window.PM_DATA={"secciones":[{"nombre":"Alapok","grupos":[{"nombre":"Mozgástani alapok","icono":"🧭","temas":[1,2,3,4]},{"nombre":"Állapotfelmérés","icono":"📋","temas":[5,6,7,8,9]}]},{"nombre":"Speciális tesztek régiónként","grupos":[{"nombre":"Váll","icono":"💪","temas":[10,11,12]},{"nombre":"Könyök, csukló és kéz","icono":"✋","temas":[13,14]},{"nombre":"Gerinc és medence","icono":"🦴","temas":[15,16,17]},{"nombre":"Csípő és térd","icono":"🦵","temas":[18,19,20]},{"nombre":"Boka és láb","icono":"🦶","temas":[21]},{"nombre":"Neurológiai tesztek","icono":"🧠","temas":[22]}]},{"nombre":"Sérülések és rehabilitáció","grupos":[{"nombre":"Váll","icono":"💪","temas":[23,24,25]},{"nombre":"Sport, inak és izmok","icono":"🏃","temas":[26,27,28,29,30]},{"nombre":"Ortopédia és traumatológia","icono":"🦴","temas":[31,32,33]},{"nombre":"Gerinc","icono":"🧍","temas":[34,35,36]},{"nombre":"Neurológia","icono":"🧠","temas":[37,38,39,40,41]}]},{"nombre":"Kezelések és beavatkozások","grupos":[{"nombre":"Technikák és fizikoterápia","icono":"🤲","temas":[42,43,44,45,46,47]},{"nombre":"Mozgásterápia és szakterületek","icono":"🩺","temas":[48,49,50,51,52,53]},{"nombre":"Klinikai esetek","icono":"🧩","temas":[54]}]}],"temas":{"1":{"id":1,"title":"Síkok és tengelyek","lead":"A test mozgásait három alapsíkkal és a rájuk merőleges mozgástengelyekkel írjuk le. A síkok és tengelyek párosítása minden vizsgálat, dokumentáció és mozgáselemzés alapja.","sheet":{"kind":"basics","items":[{"h":"Kiinduló helyzet","t":"A síkokat és tengelyeket az anatómiai alaphelyzetből definiáljuk. A ROM-mérés 0°-a a neutrális null helyzet (alkar középállásban), ezért figyelj a kettő közti különbségre."},{"h":"Sagittalis sík","t":"A testet jobb és bal félre osztja. Itt történik a flexió–extenzió, valamint a boka dorsalflexiója és plantarflexiója; a mozgástengely a frontális (haránt) tengely."},{"h":"Frontalis sík","t":"A testet elülső és hátsó részre osztja. Itt történik az abdukció–addukció és a törzs oldalra hajlítása; a mozgástengely a sagittalis tengely."},{"h":"Transversalis sík","t":"A testet felső és alsó részre osztja. Itt történik a belső és külső rotáció, a törzs rotációja, a váll horizontális flexiója és extenziója; a tengely a longitudinális (hossz-) tengely."},{"h":"Sík és tengely viszonya","t":"A mozgástengely mindig merőlegesen halad át a mozgás síkján. Ha a síkot és tengelyt párban tanulod, egy ismeretlen mozgást is könnyen besorolsz."},{"h":"Összetett mozgások","t":"A valódi mozgások több síkban zajlanak. A járást vagy a dobást síkonként külön figyeljük meg, majd együttesen elemezzük."}]},"keypoints":["Sagittalis sík = flexió–extenzió, tengely: frontális (haránt) tengely","Frontalis sík = abdukció–addukció, tengely: sagittalis tengely","Transversalis sík = rotáció, tengely: longitudinális (hossz-) tengely","A mozgástengely mindig merőleges a mozgás síkjára","A mozgáselemzésben síkonként külön figyelj meg"],"case":{"text":"20 éves atléta. Hanyatt fekvésben az egyenes alsó végtagot előre emeli (csípőízület). Ezt a mozgást szeretnéd dokumentálni. Melyik síkban és tengely körül írod le?","answer":"A csípő előreemelése flexió: sagittalis síkú mozgás, a tengely a frontális (haránt) tengely. Hogy ne keverd a frontalis síkú abdukcióval, azt nézd, hogy a mozgás a testet jobb és bal félre osztó síkban zajlik-e."},"questions":[{"level":"Alap","q":"Melyik síkban történik az abdukció és az addukció?","options":["Sagittalis sík","Frontalis sík","Transversalis sík","Ferde sík"],"answer":1,"exp":"A frontalis sík a testet elülső és hátsó részre osztja; ebben történik az abdukció–addukció. A mozgástengely a sagittalis tengely."},{"level":"Alap","q":"Mi a transversalis síkban végbemenő rotáció mozgástengelye?","options":["Frontális (haránt) tengely","Sagittalis tengely","Ferde tengely","Longitudinális (hossz-) tengely"],"answer":3,"exp":"A transversalis síkú mozgás (rotáció) a síkra merőleges longitudinális (hossz-) tengely körül történik."},{"level":"Középhaladó","q":"Melyik mozgás történik a sagittalis síkban?","options":["A törzs oldalra hajlítása","A boka dorsalflexiója","A csípő külső rotációja","A váll abdukciója"],"answer":1,"exp":"A dorsal- és plantarflexió a flexióhoz–extenzióhoz hasonlóan sagittalis síkú. Az oldalra hajlítás és az abdukció frontalis, a külső rotáció transversalis síkú."},{"level":"Középhaladó","q":"Melyik síkban történik a váll horizontális flexiója?","options":["Sagittalis sík","Frontalis sík","Transversalis sík","Egyik síkhoz sem tartozik"],"answer":2,"exp":"A horizontális flexió–extenzió során a 90°-ban abdukált felső végtag a transversalis síkban mozog, a tengely a longitudinális tengely."},{"level":"Klinikai","q":"A váll külső rotációját lógatott felkarral, 90°-ban hajlított könyökkel méred. Melyik sík–tengely páros helyes?","options":["Sagittalis sík – frontális tengely","Frontalis sík – sagittalis tengely","Transversalis sík – longitudinális tengely","Transversalis sík – frontális tengely"],"answer":2,"exp":"Lógatott karral a váll belső és külső rotációja transversalis síkú mozgás, a felkar hossztengelye (longitudinális tengely) körül."},{"level":"Klinikai","q":"Járásmegfigyelésnél támaszfázisban a medence a lendülő oldal felé süllyed. Főként melyik síkot figyeled?","options":["Frontalis sík","Sagittalis sík","Transversalis sík","A sík nem határozható meg"],"answer":0,"exp":"A medence oldalirányú dőlése frontalis síkú mozgás, elölről vagy hátulról figyeljük meg. A m. gluteus medius gyengeségére utal."}],"seccion":"Alapok","grupo":"Mozgástani alapok","icono":"🧭","mapa":"img/mapas/t01.jpg","fichas":[],"secuencias":[]},"2":{"id":2,"title":"Biomechanika","lead":"A biomechanika az erő és a mozgás kapcsolatán keresztül értelmezi a test mozgását. Az emelők, a forgatónyomaték és a tömegközéppont ismerete pontosabbá teszi a terápiás gyakorlatok terhelését.","sheet":{"kind":"basics","items":[{"h":"Forgatónyomaték","t":"Az ízületet forgató hatás a forgatónyomaték. Az erő nagyságának és az erőkarnak (a forgástengely és az erő hatásvonala közti merőleges távolság) a szorzata."},{"h":"A háromféle emelő","t":"Elsőfajú emelőnél a forgáspont, másodfajúnál a teher, harmadfajúnál az erő van középen. A legtöbb izom harmadfajú emelőként működik: sebességre és mozgásterjedelemre kedvező."},{"h":"Tömegközéppont","t":"Állásban a test tömegközéppontja a medencében, a S2 csigolya kissé előtt van. Minél inkább az alátámasztási felületen belül esik a súlyvonal, annál stabilabb a testtartás."},{"h":"Kinetikai lánc","t":"Nyitott kinetikai láncban (OKC) a disztális rész szabadon mozog, zártban (CKC) a talajhoz vagy más felülethez rögzített. A célnak megfelelően választunk."},{"h":"Izomműködési módok","t":"Koncentrikus kontrakcióban az izom rövidülve, excentrikusban nyúlva fejt ki erőt. Az izometriás kontrakció ízületi mozgás nélkül zajlik."},{"h":"Klinikai alkalmazás","t":"Minél disztálisabban van a súly, annál hosszabb az erőkar és nagyobb a terhelés. A gyakorlat terhelése nemcsak a súllyal, hanem annak helyével is szabályozható."}]},"keypoints":["A forgatónyomaték = erő × erőkar","A legtöbb izom harmadfajú emelő (sebességre kedvező)","Stabil a testtartás, ha a súlyvonal az alátámasztáson belül esik","A legtöbb leengedő mozgást excentrikus kontrakció vezérli","A terhelés a súly helyével is szabályozható"],"case":{"text":"65 éves nő, térdartrózis. Hanyatt fekvésben, a bokára rögzített súlyzómandzsettával végez SLR-gyakorlatot, de gyorsan elfárad és kompenzáló mozgások jelennek meg.","answer":"Ha a súlyt a lábszár proximális részére helyezed, rövidül az erőkar, így azonos súllyal is csökken a csípőflexiós forgatónyomaték. A fájdalmat és a kompenzációt figyelve fokozatosan emeld a terhelést; csak az ismétlésszámot ne növeld."},"questions":[{"level":"Alap","q":"Melyik emelőnél van a forgáspont az erő és a teher között?","options":["Elsőfajú emelő","Másodfajú emelő","Harmadfajú emelő","Kerék és tengely"],"answer":0,"exp":"Az elsőfajú emelőnél a forgáspont van középen; tipikus példa a fej előre-hátra egyensúlya."},{"level":"Alap","q":"Melyik emelőtípus tipikus példája a könyök m. biceps brachii általi flexiója?","options":["Elsőfajú emelő","Másodfajú emelő","Harmadfajú emelő","Csiga"],"answer":2,"exp":"Az izom tapadása (erő) a könyökízület (forgáspont) és a kézben lévő súly (teher) között van, ezért harmadfajú emelő."},{"level":"Középhaladó","q":"Melyik páros határozza meg az ízületi forgatónyomaték nagyságát?","options":["Az erő nagysága és a sebesség","Az izomhossz és a keresztmetszet","Az erő nagysága és az erőkar","A tömeg és a hőmérséklet"],"answer":2,"exp":"A forgatónyomaték az erő nagyságának és a forgástengely–hatásvonal merőleges távolságának (erőkar) szorzata."},{"level":"Középhaladó","q":"Milyen kontrakciót végez főként a m. quadriceps femoris a guggolás leengedő fázisában?","options":["Koncentrikus kontrakció","Izometriás kontrakció","Izokinetikus kontrakció","Excentrikus kontrakció"],"answer":3,"exp":"Leengedéskor a térd flektálódik, a m. quadriceps nyúlva tartja a testsúlyt, ez excentrikus kontrakció."},{"level":"Klinikai","q":"Egy idős páciens megbillen, amikor egy előtte lévő tárgyért nyúl. Mi a legjobb magyarázat a tömegközéppont szempontjából?","options":["A súlyvonal az alátámasztás széléhez közelített","Túl széles lett az alátámasztási felület","Túl alacsonyra került a tömegközéppont","Nőtt a koncentrikus kontrakció"],"answer":0,"exp":"Előrenyúláskor a súlyvonal az alátámasztási felület elülső széléhez közelít, így csökken a stabilitás."},{"level":"Klinikai","q":"Ülésben súlyzómandzsettával térdextenziót végeztetsz. Hogyan csökkented a terhelést a súly megváltoztatása nélkül?","options":["A súlyt a bokára teszem","A súlyt a lábszár proximális részére teszem","Gyorsítom a mozgást","Tovább tartatom a véghelyzetben"],"answer":1,"exp":"Ha a súlyt közelebb viszed a térdhez, rövidül az erőkar, így azonos súllyal kisebb a forgatónyomaték."}],"seccion":"Alapok","grupo":"Mozgástani alapok","icono":"🧭","mapa":"img/mapas/t02.jpg","fichas":[],"secuencias":[]},"3":{"id":3,"title":"Mozgástartomány (goniometria)","lead":"A mozgástartomány (ROM) mérésekor goniométerrel, fokban rögzítjük az ízület mozgásterjedelmét. Ez a károsodás felmérésének, a célkitűzésnek és a hatékonyság értékelésének alapja.","sheet":{"kind":"basics","items":[{"h":"Alapszabályok","t":"A neutrális null helyzet a 0°, és 5°-os lépésekben rögzítünk. Elsősorban passzív mozgással mérünk; ha aktívan mértél, ezt külön jelöld."},{"h":"Rögzített és mozgó szár","t":"A goniométer két szárát az adott ízületre előírt rögzített és mozgó karhoz igazítsd, a középpontját pedig az ízület mozgástengelyére."},{"h":"Referenciaértékek","t":"Általános referenciaértékek (neutrális null módszer): váll flexió és abdukció 180°, könyök flexió 150°, csípő flexió 120°, abdukció 45°, térd flexió 135°. Mindig vesd össze az ellenoldallal."},{"h":"Kompenzáló mozgások","t":"A törzs hátrahajlása vagy a medence dőlése túl nagy értéket ad. A proximális részt stabilan rögzítsd, és a kompenzációt kizárva mérj."},{"h":"Végérzés (end feel)","t":"Ellenőrizd a véghelyzeti ellenállás jellegét (csontos, lágyrész-, kötőszövetes) és a fájdalmat, ebből következtess a mozgást korlátozó tényezőre."},{"h":"Dokumentáció, újramérés","t":"Rögzítsd a mérési helyzetet, hogy passzív vagy aktív mérés volt-e, és a fájdalom megjelenésének szögét. Az újramérés azonos helyzetben és módszerrel összevethető."}]},"keypoints":["A 0° a neutrális null helyzet, 5°-os lépésekben rögzíts","Alapesetben passzív mérés; ha aktív, jelöld","Rögzítsd a proximális részt, zárd ki a kompenzációt","A referenciaérték csak irányadó, mindig hasonlítsd az ellenoldalhoz","A végérzésből és a fájdalomból következtess a korlátozó tényezőre"],"case":{"text":"40 éves férfi, periarthritis humeroscapularis. A vállflexió mérése közben a törzs hátrahajlik, és a mért érték szinte megegyezik az ép oldaléval.","answer":"Valószínűleg a törzsextenziós kompenzáció miatt túl nagy az érték. Rögzítsd a törzset és mérj újra, rögzítsd a fájdalom megjelenésének szögét és a végérzést is. Kompenzációval mért érték alapján ne mondd, hogy javult."},"questions":[{"level":"Alap","q":"Mennyi a váll flexiójának referenciaértéke?","options":["90°","120°","150°","180°"],"answer":3,"exp":"A váll flexiójának és abdukciójának referenciaértéke egyaránt 180°."},{"level":"Alap","q":"Mennyi a boka dorsalflexiójának referenciaértéke?","options":["10°","20°","30°","45°"],"answer":1,"exp":"A boka dorsalflexiójának referenciaértéke 20° (plantarflexió 50°). Mindig a középhelyzetből (0°) mérj."},{"level":"Középhaladó","q":"Melyik a ROM-mérés helyes alapelve?","options":["Aktív mozgással mérünk","1°-os lépésekben rögzítünk","A neutrális null helyzet a 0°","Nem kell az ellenoldallal összevetni"],"answer":2,"exp":"A neutrális null helyzet a 0°; alapesetben passzívan mérünk, 5°-os lépésekben, és összevetjük az ellenoldallal."},{"level":"Középhaladó","q":"Mit jelez a véghelyzetben kemény, hirtelen megálló csontos végérzés?","options":["Izomspazmust","Csont-csont érintkezést","Az ízületi tok feszülését","Lágyrészek érintkezését"],"answer":1,"exp":"A csontos végérzés a csontok ütközésekor érzett megállás; normálisan a könyök extenziója a tipikus példa."},{"level":"Klinikai","q":"A csípőabdukció mérése közben a medence megdől, és túl nagy értéket kapsz. Mi az első teendőd?","options":["Így rögzítem az értéket","Rögzítem a medencét és újramérek","Aktív mozgással mérek","Abbahagyom a mérést"],"answer":1,"exp":"A medence kompenzációja túl nagy abdukciós szöget ad. Rögzítsd a medencét, és mérj újra."},{"level":"Klinikai","q":"Térdműtét után a passzív flexió véghelyzetében fájdalom jelentkezik. Mi a legmegfelelőbb dokumentáció?","options":["Csak a szöget rögzítem","Az ép oldal értékét rögzítem","Amíg fáj, nem rögzítek","A fájdalom megjelenésének szögét is rögzítem"],"answer":3,"exp":"A ROM-érték mellett a fájdalom kezdetének szöge és jellege segít a korlátozó tényező felmérésében és az újraértékelésben."}],"seccion":"Alapok","grupo":"Mozgástani alapok","icono":"🧭","mapa":"img/mapas/t03.jpg","fichas":[],"secuencias":[]},"4":{"id":4,"title":"Izomerő-vizsgálat 0–5","lead":"A manuális izomtesztelés (MMT) a gravitáció és a kézi ellenállás segítségével 0–5 közötti, hatfokozatú skálán értékeli az izomerőt. Megmutatja a gyengeség mértékét és eloszlását.","sheet":{"kind":"basics","items":[{"h":"A hat fokozat","t":"0: nincs kontrakció; 1: csak kontrakció; 2: teljes ROM a gravitáció kiiktatásával; 3: teljes ROM a gravitáció ellenében; 4: közepes ellenállással szemben; 5: maximális ellenállással szemben, normál erő."},{"h":"A vizsgálat sorrendje","t":"Először antigravitációs helyzetben nézd meg, sikerül-e a 3-as fokozat. Ha igen, ellenállással döntsd el a 4-et és az 5-öt; ha nem, gravitáció nélküli helyzetben a 2-es vagy kisebb fokozatot."},{"h":"Az ellenállás adása","t":"Az ellenállást a mozgásiránnyal szemben, a testszakasz disztális részére add. Ne hirtelen, hanem fokozatosan növeld, és figyeld, meg tudja-e tartani."},{"h":"Rögzítés és kompenzáció","t":"Rögzítsd a proximális részt, és figyeld, nem jelenik-e meg más izmok kompenzáló mozgása. Ha kompenzációval mozdult, nem adhatod meg az adott fokozatot."},{"h":"A 3-as fokozat jelentése","t":"A 3-as fokozat az a határ, ahol a testszakasz saját súlya ellenében mozgatható: ez a „gravitációs határ”. A funkcionális mozgások megítélésében is irányadó."},{"h":"Korlátok","t":"Az MMT szubjektív elemeket tartalmaz, a 4-es fölötti különbségeket nehezen érzékeli. Fájdalom vagy kóros izomtónus esetén ezt is rögzítsd a lelettel együtt."}]},"keypoints":["Először a gravitáció ellenében ellenőrizd a 3-as fokozatot","A 3-as fokozat a „gravitációs határ”","Az ellenállást a mozgással szemben, disztálisan add","Rögzítsd a proximális részt, ne hagyd ki a kompenzációt","Központi idegrendszeri betegségben ne az MMT legyen az egyetlen mérés"],"case":{"text":"70 éves férfi, kórházi fekvés miatti inaktivitás. Ülésben teljes mozgásterjedelemben extendálja a térdét, de a lábszár disztális részére adott enyhe ellenállást már nem tudja megtartani.","answer":"A gravitáció ellenében teljes ROM-ban mozog, ellenállással szemben nem, ezért 3-as fokozat. Ne adj hirtelen erős ellenállást, és figyelj a kompenzációra, például a törzs hátradöntésére."},"questions":[{"level":"Alap","q":"Melyik fokozat: „a kontrakció látható, tapintható, de ízületi mozgás nincs”?","options":["0-s fokozat","1-es fokozat","2-es fokozat","3-as fokozat"],"answer":1,"exp":"Az 1-es fokozatban az izomkontrakció látható vagy tapintható, de ízületi mozgás nem jön létre."},{"level":"Alap","q":"Melyik fokozat: teljes ROM a gravitáció ellenében, de ellenállással szemben nem?","options":["4-es fokozat","2-es fokozat","3-as fokozat","5-ös fokozat"],"answer":2,"exp":"A 3-as fokozatban a gravitáció ellenében teljes ROM-ban mozog; ez a „gravitációs határ”."},{"level":"Középhaladó","q":"Melyik fokozatot ellenőrizzük általában elsőként az MMT során?","options":["1-es fokozat","5-ös fokozat","0-s fokozat","3-as fokozat"],"answer":3,"exp":"Először antigravitációs helyzetben nézzük a 3-as fokozatot; ettől függ, hogy ellenállást adunk, vagy gravitáció nélküli helyzetbe váltunk."},{"level":"Középhaladó","q":"Hová adod az ellenállást az MMT során?","options":["Közvetlenül az ízület fölé","A testszakasz proximális részére","A testszakasz disztális részére","A rögzített testrészre"],"answer":2,"exp":"Az ellenállást a mozgásiránnyal szemben, a testszakasz disztális részére adjuk, ahol hosszabb az erőkar."},{"level":"Klinikai","q":"Oldalfekvésben nem tudja abdukcióval felemelni az alsó végtagot, hanyatt fekve viszont teljes ROM-ban abdukál. Melyik fokozat?","options":["1-es fokozat","2-es fokozat","3-as fokozat","4-es fokozat"],"answer":1,"exp":"Antigravitációs helyzetben (oldalfekvés) nem megy, gravitáció nélkül (hanyatt fekve) teljes ROM-ban igen: 2-es fokozat."},{"level":"Klinikai","q":"Erősen spasztikus hemiparetikus páciens felső végtagi erejét mérnéd. Melyik a legjobb megközelítés?","options":["Az MMT önmagában nehezen értékelhető","Az 5-ös fokozat legyen a cél","Erős ellenállással döntök","Az ép oldalt nem kell vizsgálni"],"answer":0,"exp":"Központi idegrendszeri betegségben az izomtónus és a szinergiák miatt az MMT feltételei nem teljesülnek; a bénulás értékelésére más skálát is használj."}],"seccion":"Alapok","grupo":"Mozgástani alapok","icono":"🧭","mapa":"img/mapas/t04.jpg","fichas":[],"secuencias":[]},"5":{"id":5,"title":"Anamnézis","lead":"Az anamnézis során kikérdezzük a panaszok lefolyását, jellegét és a páciens életkörülményeit, és hipotézist állítunk fel. Ez határozza meg a további vizsgálatok kiválasztását és a biztonsági szűrést.","sheet":{"kind":"basics","items":[{"h":"Cél","t":"A fő panaszból és a lefolyásból hipotézist állítunk fel, és rangsoroljuk a vizsgálatokat. Közben szűrjük az orvosi továbbküldést igénylő vészjeleket is."},{"h":"Fő panasz, jelen betegség","t":"A fő panaszt a páciens szavaival rögzítsd. Kérdezz rá a kezdetre és kiváltó okra (trauma vagy fokozatos), majd a lefolyásra (javul, romlik, változatlan)."},{"h":"Fájdalomfelmérés","t":"Tisztázd a fájdalom helyét, jellegét, erősségét (pl. NRS), a rontó és enyhítő tényezőket, a napi ingadozást és az éjszakai fájdalmat."},{"h":"Előzmények, gyógyszerek","t":"Kérdezz rá a korábbi betegségekre, műtétekre, társbetegségekre és gyógyszerekre. A véralvadásgátló és a szteroid szedése óvatosságot igényel a kezelésnél."},{"h":"Életkörülmények","t":"Kérdezz a munkáról, a családi szerepről, a lakókörnyezetről és az aktivitásról. A páciens és a család igényeit, céljait építsd be a célkitűzésbe."},{"h":"Kérdezéstechnika","t":"Nyitott kérdésekkel kezdj, zárt kérdésekkel pontosíts. Kerüld a szakszavakat; ha összefoglalva visszamondod, elkerülöd a félreértéseket."}]},"keypoints":["A fő panaszt a páciens saját szavaival rögzítsd","Mindig kérdezz rá a kiváltó okra és a lefolyásra","Szűrd a vészjeleket: éjszakai fájdalom, fogyás","A gyógyszerek (pl. véralvadásgátló) óvatosságot igényelnek","Nyitott kérdéssel kezdj, zárttal pontosíts"],"case":{"text":"55 éves férfi, 2 hónapja tartó derékfájás. Elmondja: „Mostanában éjjel sem tudok aludni a fájdalomtól. Pedig semmit nem csináltam, mégis lefogytam 5 kilót.”","answer":"A pihenésre nem enyhülő éjszakai fájdalom és a megmagyarázatlan fogyás vörös zászló. A mozgásterápia megkezdése előtt jelezd és egyeztesd az orvossal. Az anamnézisben talált vészjelet ne írja felül egy későbbi vizsgálati eredmény."},"questions":[{"level":"Alap","q":"Mit kérdezel ki elsőként, és rögzítesz a páciens saját szavaival?","options":["Korábbi betegségek","Fő panasz","Családi anamnézis","Gyógyszerek"],"answer":1,"exp":"A fő panasz az, ami a pácienst leginkább zavarja; értelmezés nélkül, a saját szavaival rögzítjük."},{"level":"Alap","q":"Melyik módszerrel kéred, hogy a páciens 0–10 közötti számmal jelölje a fájdalom erősségét?","options":["MMT","ROM","NRS","ADL"],"answer":2,"exp":"Az NRS (numerikus értékelő skála) a fájdalom erősségét 0–10 közötti számmal fejezi ki."},{"level":"Középhaladó","q":"Melyik nyitott kérdés?","options":["„A jobb oldalon fáj?”","„Éjjel fáj?”","„Szed gyógyszert?”","„Mikor szokott fájni?”"],"answer":3,"exp":"A nyitott kérdésre nem lehet igennel vagy nemmel felelni, így több információt kapsz a pácienstől."},{"level":"Középhaladó","q":"Melyik információt kell különösen tisztáznod az anamnézisben, mert a kezelésnél óvatosságot igényel?","options":["Véralvadásgátló szedése","Domináns kéz","Munkába járás módja","Hobbik"],"answer":0,"exp":"A véralvadásgátló vérzés- és bevérzésveszéllyel jár, ezért óvatosságot igényel, például manuális technikáknál."},{"level":"Klinikai","q":"Derékfájós páciens: „Éjjel sem tudok aludni a fájdalomtól, és lefogytam 5 kilót.” Mi a legmegfelelőbb teendő?","options":["Azonnal elkezdem a mozgásterápiát","Hőterápiával figyelem a lefolyást","Jelzem és egyeztetek az orvossal","A következő alkalomig várok"],"answer":2,"exp":"A pihenésre nem enyhülő éjszakai fájdalom és a megmagyarázatlan fogyás vörös zászló; kezelés előtt egyeztess az orvossal."},{"level":"Klinikai","q":"70 éves, csontritkulásos nő. Elesése óta fáj a csípője, és nem tud járni. Mire gondolsz először?","options":["Izomgyengeség okozta fájdalom","Törés lehetősége","Az artrózis rosszabbodása","Pszichés tényezők"],"answer":1,"exp":"Csontritkulásban elesés utáni fájdalom és járásképtelenség esetén törésre gondolj, és az orvosi kivizsgálás az első."}],"seccion":"Alapok","grupo":"Állapotfelmérés","icono":"📋","mapa":"img/mapas/t05.jpg","fichas":[],"secuencias":[]},"6":{"id":6,"title":"Vörös zászlók","lead":"A vörös zászlók olyan figyelmeztető jelek, amelyek súlyos, rejtett betegségre utalhatnak. Ha ilyet észlelsz, a gyógytorna folytatása előtt egyeztess az orvossal.","sheet":{"kind":"basics","items":[{"h":"Meghatározás","t":"Sürgős kórállapotra (daganat, fertőzés, törés, cauda equina szindróma) utaló jelek. Egyenként kevésbé, együttesen előfordulva nagyobb a súlyuk."},{"h":"Daganat","t":"Kérdezz rá a korábbi daganatos betegségre, a megmagyarázatlan fogyásra és a pihenésre sem enyhülő éjszakai fájdalomra. Vedd figyelembe az életkort és az általános állapotot is."},{"h":"Fertőzés","t":"Figyelj a lázzal járó hát- és derékfájásra, az immunszupprimált állapotra, a közelmúltbeli fertőzésre vagy invazív beavatkozásra."},{"h":"Törés","t":"Erős trauma után, illetve csontritkulásban már kisebb esés utáni fájdalomnál gondolj törésre. Kérdezz rá a tartós szteroidszedésre is."},{"h":"Cauda equina szindróma","t":"A hólyag- és végbélzavar, a nyeregérzéskiesés és a progrediáló alsó végtagi gyengeség sürgős állapot: azonnal értesítsd az orvost."},{"h":"Teendő","t":"Dokumentáld a leletet és a lefolyást, jelezd és egyeztesd az orvossal. A pácienst ne ijeszd meg; nyugodtan magyarázd el, miért szükséges az orvosi vizsgálat."}]},"keypoints":["A pihenésre sem enyhülő éjszakai fájdalom figyelmeztető jel","A megmagyarázatlan fogyás daganatra utalhat","Hólyag- és végbélzavar, nyeregérzéskiesés: sürgős","Trauma vagy csontritkulás esetén gondolj törésre","Vörös zászló esetén kezelés előtt egyeztess az orvossal"],"case":{"text":"45 éves nő, derékfájás és jobb alsó végtagi fájdalom. Elmondja, hogy ma reggel óta nehezen tud vizelni, és zsibbad a végbélnyílás környéke.","answer":"A hólyag- és végbélzavar és a nyeregterületi érzészavar cauda equina szindrómára utal. Ne folytasd a vizsgálatot vagy a gyakorlatokat, azonnal értesítsd az orvost. A „várjunk és figyeljük” hozzáállás itt kerülendő."},"questions":[{"level":"Alap","q":"Melyik vörös zászló a hát- és derékfájásban?","options":["Mozgásra fokozódó derékfájás","Megmagyarázatlan fogyás","Hosszú üléstől fokozódó fájdalom","Edzés utáni izomláz"],"answer":1,"exp":"A megmagyarázatlan fogyás az egyik vörös zászló, daganatos betegségre utalhat."},{"level":"Alap","q":"Mi a helyes teendő vörös zászló észlelésekor?","options":["Csökkentett intenzitással folytatom","Fizikoterápiára váltok","A következő alkalomig várok","Kezelés előtt egyeztetek az orvossal"],"answer":3,"exp":"Vörös zászló esetén a gyógytorna folytatása előtt egyeztess az orvossal."},{"level":"Középhaladó","q":"Melyik leletpáros utal cauda equina szindrómára?","options":["Hólyag-végbélzavar és nyeregérzéskiesés","Nyakfájás és vállmerevség","Térdduzzanat és lépcsőn fellépő fájdalom","Éjszakai vállfájás és emelési korlát"],"answer":0,"exp":"A hólyag-végbélzavar és a nyeregterület (gát, végbélnyílás környéke) érzéskiesése a cauda equina kompressziójának sürgős jele."},{"level":"Középhaladó","q":"Melyik helyzetben gondolsz leginkább törésre?","options":["Irodai munka utáni derékfeszülés","Edzés utáni izomláz","Csontritkulásos páciens hátfájása esés után","Hideg napokon jelentkező térdmerevség"],"answer":2,"exp":"Csontritkulásban már kis erőbehatásra is eltörhet a csont, ezért esés utáni fájdalomnál törésre gondolj."},{"level":"Klinikai","q":"Derékfájós páciens: „Ma reggel óta nehezen vizelek, és zsibbad a végbélnyílás körül.” Mi a teendő?","options":["Végigviszem a vizsgálatot","Elkezdem a törzsgyakorlatokat","Azonnal értesítem az orvost","Egy hétig figyelem a lefolyást"],"answer":2,"exp":"A hólyag-végbélzavar és a nyeregterületi érzészavar cauda equina szindrómára utal: azonnal értesítsd az orvost."},{"level":"Klinikai","q":"68 éves férfi, daganatos előzmény. Egy hónapja pihenésre sem enyhülő éjszakai hátfájása van. Mi a megítélésed?","options":["Testtartási eredetű fájdalom","Orvosi egyeztetést igénylő jel","Erősítéssel javuló fájdalom","Hőterápiával követhető fájdalom"],"answer":1,"exp":"Daganatos előzmény és pihenésre nem enyhülő éjszakai fájdalom együtt áttétet sem zár ki, ezért orvosi egyeztetés szükséges."}],"seccion":"Alapok","grupo":"Állapotfelmérés","icono":"📋","mapa":"img/mapas/t06.jpg","fichas":[],"secuencias":[]},"7":{"id":7,"title":"Testtartás-vizsgálat","lead":"A testtartás-vizsgálat során álló és ülő helyzetben megfigyeljük a test vonalvezetését, és támpontokat keresünk a problémához. A tünetekkel való összefüggést mindig más vizsgálatokkal kell igazolni.","sheet":{"kind":"basics","items":[{"h":"Cél","t":"Felmérjük a tartási eltéréseket, és hipotézist állítunk fel az izomrövidüléssel, izomgyengeséggel és a fájdalommal való kapcsolatukról."},{"h":"Oldalnézeti referencia","t":"Ideális állásban a súlyvonal a fülcimpán, az acromionon, a trochanter majoron, a térdízület elülső részén (a patella mögött) és a külső boka előtt halad át."},{"h":"Hátulnézet","t":"Figyeld a fej dőlését, a váll és a medence magasságát, a gerinc oldalirányú eltérését és az alsó végtagok aszimmetriáját. Szükség esetén előrehajlásban is ellenőrizd."},{"h":"Hibás tartások","t":"Ilyen a kerek hát, az előretolt fejtartás, a fokozott medencedőléssel és ágyéki lordózissal járó tartás és a lapos hát. Az érintett izmok rövidülésével, gyengeségével együtt értékeld."},{"h":"Értelmezés","t":"Sokaknak van tartási eltérése tünetek nélkül, ezért a lelet önmagában nem bizonyítja a fájdalom okát. ROM- és izomerő-vizsgálattal igazold."},{"h":"Dokumentáció","t":"Rögzítsd a megfigyelés irányát, a testhelyzetet és a tájékozódási pontok helyzetét. Fotónál mindig azonos körülmények között készíts felvételt az összevetéshez."}]},"keypoints":["Oldalról, hátulról és elölről is figyeld meg","A súlyvonal a fülcimpán, acromionon, trochanter majoron halad át","Hátulról a váll- és medencemagasság oldalkülönbségét nézd","Előrehajláskor a bordapúp strukturális scoliosisra utal","A testtartás alapján ne mondd ki a fájdalom okát"],"case":{"text":"30 éves nő, irodai munka. Nyakfájása van, oldalról nézve a fülcimpa egyértelműen az acromion előtt helyezkedik el.","answer":"Ez előretolt fejtartás. A tartás alapján azonban ne mondd ki az okot: vizsgáld a nyaki ROM-ot, a tünetet kiváltó mozgásokat és a neurológiai jeleket (zsibbadás, gyengeség). Neurológiai tünet esetén egyeztess az orvossal."},"questions":[{"level":"Alap","q":"Ideális állásban oldalról nézve hol halad át a súlyvonal?","options":["Az orrhegyen","A lapocka alsó szögletén","A fülcimpán","A sarokcsont hátsó szélén"],"answer":2,"exp":"Ideális esetben a súlyvonal a fülcimpán, az acromionon, a trochanter majoron, a térd elülső részén és a külső boka előtt halad át."},{"level":"Alap","q":"Mit vizsgálsz főként hátulnézetben?","options":["Előretolt fejtartást","A váll és a medence magasságkülönbségét","Az ágyéki lordózis mértékét","A térd hiperextenzióját"],"answer":1,"exp":"Hátulról az oldalkülönbségeket figyeljük: a váll és a medence magasságát, a gerinc oldalirányú eltérését."},{"level":"Középhaladó","q":"Ideális állásban mi igaz az oldalnézeti súlyvonalra?","options":["A külső boka mögött halad","A térdízület mögött halad","A lapocka belső szélén halad","A trochanter majoron halad át"],"answer":3,"exp":"A súlyvonal a trochanter majoron, a térdízület elülső részén és a külső boka előtt halad át."},{"level":"Középhaladó","q":"Melyik a testtartás-vizsgálat helyes értelmezése?","options":["Az eltérés a fájdalom oka","Más vizsgálattal igazolom a kapcsolatot","Egy irányból elég megfigyelni","A fotókat mindig más körülmények között készítem"],"answer":1,"exp":"Tartási eltérés tünetmentes embereknél is előfordul, ezért ROM- és izomerő-vizsgálattal igazold az összefüggést."},{"level":"Klinikai","q":"Nyakfájós páciensnél a fülcimpa egyértelműen az acromion előtt van. Mi a legmegfelelőbb következő lépés?","options":["Megvizsgálom a nyaki ROM-ot és a neurológiai jeleket","Csak tartásjavító tanácsot adok","Azonnal trakciót alkalmazok","Csak megfigyelem a lefolyást"],"answer":0,"exp":"Az előretolt fejtartás csak támpont. Vizsgáld a ROM-ot és a neurológiai jeleket, és értékeld a tünetekkel való összefüggést."},{"level":"Klinikai","q":"Hátulról váll- és medence-magasságkülönbség látszik, előrehajláskor egyoldali bordapúp. Mire gondolsz?","options":["Előretolt fejtartás","Kerek hát","Strukturális scoliosis","Lapos hát"],"answer":2,"exp":"Az előrehajláskor látható bordapúp a csigolyák rotációjával járó strukturális scoliosisra utal; orvosi kivizsgálás szükséges."}],"seccion":"Alapok","grupo":"Állapotfelmérés","icono":"📋","mapa":"img/mapas/t07.jpg","fichas":[],"secuencias":[]},"8":{"id":8,"title":"Járáselemzés","lead":"A járáselemzés során a járásciklus egyes fázisaiban megfigyeljük az ízületi mozgásokat és az izomműködést, és azonosítjuk a problémát. Ez irányt ad az elesésmegelőzéshez és a mozgás javításához.","sheet":{"kind":"basics","items":[{"h":"A járásciklus","t":"Egy ciklus az egyik láb kezdeti talajfogásától ugyanazon láb következő talajfogásáig tart. Támasz- és lendítőfázisra oszlik, és két kettős támaszt tartalmaz."},{"h":"A fázisok","t":"Támaszfázis: kezdeti talajfogás, terhelésfelvétel, középső és végső támaszfázis, lendítés előtti fázis. Lendítőfázis: korai, középső és késői lendítőfázis."},{"h":"A megfigyelés menete","t":"Figyeld meg elölről, hátulról és oldalról, egyszerre egy ízületre vagy fázisra koncentrálva. Rögzítsd a sebességet, a lépéshosszt, a ritmust és a segédeszközt is."},{"h":"Jellegzetes kóros járások","t":"Trendelenburg-járás (m. gluteus medius), lépegető (steppage) járás (lógó láb kompenzációja), körző járás, járásindítási blokk (freezing), aprólépéses járás."},{"h":"Izomműködés","t":"Terhelésfelvételkor a m. quadriceps a térdflexiót, a m. tibialis anterior a lábfej leereszkedését excentrikusan fékezi. Végső támaszfázisban a m. triceps surae dolgozik."},{"h":"Mérhető vizsgálatok","t":"A 10 méteres járásteszttel és a TUG-teszttel számszerűsítheted a sebességet és a mobilitást. A megfigyeléssel együtt az elesési kockázatot is megítéled."}]},"keypoints":["Egy ciklus: talajfogástól ugyanazon láb következő talajfogásáig","Támaszfázis kb. 60%, lendítőfázis kb. 40%","Három irányból figyelj, egyszerre egy pontra","Trendelenburg-járásnál a m. gluteus mediusra gondolj","A lépegető járás a lógó láb (gyenge m. tibialis anterior) kompenzációja"],"case":{"text":"60 éves férfi, n. peroneus bénulás. Lendítőfázisban erősen flektálja a csípőt és a térdet, magasra emelve lép. Egyre gyakrabban botlik meg.","answer":"Ez a lógó lábat kompenzáló lépegető (steppage) járás. Vizsgáld a dorsalflexiós izomerőt, az érzést és az elesési kockázatot. Az ortézist az orvossal és az ortopédiai műszerésszel közösen mérlegeld, ne önállóan dönts."},"questions":[{"level":"Alap","q":"Egy járásciklusnak körülbelül hányad részét teszi ki a támaszfázis?","options":["Kb. 40%","Kb. 50%","Kb. 60%","Kb. 80%"],"answer":2,"exp":"Normál járásban a támaszfázis kb. 60%, a lendítőfázis kb. 40%."},{"level":"Alap","q":"Melyik fázisban tartja egy lábon a testsúlyt, és van a súlypont a legmagasabban?","options":["Kezdeti talajfogás","Középső támaszfázis","Lendítés előtti fázis","Középső lendítőfázis"],"answer":1,"exp":"Középső támaszfázisban a test a támaszláb fölött halad át, ekkor van a súlypont a legmagasabban."},{"level":"Középhaladó","q":"Melyik izom fékezi excentrikusan a térdflexiót terhelésfelvételkor?","options":["M. quadriceps femoris","Hamstringizmok","M. iliopsoas","M. triceps surae"],"answer":0,"exp":"Terhelésfelvételkor a térd enyhén flektálódik a lökés elnyelésére, ezt a m. quadriceps excentrikusan fékezi."},{"level":"Középhaladó","q":"Melyik izom gyengeségére gyanakszol Trendelenburg-járásnál?","options":["M. gluteus maximus","M. quadriceps femoris","M. tibialis anterior","M. gluteus medius"],"answer":3,"exp":"A m. gluteus medius gyengeségekor támaszfázisban a lendülő oldali medence lesüllyed: Trendelenburg-jel."},{"level":"Klinikai","q":"Lendítőfázisban túlzottan flektálja a csípőt és a térdet, magasra emelve lép. Mi lehet az ok?","options":["A m. quadriceps gyengesége","A m. tibialis anterior gyengesége","A m. gluteus medius gyengesége","A m. gluteus maximus gyengesége"],"answer":1,"exp":"A m. tibialis anterior gyengesége miatt lóg a láb; hogy a lábujjak ne akadjanak meg, magasra emeli: lépegető járás."},{"level":"Klinikai","q":"Parkinson-kóros páciensnél járásinduláskor és fordulásnál a láb mintha a talajhoz tapadna, nem indul. Mi ez?","options":["Körző járás","Lépegető járás","Járásindítási blokk (freezing)","Kacsázó járás"],"answer":2,"exp":"A freezing a Parkinson-kórra jellemző; főként járásinduláskor, fordulásnál és szűk helyeken jelentkezik."}],"seccion":"Alapok","grupo":"Állapotfelmérés","icono":"📋","mapa":"img/mapas/t08.jpg","fichas":[],"secuencias":[]},"9":{"id":9,"title":"Neurológiai vizsgálat","lead":"A neurológiai vizsgálat során szegmentumonként vizsgáljuk az érzést, az izomerőt és a reflexeket, és következtetünk a károsodás helyére és szintjére. A progrediáló neurológiai tünetek korai felismeréséhez is nélkülözhetetlen.","sheet":{"kind":"basics","items":[{"h":"Cél","t":"Az érzés-, izomerő- és reflexleletek együttes értékelésével eldöntjük, hogy a károsodás perifériás idegben, ideggyökben, gerincvelőben vagy agyban van-e."},{"h":"Érzésvizsgálat","t":"Vizsgáld a tapintást, a fájdalom-, hő-, helyzet- és vibrációérzést, és a dermatomák mentén hasonlítsd össze a két oldalt, valamint a proximális és disztális részt."},{"h":"Indikátorizmok","t":"C5: vállabdukció; C6: csukló dorsalflexió (extenzió); C7: könyökextenzió; L4: boka dorsalflexió; L5: öregujj-extenzió; S1: boka plantarflexió."},{"h":"Mélyreflexek","t":"Alapreflexek: bicepsreflex (C5), brachioradialis reflex (C6), tricepsreflex (C7), patellareflex (L4), Achilles-reflex (S1)."},{"h":"Felső és alsó motoneuron","t":"Felső motoneuron-károsodásban fokozott ínreflexek és kóros reflexek, alsó motoneuron-károsodásban gyengült vagy kiesett reflexek és izomatrófia láthatók."},{"h":"Figyelmeztetés","t":"Gyorsan romló izomerő, terjedő érzészavar vagy hólyag- és végbélzavar esetén haladéktalanul értesítsd az orvost. A leleteket időben követve dokumentáld."}]},"keypoints":["Az érzést, az erőt és a reflexeket mindig két oldalon vesd össze","Patellareflex: L4, Achilles-reflex: S1","Az L5-öt az öregujj-extenzió ereje és az érzés alapján ítéld meg","Fokozott reflex és kóros reflex: felső motoneuron","Progrediáló izomgyengeségnél azonnal értesítsd az orvost"],"case":{"text":"50 éves férfi, derékfájás, zsibbadás a jobb lábszár külső oldalától a lábhátig. Jobb oldalon gyengült az öregujj-extenzió, a patella- és az Achilles-reflexben nincs oldalkülönbség.","answer":"L5-ös ideggyök-károsodás valószínű. Az L5-nek nincs jellemző ínreflexe, ezért az érzés és az öregujj-extenzió ereje alapján döntesz. Romló izomerő vagy hólyag-végbélzavar esetén azonnal értesítsd az orvost."},"questions":[{"level":"Alap","q":"Melyik kóros reflex utal felső motoneuron-károsodásra?","options":["Patellareflex","Hasbőrreflex","Babinski-reflex","Cornealis reflex"],"answer":2,"exp":"A Babinski-reflex kóros reflex: a talp ingerlésére az öregujj dorsalflexióba megy; felső motoneuron-károsodásra utal."},{"level":"Alap","q":"Melyik vizsgálatban hasonlítod össze a két oldalt a dermatomák mentén?","options":["Ínreflexek","Érzésvizsgálat","MMT","ROM-mérés"],"answer":1,"exp":"A dermatoma az egyes szegmentumok által beidegzett bőrterület; az érzésvizsgálatban oldalanként és proximodisztálisan hasonlítjuk össze."},{"level":"Középhaladó","q":"Melyik szegmentumot tükrözi elsősorban az Achilles-reflex?","options":["L3","L4","L5","S1"],"answer":3,"exp":"Az Achilles-reflex főként az S1, a patellareflex főként az L4 szegmentumot tükrözi."},{"level":"Középhaladó","q":"Melyik az alsó motoneuron-károsodás lelete?","options":["Fokozott ínreflexek","Pozitív kóros reflex","Izomatrófia","Spaszticitás"],"answer":2,"exp":"Alsó motoneuron-károsodásban gyengült vagy kiesett ínreflexek, izomatrófia és csökkent izomtónus látható."},{"level":"Klinikai","q":"Zsibbadás a lábszár külső oldalától a lábhátig, gyengült öregujj-extenzió, a reflexekben nincs oldalkülönbség. Melyik a károsodás szintje?","options":["L3","L4","L5","S1"],"answer":2,"exp":"A lábszár külső oldalától a lábhátig terjedő érzés és az öregujj-extenzió L5-ös lelet. Az L5-nek nincs jellemző ínreflexe."},{"level":"Klinikai","q":"Nyakfájás és mindkét kéz zsibbadása mellett az alsó végtagon fokozottak az ínreflexek, és pozitív a Babinski-jel. Mire gondolsz?","options":["Nyaki gerincvelő-károsodás (myelopathia)","Egyetlen ideggyök károsodása","Carpalis alagút szindróma","Myofascialis fájdalom"],"answer":0,"exp":"Az alsó végtagi fokozott reflexek és a kóros reflex felső motoneuron-károsodást jeleznek; nyaki gerincvelő-kompresszióra gondolj, és küldd orvoshoz."}],"seccion":"Alapok","grupo":"Állapotfelmérés","icono":"📋","mapa":"img/mapas/t09.jpg","fichas":[],"secuencias":[]},"10":{"id":10,"title":"Rotátorköpeny","lead":"A rotátorköpeny négy izom ina, amely stabilizálja a vállízületet. Annak tesztekkel való elkülönítése, hogy melyik izom sérült, a vizsgálat és a gyógytorna kiindulópontja.","sheet":{"kind":"tests","tests":[{"name":"Jobe-teszt","alias":"empty can teszt","steps":"A beteg a lapocka síkjában 90°-os abdukcióban, belső rotációban, lefelé néző hüvelykujjal tartja a kart; a vizsgáló felülről lefelé ad ellenállást.","positive":"Fájdalom vagy gyengeség: nem tudja megtartani a kart az ellenállással szemben","tissue":"m. supraspinatus","point":"A fájdalmat és a gyengeséget külön rögzítsd. Impingement esetén is fájdalmat okozhat."},{"name":"Külső rotáció ellenállással","alias":"","steps":"90°-ban hajlított könyökkel, a test mellett lógó felkarral a beteg kifelé rotál; a vizsgáló az alkarra befelé ható ellenállást ad.","positive":"Fájdalom külső rotációkor vagy az ép oldalnál egyértelműen kisebb erő","tissue":"m. infraspinatus és m. teres minor","point":"Ha a passzívan beállított külső rotációt nem tudja megtartani (külső rotációs lag), nagy szakadásra gondolj."},{"name":"Lift-off teszt","alias":"Gerber-féle lift-off teszt","steps":"A beteg kézháta a deréktájon nyugszik; kérd meg, hogy emelje el a kezét hátrafelé a hátától.","positive":"Nem tudja elemelni a kezét a hátától, vagy fájdalom jelentkezik","tissue":"m. subscapularis","point":"Ha a belső rotációs ROM hiánya miatt a kéz nem ér a hát mögé, a belly press teszttel helyettesítsd."},{"name":"Drop arm teszt","alias":"","steps":"A vizsgáló passzívan kb. 90°-os abdukcióig emeli a kart, majd a beteg lassan leengedi.","positive":"Útközben nem tudja tartani és a kar leesik, vagy erős fájdalom","tissue":"Rotátorköpeny-szakadás (főként m. supraspinatus)","point":"Nagy szakadásra utaló jel. Önmagában ne diagnosztizálj; vesd össze más tesztekkel és képalkotással."}]},"keypoints":["A fájdalmat és a gyengeséget külön rögzítsd, és mindig hasonlítsd az ép oldalhoz","A Jobe-teszt a lapocka síkjában, lefelé néző hüvelykujjal a m. supraspinatust vizsgálja","Ellenállásos külső rotáció: m. infraspinatus és teres minor; lift-off: m. subscapularis","Egyetlen tesztből ne vonj le végső következtetést; kombináld a leleteket","Ha trauma után hirtelen nem tudja emelni a kart, irányítsd orvosi vizsgálatra"],"case":{"text":"58 éves férfi. Elesett és jobb kezére támaszkodott, azóta nem tudja emelni a jobb vállát. A passzív ROM közel megtartott, az aktív emelés nehéz. Jobe-teszt: gyengeség; drop arm teszt pozitív.","answer":"Mivel a passzív ROM megtartott és csak az aktív mozgás nehéz, kontraktúra helyett rotátorköpeny-szakadásra gondolunk. A tesztek alapján ne diagnosztizálj; irányítsd orvosi vizsgálatra és képalkotásra. Kerüld a fájdalmat kiváltó erős ellenállásos gyakorlatok ismétlését."},"questions":[{"level":"Alap","q":"Melyik izmot vizsgálja elsősorban a Jobe-teszt (lapocka síkjában 90°, lefelé néző hüvelykujj)?","options":["m. supraspinatus","m. infraspinatus","m. subscapularis","m. teres minor"],"answer":0,"exp":"A lapocka síkjában 90°-os abdukcióban, lefelé néző hüvelykujjal adott ellenállással a m. supraspinatust vizsgáljuk."},{"level":"Alap","q":"Melyik izmot vizsgálja a Gerber-féle lift-off teszt, amelyben a deréktájra tett kézhátat kell elemelni?","options":["m. teres major","m. supraspinatus","m. subscapularis","m. deltoideus"],"answer":2,"exp":"A kéz elemelése a háttól belső rotáció, így a fő belső rotátort, a m. subscapularist vizsgálja."},{"level":"Középhaladó","q":"Mit vizsgál a 90°-ban hajlított könyökkel, lógó felkarral, ellenállással szemben végzett külső rotáció?","options":["Csak a m. supraspinatust","m. infraspinatus és m. teres minor","m. subscapularis","A m. biceps brachii hosszú fejét"],"answer":1,"exp":"Az ellenállásos külső rotáció a külső rotátorok, a m. infraspinatus és a m. teres minor fájdalmát és gyengeségét mutatja."},{"level":"Középhaladó","q":"Mire utal leginkább a pozitív drop arm teszt?","options":["Elülső vállinstabilitás","A bicepsz hosszú fejének ínhüvelygyulladása","Az acromioclavicularis ízület károsodása","Rotátorköpeny-szakadás"],"answer":3,"exp":"Ha a beteg nem tudja lassan leengedni az emelt kart és az leesik, az rotátorköpeny- (főként m. supraspinatus-) szakadásra utal."},{"level":"Klinikai","q":"62 éves nő. A kezét a háta mögé tudja vinni, de elemelni a hátától nem. Az ellenállásos külső rotáció normális. Hol a legvalószínűbb a sérülés?","options":["m. supraspinatus","m. subscapularis","m. infraspinatus","m. teres minor"],"answer":1,"exp":"A lift-off teszt pozitív, a külső rotáció normális. Leginkább a belső rotátor m. subscapularis károsodására gondolunk."},{"level":"Klinikai","q":"65 éves férfi, nehezen emeli a vállát. A passzív ROM megtartott, a Jobe-teszten kifejezett gyengeség. Mi a legmegfelelőbb teendő?","options":["Maximális ellenállású erősítés kezdése","Tájékoztatás és orvosi vizsgálat kérése","Erős nyújtások ismétlése","Várakozás javaslata"],"answer":1,"exp":"Rotátorköpeny-szakadás gyanúja áll fenn; a diagnózishoz és a tervhez orvosi vizsgálat és képalkotás kell. Kerüld a nagy terhelést."}],"seccion":"Speciális tesztek régiónként","grupo":"Váll","icono":"💪","mapa":"img/mapas/t10.jpg","fichas":[{"nombre":"Jobe-teszt","img":"img/fichas/jobe.jpg"}],"secuencias":[{"nombre":"Jobe-teszt","rotulo":"Vizsgálja","texto":"m. supraspinatus","frames":["img/mov/teste-jobe-1.jpg","img/mov/teste-jobe-2.jpg","img/mov/teste-jobe-3.jpg"]}]},"11":{"id":11,"title":"Impingement és instabilitás","lead":"Az emeléskor jelentkező fájdalom subacromialis beszorulásra, a külső rotációkor fellépő bizonytalanságérzés elülső instabilitásra utal. Fontos, hogy a fájdalmat és a bizonytalanságérzést elkülönítsd.","sheet":{"kind":"tests","tests":[{"name":"Neer-teszt","alias":"Neer-féle impingement jel","steps":"Felülről rögzítsd a lapockát, és belső rotációban tartott karral passzívan, előre emeld a felső végtagot maximálisan.","positive":"Fájdalom a váll elülső-felső részén emeléskor","tissue":"Subacromialis rotátorköpeny és nyálkatömlő","point":"A tuberculum majus az acromion alá préselődik és fájdalmat okoz. Pozitív teszt sem dönti el, van-e szakadás."},{"name":"Hawkins–Kennedy-teszt","alias":"","steps":"A váll és a könyök 90°-os flexióban; a vizsgáló az alkart lefelé nyomva passzívan belső rotációba viszi a vállat.","positive":"Fájdalom belső rotációkor a váll elülső-felső vagy oldalsó részén","tissue":"Supraspinatus-ín és subacromialis bursa","point":"A Neer-teszttel együtt értékeld. Ellenőrizd a fájdalom helyét és reprodukálhatóságát."},{"name":"Apprehension-teszt","alias":"Elülső apprehension teszt","steps":"Hanyatt fekvésben a váll 90°-os abdukcióban, a könyök 90°-os flexióban; a vizsgáló lassan külső rotációba viszi a vállat.","positive":"Ficamodástól való félelem, védekező izomfeszülés","tissue":"A vállízület elülső tokja és labruma","point":"Nem a fájdalom, hanem a bizonytalanságérzés dönt. Ficam után lassan, kíméletesen végezd."},{"name":"Relocation-teszt","alias":"","steps":"Az apprehension-teszt helyzetében a humerusfejet elölről hátrafelé nyomva végezz külső rotációt.","positive":"Csökken a bizonytalanságérzés, és tovább vihető a külső rotáció","tissue":"A vállízület elülső instabilitása","point":"Az apprehension-teszt után végezd; a bizonytalanság változása megerősíti az elülső instabilitást."}]},"keypoints":["A Neer- és a Hawkins–Kennedy-teszt a subacromialis beszorulás fájdalmát vizsgálja","Instabilitástesztnél a bizonytalanságérzés megjelenése fontosabb a fájdalomnál","Pozitív teszt sem mutatja meg, van-e rotátorköpeny-szakadás, és mekkora","Ficam utáni állapotban a külső rotációt lassan, erőltetés nélkül végezd","Az anamnézist, más teszteket és a képalkotást együtt értékeld"],"case":{"text":"19 éves férfi rögbijátékos. Szereléskor a karját abdukcióba és külső rotációba kényszerítették; azóta ugyanebben a helyzetben úgy érzi, „kiugrik” a válla. Az apprehension-teszt bizonytalanságot vált ki, a relocation-teszt ezt csökkenti.","answer":"Elülső vállinstabilitásra utaló leletek; különítsd el az impingement fájdalmától. Kerüld az abdukciót és külső rotációt erőltető mozgásokat; orvosi vizsgálatra építve a rotátorköpeny és a lapocka körüli izmok stabilizálásával haladj."},"questions":[{"level":"Alap","q":"Melyik struktúra szorul be leggyakrabban subacromialis impingementben?","options":["A m. triceps brachii ina","m. teres major","Supraspinatus-ín","m. latissimus dorsi"],"answer":2,"exp":"Emeléskor az acromion alatt a supraspinatus-ín és a subacromialis bursa szorul be, és fájdalmat okoz."},{"level":"Alap","q":"Milyen mozgást végzel a vállal a Hawkins–Kennedy-tesztben?","options":["Belső rotáció 90°-os flexióban","Külső rotáció lógó karral","Horizontális abdukció","Extenzió"],"answer":0,"exp":"A váll és könyök 90°-os flexiójából passzív belső rotáció a tuberculum majust a coracoacromialis ív alá préseli."},{"level":"Középhaladó","q":"Mi az apprehension-teszt pozitív lelete?","options":["Elülső-felső vállfájdalom emeléskor","Ficamodástól való félelem","Fájdalom könyökhajlításkor","A kar leesése"],"answer":1,"exp":"Abdukció és külső rotáció mellett megjelenő ficamodási félelem vagy védekező izomfeszülés pozitív, elülső instabilitásra utal."},{"level":"Középhaladó","q":"Mire utal, ha a relocation-tesztben csökken a bizonytalanságérzés?","options":["Rotátorköpeny-szakadás","Acromioclavicularis ízületi károsodás","Fagyott váll","Elülső vállinstabilitás"],"answer":3,"exp":"Ha a humerusfej hátrafelé nyomására csökken a bizonytalanság, az megerősíti az elülső instabilitást."},{"level":"Klinikai","q":"45 éves férfi, fej feletti munkánál fáj a válla elöl-felül. A Neer- és Hawkins-teszt fájdalmas, az erő megtartott. Mi a legvalószínűbb?","options":["Elülső instabilitás","Subacromialis impingement","Nyaki radiculopathia","Acromioclavicularis ficam"],"answer":1,"exp":"Az emeléskor és belső rotációkor jelentkező elülső-felső fájdalom és a megtartott erő alapján subacromialis impingement a legvalószínűbb."},{"level":"Klinikai","q":"20 éves nőnek kétszer volt elülső vállficama. Mi a legmegfelelőbb az apprehension-teszt végzésekor?","options":["Gyorsan maximális külső rotációba vinni","Leállni, amint bizonytalanság jelentkezik","Fájdalomig folytatni a külső rotációt","Lendülettel végezni"],"answer":1,"exp":"A cél a bizonytalanságérzés észlelése, így megjelenésekor állj le. Erőltetésnél újraficamodás veszélye áll fenn."}],"seccion":"Speciális tesztek régiónként","grupo":"Váll","icono":"💪","mapa":"img/mapas/t11.jpg","fichas":[{"nombre":"Neer-teszt","img":"img/fichas/neer.jpg"},{"nombre":"Hawkins–Kennedy-teszt","img":"img/fichas/hawkins.jpg"}],"secuencias":[]},"12":{"id":12,"title":"Biceps és labrum glenoidale","lead":"A m. biceps brachii hosszú fejének ina a sulcus intertubercularisban fut, és a felső labrumon tapad. Dobáskor és húzáskor gyakran sérül; az ínt és a labrumot külön vizsgáld.","sheet":{"kind":"tests","tests":[{"name":"Speed-teszt","alias":"","steps":"Nyújtott könyökkel, szupinált alkarral a beteg előre emeli a vállát; a vizsgáló az alkarra lefelé ható ellenállást ad.","positive":"Fájdalom a sulcus intertubercularis területén","tissue":"A m. biceps brachii hosszú fejének ina","point":"A felső labrum sérülése is okozhat fájdalmat. A nyomásérzékeny ponttal együtt értékeld."},{"name":"Yergason-teszt","alias":"","steps":"90°-ban hajlított könyökkel, pronált alkarból a beteg a vizsgáló ellenállásával szemben szupinálja az alkart.","positive":"Fájdalom a sulcus intertubercularisban, vagy az ín kiugrásának érzése","tissue":"Hosszú fej ina és lig. transversum humeri","point":"Az ín subluxatiójakor kattanás kísérheti. Mindig ellenőrizd a fájdalom helyét."},{"name":"O’Brien-teszt","alias":"Aktív kompressziós teszt","steps":"Váll 90°-os flexióban, enyhe horizontális addukcióban, lefelé néző hüvelykujjal adj lefelé ellenállást; majd felfelé néző tenyérrel ismételd.","positive":"Hüvelykujj lefelé: mély fájdalom vagy kattanás; tenyér felfelé: enyhül","tissue":"Felső labrum és acromioclavicularis ízület","point":"A váll tetején jelentkező fájdalom az AC-ízületre, a mély fájdalom a labrumra utal. Különítsd el a helyét."},{"name":"Crank-teszt","alias":"","steps":"Erősen emelt vállnál a humerus hossztengelye mentén nyomást adva végezz belső és külső rotációt.","positive":"Fájdalom vagy kattanás (akadás érzése) kiváltása","tissue":"Labrum glenoidale","point":"A labrumsérülés teszttel önmagában nehezen igazolható; a képalkotással együtt értékeld."}]},"keypoints":["A hosszú fej ina a sulcusban fut, a tuberculum supraglenoidalén és a felső labrumon tapad","A Speed- és a Yergason-teszt a sulcus intertubercularis fájdalmát ellenőrzi","Az O’Brien-teszt a fájdalom helye alapján különíti el a labrumot és az AC-ízületet","Rögzítsd azt is, van-e kattanás vagy akadásérzés","Labrumsérülést ne csak teszttel igazolj; vesd össze a képalkotással"],"case":{"text":"22 éves férfi baseball-dobójátékos. Dobáskor mély vállfájdalom és akadásérzés. Az O’Brien-teszt lefelé néző hüvelykujjal mély fájdalmat okoz, felfelé néző tenyérrel enyhül. A Speed-teszt is fájdalmas.","answer":"Felső labrum- (SLAP-) sérülésre gyanakszunk. Ha a fájdalom a váll tetején van, AC-ízületi eredetre gondolj. A dobás folytatásáról ne egyedül dönts; irányítsd orvoshoz, és kérd, hogy kerülje a fájdalmat kiváltó dobómozgást."},"questions":[{"level":"Alap","q":"Melyik barázdában fut a m. biceps brachii hosszú fejének ina?","options":["Cavitas glenoidalis","Sulcus intertubercularis","Sulcus nervi radialis","Acromion"],"answer":1,"exp":"A hosszú fej ina a humerus tuberculum majusa és minusa közötti sulcus intertubercularisban fut az ízületbe."},{"level":"Alap","q":"A tuberculum supraglenoidale mellett melyik struktúrán tapad a biceps hosszú fejének ina?","options":["Felső labrum","Lig. glenohumerale inferius","Lig. acromioclaviculare","Lig. coracoclaviculare"],"answer":0,"exp":"A hosszú fej a tuberculum supraglenoidalén és a felső labrumon tapad, ezért az ín és a labrum sérülése gyakran társul."},{"level":"Középhaladó","q":"Melyik mozgással szemben adsz ellenállást a Yergason-tesztben?","options":["Vállabdukció","Csukló dorsalflexiója","Alkar szupinációja","Könyökextenzió"],"answer":2,"exp":"90°-os könyökflexióban az alkar szupinációjával szemben adott ellenállás; a sulcus fájdalma a hosszú fej ínkárosodására utal."},{"level":"Középhaladó","q":"Mire gondolsz, ha az O’Brien-teszt a váll tetején okoz fájdalmat?","options":["Felső labrumsérülés","Acromioclavicularis ízületi károsodás","Rotátorköpeny-szakadás","Elülső instabilitás"],"answer":1,"exp":"A váll tetején jelentkező fájdalom az AC-ízületre, a mély vállfájdalom a felső labrum sérülésére utal."},{"level":"Klinikai","q":"25 éves férfi röplabdázó. Leütéskor mély vállfájdalom és kattanás; az O’Brien-teszt mély fájdalmat okoz. Mi a legvalószínűbb?","options":["AC-ízületi károsodás","Fagyott váll","Nyaki spondylosis","SLAP-sérülés"],"answer":3,"exp":"Fej feletti mozgásnál mély fájdalom és kattanás, valamint pozitív O’Brien-teszt (mély fájdalom): SLAP-sérülésre gyanakszunk."},{"level":"Klinikai","q":"40 éves férfi nehéz tárgy emelésekor szakadó hangot hallott a felkar elején, és a bicepszhas lejjebb került. Mi a legjobb teendő?","options":["Maximális ellenállású erősítés","A Yergason-teszt ismétlése","Orvosi vizsgálatra irányítás","Melegítés és várakozás"],"answer":2,"exp":"A hosszú fej ínszakadására utaló jelek; először orvosi vizsgálat kell. Kerüld a terhelő vizsgálatot és gyakorlatot."}],"seccion":"Speciális tesztek régiónként","grupo":"Váll","icono":"💪","mapa":"img/mapas/t12.jpg","fichas":[],"secuencias":[]},"13":{"id":13,"title":"Könyök","lead":"A könyökfájdalmat oldalt a feszítőizmokra, belül a hajlítóizmokra és a szalagokra, valamint a n. ulnarisra bontva gondold végig. A fájdalom helyét kösd össze a megfelelő teszttel.","sheet":{"kind":"tests","tests":[{"name":"Thomsen-teszt","alias":"","steps":"Nyújtott könyökkel, enyhe csukló-dorsalflexióban a beteg ökölbe szorítja a kezét; a vizsgáló a kézhátat palmarflexió irányába nyomja.","positive":"Fájdalom az epicondylus lateralis humeri körül","tissue":"A m. extensor carpi radialis brevis eredése","point":"Az epicondylitis lateralis vizsgálata. Kombináld a középsőujj-extenzió és a szék-teszttel."},{"name":"Középsőujj-extenzió teszt","alias":"","steps":"Nyújtott könyökkel a beteg kinyújtja a középső ujját; a vizsgáló a proximális ujjpercet palmar irányba nyomja.","positive":"Fájdalom az epicondylus lateralis humeri körül","tissue":"Az ECRB és a m. extensor digitorum eredése","point":"A Thomsen-teszthez hasonlóan epicondylitis lateralisban pozitív. Ellenőrizd, hol jelentkezik a fájdalom."},{"name":"Valgus stresszteszt","alias":"","steps":"Enyhén hajlított könyöknél rögzítsd a felkart, és az alkarra valgus irányú terhelést adj.","positive":"Belső könyökfájdalom vagy az ép oldalnál nagyobb nyithatóság","tissue":"Lig. collaterale ulnare (belső oldalszalag)","point":"Dobókönyök vizsgálatára. Mindig hasonlítsd az ép oldalhoz; a fájdalmat és a lazaságot külön rögzítsd."},{"name":"Tinel-jel (cubitalis alagút)","alias":"","steps":"Az epicondylus medialis és az olecranon közötti cubitalis alagutat ujjbeggyel vagy reflexkalapáccsal enyhén kopogtasd.","positive":"A kisujjba és a gyűrűsujj ulnaris oldalára sugárzó zsibbadás","tissue":"n. ulnaris (cubitalis alagút)","point":"A cubitalis alagút szindróma vizsgálata. A könyökflexiós teszttel és a Froment-jellel együtt értékeld."}]},"keypoints":["Az epicondylus lateralis fájdalmánál a csukló- és ujjfeszítők eredésére gondolj","A valgus stressztesztet enyhe flexióban végezd, és hasonlítsd az ép oldalhoz","A n. ulnaris tüneteit a kisujj és a gyűrűsujj ulnaris oldalának zsibbadása jelzi","A fájdalmat és a lazaságot (instabilitást) külön rögzítsd","Tartós zsibbadás vagy kézizom-atrófia esetén irányítsd orvoshoz"],"case":{"text":"45 éves nő, irodai dolgozó. Törölköző kicsavarásakor és táska felemelésekor fáj a könyöke oldalt. Az epicondylus lateralis nyomásérzékeny, a Thomsen-teszt és a középsőujj-extenzió teszt kiváltja a fájdalmat.","answer":"Epicondylitis lateralis humerire utaló leletek. Kerülje a fájdalmat kiváltó fogómozgások ismétlését, és adagold a terhelést. Ha zsibbadás, duzzanat vagy erős éjszakai fájdalom társul, gondolj más betegségre is, és irányítsd orvoshoz."},"questions":[{"level":"Alap","q":"Melyik izomcsoport ered az epicondylus lateralis humerin?","options":["A csukló hajlítói","A csukló feszítői","m. biceps brachii","m. pronator teres"],"answer":1,"exp":"Az epicondylus lateralison a csukló- és ujjfeszítők, a medialison a hajlítók és a m. pronator teres erednek."},{"level":"Alap","q":"Melyik ideg halad át a cubitalis alagúton?","options":["n. medianus","n. radialis","n. ulnaris","n. musculocutaneus"],"answer":2,"exp":"A n. ulnaris az epicondylus medialis mögötti cubitalis alagútban fut, így a belső könyök kopogtatása a kisujj felé zsibbaszt."},{"level":"Középhaladó","q":"Melyik mozgással szemben adsz ellenállást a Thomsen-tesztben?","options":["Csukló dorsalflexiója","Csukló palmarflexiója","Alkar pronációja","Könyökflexió"],"answer":0,"exp":"A csukló dorsalflexiójával szemben adott ellenállás az epicondylus lateralis körüli fájdalmat váltja ki (feszítők eredése)."},{"level":"Középhaladó","q":"Melyik struktúrát vizsgálja elsősorban a valgus stresszteszt?","options":["Külső oldalszalag","Lig. anulare radii","Caput radii","Belső oldalszalag"],"answer":3,"exp":"Az alkarra adott valgus terhelés a könyök belső oldalát feszíti, így a belső oldalszalag fájdalmát és lazaságát vizsgálja."},{"level":"Klinikai","q":"14 éves fiú baseball-dobó. Dobáskor belső könyökfájdalom; a valgus stresszteszt belül fájdalmat okoz. Mi a legvalószínűbb?","options":["Epicondylitis lateralis humeri","Medialis típusú dobókönyök","Dajkakönyök","Radiusfejtörés"],"answer":1,"exp":"Az ismételt dobómozgás és a valgus terhelésre jelentkező belső fájdalom medialis dobókönyökre (szalag-, epiphysiskárosodás) utal."},{"level":"Klinikai","q":"50 éves férfi. A belső könyök kopogtatására zsibbadás fut a kisujjába, és a finom ujjmozgások is nehezek. Mi a legjobb teendő?","options":["A könyök hosszan hajlított tartása","A zsibbadás megfigyelése","Tájékoztatás az orvosnak","A belső könyök erős masszírozása"],"answer":2,"exp":"Ügyességcsökkenéssel járó n. ulnaris-károsodásnál orvosi vizsgálat kell. A tartós könyökflexió és a nyomás rontja a tüneteket."}],"seccion":"Speciális tesztek régiónként","grupo":"Könyök, csukló és kéz","icono":"✋","mapa":"img/mapas/t13.jpg","fichas":[],"secuencias":[]},"14":{"id":14,"title":"Csukló és kéz","lead":"A kéz zsibbadásánál és fájdalmánál az eloszlás alapján következtess, melyik ideg vagy ín érintett. A carpalis alagút szindróma és az ínhüvelygyulladás a klinikumban és a záróvizsgán is gyakori.","sheet":{"kind":"tests","tests":[{"name":"Phalen-teszt","alias":"","steps":"A beteg a két kézhátat összeillesztve maximális csukló-palmarflexióban tartja egy ideig; figyeld a zsibbadás megjelenését.","positive":"Zsibbadás a hüvelykujjtól a gyűrűsujj radialis oldaláig, vagy annak fokozódása","tissue":"n. medianus (carpalis alagút)","point":"A carpalis alagút szindróma vizsgálata. Ellenőrizd, hogy a zsibbadás a n. medianus területének felel-e meg."},{"name":"Tinel-jel (csukló)","alias":"","steps":"A csukló palmaris oldalán a carpalis alagutat ujjbeggyel vagy reflexkalapáccsal enyhén kopogtasd.","positive":"A n. medianus területén az ujjbegyekbe sugárzó zsibbadás","tissue":"n. medianus (carpalis alagút)","point":"Az idegkompresszió helyének és a regenerációnak a becslésére is használható. Ne kopogtass túl erősen."},{"name":"Finkelstein-teszt","alias":"","steps":"A beteg a hüvelykujját a többi ujjával ökölbe zárja (vagy a vizsgáló fogja a hüvelykujjat), majd a csuklót passzívan ulnaris deviációba viszed.","positive":"Erős fájdalom a processus styloideus radii területén","tissue":"m. abductor poll. longus és m. extensor poll. brevis","point":"A de Quervain-betegség vizsgálata. Az ökölbe zárós változat neve Eichhoff-teszt. Hasonlítsd az ép oldalhoz."},{"name":"Froment-jel","alias":"","steps":"A beteg mindkét kezének hüvelyk- és mutatóujja között papírt tart, a vizsgáló pedig kihúzza azt.","positive":"A hüvelykujj IP-ízülete behajlik, hogy megtartsa a papírt","tissue":"n. ulnaris (m. adductor pollicis)","point":"A gyenge m. adductor pollicist a n. medianus által beidegzett m. flexor pollicis longus kompenzálja."}]},"keypoints":["A zsibbadás eloszlása alapján különítsd el a n. medianust, ulnarist és radialist","A Phalen-teszt és a Tinel-jel a n. medianust vizsgálja a carpalis alagútban","A Finkelstein-teszt a hüvelykujj ínhüvelygyulladásának vizsgálatára szolgál","Mindkét oldalon végezd el, és az ép oldalhoz hasonlítva értékelj","Thenaratrófia vagy tartós zsibbadás esetén irányítsd orvoshoz"],"case":{"text":"52 éves nő. Hajnalban zsibbad a hüvelyk-, mutató- és középső ujja, a kéz rázására enyhül. A Phalen-teszt ugyanott zsibbadást vált ki, és a carpalis alagút feletti Tinel-jel is pozitív.","answer":"Carpalis alagút szindrómára gyanakszunk. Ha a zsibbadás a kisujjra is kiterjed, vagy a nyak mozgására változik, gondolj más szintre is. Thenaratrófia vagy gyengeség esetén irányítsd orvoshoz; kerüld a csukló erős összenyomását."},"questions":[{"level":"Alap","q":"Melyik ideg halad át a carpalis alagúton?","options":["n. ulnaris","n. medianus","n. radialis","n. musculocutaneus"],"answer":1,"exp":"A carpalis alagútban az ujjhajlítók inai és a n. medianus futnak; itt bekövetkező kompressziója a carpalis alagút szindróma."},{"level":"Alap","q":"Hol jelentkezik fájdalom a Finkelstein-tesztben?","options":["Processus styloideus radii","Processus styloideus ulnae","Os pisiforme","Az V. kézközépcsont feje"],"answer":0,"exp":"A hüvelykujj inai (m. abductor pollicis longus, m. extensor pollicis brevis) által keresztezett proc. styloideus radiinál fáj."},{"level":"Középhaladó","q":"Melyik ideget vizsgálja a Froment-jel?","options":["n. medianus","n. radialis","n. axillaris","n. ulnaris"],"answer":3,"exp":"Ha a n. ulnaris által beidegzett m. adductor pollicis gyenge, a m. flexor pollicis longus kompenzál, és az IP-ízület behajlik."},{"level":"Középhaladó","q":"Mi a Phalen-teszt pozitív lelete?","options":["A kisujj zsibbadása","Az egész kézhát fájdalma","Zsibbadás az I–IV. ujj radialis feléig","A csukló instabilitásérzése"],"answer":2,"exp":"A tartott palmarflexió növeli az alagút nyomását, így a n. medianus területén (hüvelykujjtól a IV. ujj radialis feléig) zsibbadás jelentkezik."},{"level":"Klinikai","q":"30 éves nő. Szülés óta babagondozáskor fáj a csukló hüvelykujj felőli oldala; ökölbe zárt hüvelykujjal, ulnaris deviációban fáj. Mi valószínű?","options":["Carpalis alagút szindróma","TFCC-sérülés","De Quervain-betegség","Pattanó ujj"],"answer":2,"exp":"A hüvelykujj túlterhelése és az ökölbe zárás + ulnaris deviáció során a proc. styloideus radiinál jelentkező fájdalom de Quervain-betegségre utal."},{"level":"Klinikai","q":"60 éves férfi. Zsibbad a kisujja és a gyűrűsujja ulnaris oldala, papírcsípésnél behajlik a hüvelykujj IP-ízülete. Melyik ideg károsodására gondolsz?","options":["n. medianus","n. radialis","n. interosseus posterior","n. ulnaris"],"answer":3,"exp":"A kisujj és a gyűrűsujj ulnaris oldalának zsibbadása és a pozitív Froment-jel a n. ulnaris károsodására utal."}],"seccion":"Speciális tesztek régiónként","grupo":"Könyök, csukló és kéz","icono":"✋","mapa":"img/mapas/t14.jpg","fichas":[{"nombre":"Phalen-teszt","img":"img/fichas/phalen.jpg"},{"nombre":"Finkelstein-teszt","img":"img/fichas/finkelstein.jpg"},{"nombre":"Tinel-jel a csuklón","img":"img/fichas/tinel-punho.jpg"}],"secuencias":[]},"15":{"id":15,"title":"Nyaki gerinc","lead":"A nyakból a karba sugárzó fájdalmat és zsibbadást ideggyöki kompresszió okozhatja. Provokáló és tehermentesítő tesztekkel is ellenőrizd, hogy radicularis tünetről van-e szó.","sheet":{"kind":"tests","tests":[{"name":"Spurling-teszt","alias":"Foraminalis kompressziós teszt","steps":"Ülő helyzetben a nyakat a fájós oldalra hajlítod (enyhe extenzió és rotáció), majd a fejtetőn át lefelé nyomást adsz.","positive":"A fájós oldali karba sugárzó fájdalom vagy zsibbadás kiváltása","tissue":"Nyaki ideggyök (foramen intervertebrale)","point":"Csak nyaki fájdalom kiváltása nem pozitív. Erős fájdalom vagy szédülés esetén azonnal hagyd abba."},{"name":"Jackson-teszt","alias":"Jackson-féle kompressziós teszt","steps":"Ülő helyzetben, enyhe nyaki extenzióban a fejtetőn át lefelé nyomást adsz.","positive":"A karba sugárzó fájdalom vagy zsibbadás kiváltása","tissue":"Nyaki ideggyök","point":"Kihasználja, hogy extenzióban szűkül a foramen. Kombináld a Spurling-teszttel."},{"name":"Nyaki disztrakciós teszt","alias":"Distractiós teszt","steps":"Ülő helyzetben az állkapocs alatt és a tarkón megtámasztva lassan felfelé húzod a fejet.","positive":"Enyhül a karba sugárzó fájdalom vagy zsibbadás","tissue":"Nyaki ideggyök (foraminalis kompresszió)","point":"Enyhülés esetén pozitív. Ha a húzás rontja a tüneteket, gondolj más okra, és hagyd abba."},{"name":"Vállabdukciós teszt","alias":"Bakody-jel","steps":"Ülő helyzetben a beteg a fájós oldali kezét a feje tetejére teszi; figyeld a kartünetek változását.","positive":"Enyhül a karba sugárzó fájdalom vagy zsibbadás","tissue":"Nyaki ideggyök","point":"Az ideggyök feszülése csökken, a tünetek enyhülnek. A beteg ezt a testhelyzetet akár magától is felveszi."}]},"keypoints":["A karba sugárzó fájdalom vagy zsibbadás kiváltása radicularis tünetre utal","A kompressziós teszteket kíméletesen végezd, erős tünet esetén állj le","Ellenőrizd azt is, hogy húzásra vagy vállabdukcióra enyhülnek-e a tünetek","A dermatomák, az izomerő és az ínreflexek alapján becsüld meg a szintet","Kétoldali kézzsibbadás vagy járászavar: myelopathia gyanúja, orvoshoz"],"case":{"text":"48 éves férfi, ülőmunkát végez. Nyakfájás, valamint zsibbadás a jobb hüvelykujjtól az alkar radialis oldaláig. A Spurling-teszt a jobb karban kiváltja a zsibbadást, a fej húzására enyhül.","answer":"Nyaki radiculopathiára gyanakszunk; a zsibbadás eloszlása alapján C6-os területre. Ellenőrizd az ínreflexeket és az izomerőt is. Ha a két kéz ügyessége romlik vagy járászavar van, myelopathiára gondolj, és irányítsd orvoshoz. Kerüld az erős kompresszió ismétlését."},"questions":[{"level":"Alap","q":"Milyen nyaki helyzetben nyomod lefelé a fejet a Spurling-tesztben?","options":["Lateralflexió a fájós oldalra","Lateralflexió az ép oldalra","Maximális flexió","Középhelyzet húzással"],"answer":0,"exp":"A fájós oldalra hajlítva (enyhe extenzióval) szűkül a foramen; a fej összenyomása kiváltja a radicularis tünetet."},{"level":"Alap","q":"Melyik terület szűkül nyaki extenzióban és a fájós oldalra hajlításkor, így könnyen nyomva az ideggyököt?","options":["A csigolyatest elülső széle","Foramen intervertebrale","A tövisnyúlványok köze","A harántnyúlvány csúcsa"],"answer":1,"exp":"Az ideggyök a foramen intervertebralén lép ki, ezért az extenzió és a lateralflexió szűkítése könnyen nyomja."},{"level":"Középhaladó","q":"Mi a nyaki disztrakciós teszt pozitív lelete?","options":["A kartünetek fokozódása","Szédülés megjelenése","A kartünetek enyhülése","A nyaki ROM növekedése"],"answer":2,"exp":"A húzás tágítja a forament, csökken az ideggyök kompressziója; ha enyhül a kar fájdalma, zsibbadása, a teszt pozitív."},{"level":"Középhaladó","q":"Melyik lelet alapján értékeled pozitívnak a Spurling-tesztet?","options":["Csak nyaki fájdalom","Vállmerevség érzése","Nyaki izomfeszülés","A fájós oldali karba sugárzó fájdalom"],"answer":3,"exp":"Pozitív, ha a karba sugárzó fájdalom vagy zsibbadás kiváltható. A csak helyi nyaki fájdalom nem pozitív."},{"level":"Klinikai","q":"50 éves nő, nyakfájás és a bal középső ujj zsibbadása. A bal oldali tricepsz-ínreflex csökkent. Melyik ideggyökre gyanakszol?","options":["C5","C6","C7","C8"],"answer":2,"exp":"A középső ujj érzészavara és a csökkent tricepszreflex a C7-es ideggyök károsodására utal."},{"level":"Klinikai","q":"65 éves férfi. Mindkét keze zsibbad, nehezen gombol, és járás közben bizonytalan. Mi a legmegfelelőbb teendő?","options":["Tájékoztatás az orvosnak","A nyak erős húzása","A Spurling-teszt ismétlése","Nyaki manuális korrekció"],"answer":0,"exp":"A kétoldali ügyességcsökkenés és a járászavar cervicalis myelopathiára utal. Kerüld a provokáló teszteket, irányítsd orvoshoz."}],"seccion":"Speciális tesztek régiónként","grupo":"Gerinc és medence","icono":"🦴","mapa":"img/mapas/t15.jpg","fichas":[],"secuencias":[]},"16":{"id":16,"title":"Ágyéki gerinc","lead":"Ha a derékfájást alsó végtagi fájdalom vagy zsibbadás kíséri, vizsgáld az ideggyök érintettségét. A tesztekkel kiváltott tünetekből és a neurológiai leletekből becsüld meg a károsodás szintjét.","sheet":{"kind":"tests","tests":[{"name":"SLR-teszt","alias":"Lasègue-jel","steps":"Hanyatt fekvésben, nyújtott térddel a vizsgáló lassan, passzívan megemeli az alsó végtagot.","positive":"A farba és a lábszárba sugárzó fájdalom vagy zsibbadás kiváltása","tissue":"L5- és S1-ideggyök, n. ischiadicus","point":"A comb hátsó részének feszülését különítsd el a hamstringek nyúlásától. Rögzítsd a szöget és a tünetet."},{"name":"Femoralis feszítési teszt","alias":"FNS-teszt (fordított Lasègue)","steps":"Hason fekvésben passzívan hajlítsd be a térdet, szükség esetén a csípőt is vidd extenzióba.","positive":"A comb elülső részébe sugárzó fájdalom","tissue":"Felső lumbalis ideggyökök (L2–L4), n. femoralis","point":"Különítsd el a m. quadriceps nyúlási fájdalmától és a csípő eredetű fájdalomtól."},{"name":"Kemp-teszt","alias":"","steps":"Állva vagy ülve a vizsgáló a törzset hátrafelé extenzióba viszi, és közben a fájós oldalra hajlítja és rotálja.","positive":"Derékfájás vagy a fájós oldali lábba sugárzó fájdalom","tissue":"Kisízületek és ideggyök (foramen)","point":"Helyi derékfájásnál kisízületi, lábba sugárzó fájdalomnál ideggyöki érintettségre gondolj."},{"name":"Bragard-teszt","alias":"","steps":"Az SLR-ben tünetet kiváltó szögből kissé engedd le a végtagot, majd passzívan vidd dorsalflexióba a bokát.","positive":"A lábba sugárzó fájdalom újra megjelenik vagy fokozódik","tissue":"n. ischiadicus és lumbosacralis ideggyökök","point":"Segít elkülöníteni a hamstringek nyúlási fájdalmát az ideg eredetű tünettől."}]},"keypoints":["Először különítsd el: csak derékfájás, vagy lábtünetekkel jár?","Az SLR az alsó, a femoralis feszítési teszt a felső lumbalis ideggyököket vizsgálja","Az izomnyúlás érzését és a neurogén kisugárzó fájdalmat külön rögzítsd","A dermatomák, az izomerő és az ínreflexek alapján becsüld meg a szintet","Vizelet- vagy székletürítési zavar, gáttájéki zsibbadás: sürgősen orvoshoz"],"case":{"text":"35 éves férfi. Nehéz tárgy emelése óta derékfájás, valamint zsibbadás a jobb lábszár külső oldalától a lábhátig. Az SLR-teszt a jobb lábba sugárzó fájdalmat vált ki, a Bragard-teszt fokozza. A nagylábujj dorsalflexiós ereje csökkent.","answer":"L5-ös radicularis tünetre gyanakszunk (pl. lumbalis porckorongsérv). Kerüld a fájdalmat fokozó előrehajlításos terhelést. Vizelet- vagy székletürítési zavar, gáttájéki zsibbadás vagy gyorsan romló izomerő esetén sürgősen irányítsd orvoshoz."},"questions":[{"level":"Alap","q":"Melyik ideget feszíti elsősorban az SLR-teszt?","options":["n. femoralis","n. ischiadicus","n. obturatorius","n. pudendus"],"answer":1,"exp":"Nyújtott térd mellett a csípő flexiója a végtag hátsó részén futó n. ischiadicust és az L5–S1-ideggyököket feszíti."},{"level":"Alap","q":"Melyik ideggyöki szinteket vizsgálja elsősorban a femoralis feszítési teszt?","options":["L2–L4","L5–S1","S2–S4","C5–C6"],"answer":0,"exp":"A n. femoralis az L2–L4-ideggyökökből ered, így a felső lumbalis radicularis tünetek vizsgálatára használjuk."},{"level":"Középhaladó","q":"Milyen műveletet végzel a Bragard-tesztben?","options":["Boka plantarflexiója","Csípő külső rotációja","Térdflexió","Boka dorsalflexiója"],"answer":3,"exp":"Az SLR-ben tünetet adó szögből kissé leengeded a lábat, majd a boka dorsalflexiójával tovább feszíted az ideget."},{"level":"Középhaladó","q":"Mire gondolsz elsősorban, ha a Kemp-teszt lábtünet nélkül csak helyi derékfájást okoz?","options":["Ideggyöki kompresszió","n. femoralis károsodása","Kisízületi eredetű fájdalom","m. piriformis-szindróma"],"answer":2,"exp":"Az extenzió és rotáció a kisízületeket terheli. Csak helyi fájdalomnál kisízületi eredetre gondolj."},{"level":"Klinikai","q":"40 éves nő, derékfájás, zsibbadás a bal láb külső szélétől a talpig. A bal Achilles-ínreflex csökkent. Melyik ideggyökre gyanakszol?","options":["L3","L4","L5","S1"],"answer":3,"exp":"A láb külső szélének és a talpnak az érzészavara, valamint a csökkent Achilles-reflex S1-es ideggyöki károsodásra utal."},{"level":"Klinikai","q":"50 éves férfinál a derékfájás mellett hirtelen gáttájéki zsibbadás és vizelési nehézség jelent meg. Mi a legjobb teendő?","options":["Azonnal orvoshoz irányítani","Az SLR ismételt vizsgálata","Ágyéki gyakorlatok kezdése","Hőterápia és várakozás"],"answer":0,"exp":"A gáttájéki zsibbadás és a hólyag-végbél zavar cauda equina szindrómára utaló vörös zászló; sürgős ellátás kell."}],"seccion":"Speciális tesztek régiónként","grupo":"Gerinc és medence","icono":"🦴","mapa":"img/mapas/t16.jpg","fichas":[],"secuencias":[]},"17":{"id":17,"title":"Sacroiliacalis ízület","lead":"A sacroiliacalis (SI) ízület eredetű fájdalmat könnyű összetéveszteni a derékfájással. A fájdalom helyének megmutatását és több provokációs tesztet kombinálva következtess.","sheet":{"kind":"tests","tests":[{"name":"FABER (Patrick-) teszt","alias":"","steps":"Hanyatt fekvésben a fájós oldali lábfejet az ellenoldali térdre helyezed, rögzíted az ellenoldali medencét, és a térdet lefelé nyomod.","positive":"Fájdalom a farban, az SI-ízület felett (lágyéki fájdalom: csípőízület)","tissue":"Sacroiliacalis ízület és csípőízület","point":"A fájdalom helye alapján különíts el: lágyék esetén csípőízület, far és SI-ízület esetén SI-ízület."},{"name":"Gaenslen-teszt","alias":"","steps":"Hanyatt fekvésben az egyik alsó végtag a vizsgálóasztal széléről lelóg (csípőextenzió), a másik térdet a beteg flexióban magához öleli.","positive":"Fájdalom az extendált oldali SI-ízület felett","tissue":"Sacroiliacalis ízület","point":"Kerüld az ágyéki gerinc hiperextenzióját; a leesés elkerülésére támaszd meg a törzset."},{"name":"Thigh thrust teszt","alias":"Combnyomásos teszt","steps":"Hanyatt fekvésben, 90°-os csípőflexióban a comb hossztengelye mentén lefelé nyomást adsz.","positive":"Fájdalom az azonos oldali farban, az SI-ízület felett","tissue":"Sacroiliacalis ízület","point":"Kérd meg a beteget, mutassa meg a fájdalom helyét, és ellenőrizd, hogy a megszokott fájdalma-e."},{"name":"Medencekompressziós teszt","alias":"","steps":"Oldalfekvésben a felül lévő crista iliacára felülről lefelé kompressziót adsz.","positive":"Fájdalom az SI-ízület felett","tissue":"Sacroiliacalis ízület","point":"Önmagában nem elég. Több provokációs teszt kombinációjával következtess SI-eredetű fájdalomra."}]},"keypoints":["Kérd meg a beteget, hogy egy ujjal mutassa meg a fájdalom helyét","A spina iliaca posterior superior körüli fájdalomnál SI-eredetre gondolj","Ne egyetlen, hanem több provokációs teszt alapján dönts","Lágyéki fájdalomnál csípőre, lábba sugárzó fájdalomnál ideggyökre is gondolj","Láz vagy erős nyugalmi fájdalom esetén irányítsd orvoshoz"],"case":{"text":"32 éves nő, 3 hónappal szülés után. Egyoldali farfájdalom, amely forduláskor és egylábas állásban fokozódik. Egy ujjal a spina iliaca posterior superior környékét mutatja. A thigh thrust és a Gaenslen-teszt kiváltja a fájdalmat.","answer":"SI-ízület eredetű fájdalomra gyanakszunk. Lábba sugárzó fájdalom vagy neurológiai tünet esetén ágyéki eredetre is gondolj. Láz vagy erős nyugalmi fájdalom esetén irányítsd orvoshoz. A medenceöv stabilizálásával és a terhelés adagolásával haladj."},"questions":[{"level":"Alap","q":"Az egyujjas tesztben SI-eredetű fájdalomnál melyik területet mutatja jellemzően a beteg?","options":["A spina iliaca ant. sup. környékét","A spina iliaca post. sup. környékét","Symphysis pubica","Tuber ischiadicum"],"answer":1,"exp":"SI-ízület eredetű fájdalomnál a beteg gyakran egy ujjal a spina iliaca posterior superior környékét mutatja."},{"level":"Alap","q":"Mely csontok alkotják a sacroiliacalis ízületet?","options":["Keresztcsont és csípőcsont","Keresztcsont és ülőcsont","Csípőcsont és szeméremcsont","Az L5-csigolya és a keresztcsont"],"answer":0,"exp":"Az SI-ízület a keresztcsont és a két csípőcsont közötti ízület; a medencegyűrű hátsó részét alkotja."},{"level":"Középhaladó","q":"Melyik ízületre gondolsz, ha a FABER (Patrick-) teszt lágyéki fájdalmat okoz?","options":["Sacroiliacalis ízület","Csípőízület","Térdízület","Kisízületek"],"answer":1,"exp":"Ha flexió, abdukció és külső rotáció mellett a lágyék fáj, csípőízületre, ha a far hátsó része, SI-ízületre gondolj."},{"level":"Középhaladó","q":"Milyen irányban adsz nyomást a thigh thrust tesztben?","options":["A combot kifelé","A medencét előre","A comb hossztengelye mentén lefelé","A térdet befelé"],"answer":2,"exp":"90°-os csípőflexióban a comb hossztengelye mentén adott nyomás nyíró terhelést ad az SI-ízületre."},{"level":"Klinikai","q":"28 éves nő, szülés után egyoldali farfájdalom. A Gaenslen-, a thigh thrust és a medencekompressziós teszt kiváltja a fájdalmat. Mi a legvalószínűbb?","options":["Csípőízület","L5-ideggyök","m. piriformis","Sacroiliacalis ízület"],"answer":3,"exp":"Több SI-provokációs teszt ugyanazt a fájdalmat váltja ki, így leginkább SI-ízület eredetű fájdalomra gondolunk."},{"level":"Klinikai","q":"45 éves férfi, egyoldali farfájdalom. Csak a FABER (Patrick-) teszt okozott farfájdalmat. Mi a legmegfelelőbb következő lépés?","options":["SI-ízületi diszfunkció kimondása","További provokációs tesztek","Az ágyéki és csípővizsgálat elhagyása","Erős manuális korrekció"],"answer":1,"exp":"Egyetlen pozitív teszt alapján nem dönthetsz. Kombinálj több provokációs tesztet az ágyéki gerinc és a csípő vizsgálatával."}],"seccion":"Speciális tesztek régiónként","grupo":"Gerinc és medence","icono":"🦴","mapa":"img/mapas/t17.jpg","fichas":[],"secuencias":[]},"18":{"id":18,"title":"Csípő","lead":"A csípőízület eredetű fájdalom gyakran a lágyékban jelentkezik, a kontraktúra és az izomgyengeség pedig a járásban látszik. Tesztekkel ellenőrizd az ízületen belüli, az izom- és a járásra gyakorolt hatást.","sheet":{"kind":"tests","tests":[{"name":"Thomas-teszt","alias":"","steps":"Hanyatt fekvésben a beteg az egyik térdét a mellkasához öleli, megszüntetve a lumbalis lordózist; figyeld, felemelkedik-e az ellenoldali comb.","positive":"Az ellenoldali comb felemelkedik az alátámasztásról (csípőflexiós kontraktúra)","tissue":"A m. iliopsoas (csípőhajlítók) rövidülése","point":"Ha a térd extendálódik, gondolj a m. rectus femoris rövidülésére is. A lordózis megszüntetése után értékelj."},{"name":"FABER (Patrick-) teszt","alias":"","steps":"Hanyatt fekvésben a csípőt flexióba, abdukcióba és külső rotációba viszed (lábfej az ellenoldali térden), majd a térdet lefelé nyomod.","positive":"Lágyéki fájdalom, vagy a térd süllyedésének korlátozottsága","tissue":"Csípőízület és sacroiliacalis ízület","point":"Lágyéki fájdalomnál csípőre, hátsó farfájdalomnál SI-ízületre gondolj. Hasonlítsd az ép oldalhoz."},{"name":"Elülső impingement teszt","alias":"FADIR-teszt","steps":"Hanyatt fekvésben 90°-os csípőflexióból passzívan addukciót és belső rotációt adsz.","positive":"A lágyéki fájdalom kiváltása","tissue":"A csípőízület elülső része (labrum, acetabulumszél)","point":"Femoroacetabularis impingementben és labrumsérülésben gyakran pozitív. Vesd össze a képalkotással."},{"name":"Trendelenburg-jel","alias":"","steps":"A beteg a fájós lábán egy lábon áll; hátulról figyeld az ellenoldali (emelt oldali) medence magasságát.","positive":"Az emelt oldali medence lesüllyed","tissue":"Az állóláb m. gluteus mediusa (csípőabduktorok)","point":"Ha a törzs az állóláb felé dőlve kompenzál, az Duchenne-jel. Támaszd meg az elesés megelőzésére."}]},"keypoints":["A csípőízület eredetű fájdalom gyakran a lágyékban jelentkezik","A Thomas-teszt a lordózis megszüntetése után a flexiós kontraktúrát vizsgálja","A Trendelenburg-jel az állóláb m. gluteus mediusának erejét mutatja","Különítsd el az ágyéki gerinc és az SI-ízület eredetű fájdalomtól is","Trauma utáni terhelésképtelenség vagy romló nyugalmi fájdalom: orvoshoz"],"case":{"text":"68 éves nő, coxarthrosis. Járáskor jobb lágyéki fájdalom. Jobb lábon állva a bal medence lesüllyed; bal térdét a mellkasához ölelve a jobb comb felemelkedik az alátámasztásról.","answer":"A jobb m. gluteus medius gyengeségére és jobb oldali csípőflexiós kontraktúrára gondolunk. Figyeld a járás közbeni kompenzációt is; a fájdalomra ügyelve végezz abduktorerősítést és ROM-gyakorlatokat. Hirtelen romló nyugalmi fájdalom esetén irányítsd orvoshoz."},"questions":[{"level":"Alap","q":"Melyik izom rövidülését vizsgálja elsősorban a Thomas-teszt?","options":["m. gluteus maximus","m. iliopsoas","m. gluteus medius","Hamstringek"],"answer":1,"exp":"Az ellenoldali comb felemelkedése csípőflexiós kontraktúrát jelez, így a fő csípőhajlító m. iliopsoas rövidülését mutatja."},{"level":"Alap","q":"Melyik izom gyengeségére utal a Trendelenburg-jel, amikor egylábas állásban lesüllyed az ellenoldali medence?","options":["A lendítőláb m. gluteus mediusa","Az állóláb m. quadricepse","Az állóláb m. gluteus mediusa","A lendítőláb m. iliopsoasa"],"answer":2,"exp":"Ha az állóláb m. gluteus mediusa gyenge, nem tudja vízszintesen tartani a medencét, és az ellenoldali (emelt) oldal lesüllyed."},{"level":"Középhaladó","q":"Melyik izom rövidülésére gondolsz, ha a Thomas-tesztben a térd extendálódik?","options":["m. rectus femoris","m. sartorius","m. adductor magnus","m. biceps femoris"],"answer":0,"exp":"A m. rectus femoris a csípő- és térdízületet is áthidaló kétízületi izom; rövidülésekor a térd extendálódik."},{"level":"Középhaladó","q":"Milyen mozgások kombinációját végzed az elülső impingement (FADIR-) tesztben?","options":["Flexió, abdukció, külső rotáció","Extenzió, abdukció, belső rotáció","Extenzió, addukció, külső rotáció","Flexió, addukció, belső rotáció"],"answer":3,"exp":"90°-os csípőflexióból addukciót és belső rotációt adsz, és figyeled, kiváltható-e az elülső csípőfájdalom."},{"level":"Klinikai","q":"70 éves férfi. Valahányszor a jobb lábára lép, a törzsét erősen jobbra dönti járás közben. Hogy hívják ezt a járást?","options":["Lépegető (kakas-) járás","Circumductiós járás","Freezing (lefagyás)","Duchenne-járás"],"answer":3,"exp":"Ha a m. gluteus medius gyengeségét a törzs állóláb felé döntésével kompenzálja a beteg, az a Duchenne-járás."},{"level":"Klinikai","q":"30 éves férfi labdarúgó. Mély guggoláskor fáj a lágyéka, és a csípő flexiója, addukciója és belső rotációja kiváltja a fájdalmat. Mi a legvalószínűbb?","options":["Gonarthrosis","Femoroacetabularis impingement","L5-ös radiculopathia","m. piriformis-szindróma"],"answer":1,"exp":"A mély flexióban jelentkező lágyéki fájdalom és a pozitív elülső impingement teszt femoroacetabularis impingementre utal."}],"seccion":"Speciális tesztek régiónként","grupo":"Csípő és térd","icono":"🦵","mapa":"img/mapas/t18.jpg","fichas":[],"secuencias":[]},"19":{"id":19,"title":"Térd: szalagok","lead":"A térdszalag-tesztekkel az elülső és hátsó keresztszalag, valamint a belső és külső oldalszalag sérülését különítjük el. A döntés alapja a sérülési mechanizmus és az ép oldallal való összevetés.","sheet":{"kind":"tests","tests":[{"name":"Lachman-teszt","alias":"","steps":"Hanyatt fekvés, térd 20–30° flexióban. Egyik kéz a comb distalis részét, a másik a sípcsont proximalis részét fogja, és a sípcsontot előre húzza.","positive":"Az ép oldalnál nagyobb elülső elmozdulás vagy bizonytalan végérzés.","tissue":"Elülső keresztszalag (ACL)","point":"Az ACL-sérülésre érzékeny teszt. Nem kell hozzá 90°-os térdflexió, ezért akut szakban is jól kivitelezhető."},{"name":"Elülső fiók teszt","alias":"","steps":"Hanyatt fekvés, csípő 45°-os, térd 90°-os flexióban. A lábfejet rögzíted, a sípcsont proximalis részét két kézzel fogod és előre húzod.","positive":"Az ép oldalhoz képest nagyobb elülső tibiaelmozdulás.","tissue":"Elülső keresztszalag (ACL)","point":"Az izmok védekező feszülése álnegatív eredményt adhat. Figyelj a PCL-sérülés okozta hátsó besüllyedésre is."},{"name":"Hátsó fiók teszt","alias":"","steps":"Hanyatt fekvés, csípő 45°-os, térd 90°-os flexióban. A lábfejet rögzíted, és a sípcsont proximalis részét hátrafelé tolod.","positive":"Az ép oldalnál nagyobb hátsó tibiaelmozdulás, bizonytalan végérzés.","tissue":"Hátsó keresztszalag (PCL)","point":"Kezdés előtt nézd meg a sípcsont hátsó besüllyedését (sag-jel), hogy ne téveszd el a kiinduló helyzetet."},{"name":"Valgus és varus stresszteszt","alias":"","steps":"Hanyatt fekvés, térd 0°-ban és 30° flexióban. A comb distalis részét rögzíted, és a lábszárra valgus vagy varus irányú erőt adsz.","positive":"Fájdalom az ízületi résben vagy az ép oldalnál nagyobb nyílás.","tissue":"Valgus = MCL, varus = LCL","point":"Csak 30°-ban pozitív: izolált oldalszalag-sérülés. 0°-ban is: társult (pl. keresztszalag-) sérülés gyanúja."}]},"keypoints":["Az ACL vizsgálatára a Lachman-teszt az első választás, mindig az ép oldallal összevetve","Az anamnézisben kérdezz rá a térd kiugrására, a pattanó hangra és a gyors duzzanatra","A hátsó fiók teszt előtt a sag-jellel ellenőrizd a sípcsont helyzetét","Az oldalszalagokat 0°-ban és 30° flexióban is terheld","A védekező feszülés álnegatív eredményt ad, ezért ellazult helyzetben vizsgálj"],"case":{"text":"20 éves nő. Kosárlabdában érkezéskor a térde befelé bicsaklott. Pattanó hangot hallott, a térd azonnal megduzzadt. A Lachman-tesztnél az ép oldalnál nagyobb az elülső elmozdulás, a végérzés bizonytalan.","answer":"ACL-sérülésre utaló lelet. Vizsgáld a társult meniszkusz- és oldalszalag-sérülést is, és irányítsd orvosi képalkotó vizsgálatra. Erős duzzanat és fájdalom idején ne ismételj erős stresszteszteket."},"questions":[{"level":"Alap","q":"Az ábrán melyik teszt húzza előre a sípcsontot 20–30°-os térdflexióban?","options":["Elülső fiók teszt","Lachman-teszt","Hátsó fiók teszt","Valgus stresszteszt"],"answer":1,"exp":"A Lachman-teszt 20–30°-os térdflexióban húzza előre a sípcsontot, és az ACL-t vizsgálja. Az elülső fiók tesztet 90°-os térdnél végezzük."},{"level":"Alap","q":"Az ábrán melyik szalagot vizsgálja a varus stresszteszt?","options":["Belső oldalszalag (MCL)","Elülső keresztszalag (ACL)","Külső oldalszalag (LCL)","Hátsó keresztszalag (PCL)"],"answer":2,"exp":"A varus stressz a térd külső oldalát nyitja, így a külső oldalszalagot (LCL) vizsgálja. A valgus stressz az MCL-t vizsgálja."},{"level":"Középhaladó","q":"Milyen sérülésre utal a pozitív hátsó fiók teszt?","options":["PCL-sérülés","ACL-sérülés","LCL-sérülés","Patellaficam"],"answer":0,"exp":"A hátsó fiók teszt 90°-os térdflexióban hátrafelé tolja a sípcsontot, és a hátsó keresztszalagot (PCL) vizsgálja."},{"level":"Középhaladó","q":"Ha a valgus stresszteszt 0°-os térdnél is pozitív, mire gondolsz először?","options":["Enyhe, izolált MCL-sérülés","Csak külső meniszkusz-sérülés","Patellainstabilitás","Társult (pl. keresztszalag-) sérülés"],"answer":3,"exp":"Extenzióban a keresztszalagok és az ízületi tok is stabilizál. Ha 0°-ban is nyílik a rés, nem izolált MCL-, hanem társult sérülés gyanúja áll fenn."},{"level":"Klinikai","q":"25 éves férfi. Focizáskor hajlított térdnél erős ütés érte a sípcsont elejét. 90°-os flexióban a sípcsont hátrasüllyedt. Mi a legvalószínűbb?","options":["ACL-sérülés","PCL-sérülés","MCL-sérülés","Belső meniszkusz-sérülés"],"answer":1,"exp":"A sípcsont elülső felszínét érő erő és a sag-jel tipikus PCL-sérülésre. Hátsó fiók teszttel erősítsd meg, és irányítsd orvosi diagnózisra."},{"level":"Klinikai","q":"30 éves nő. Síelés közben a térde valgusba csavarodott. Valgus stressznél 30° flexióban fájdalom és nyílás van, 0°-ban stabil. Mi a legvalószínűbb?","options":["Izolált ACL-sérülés","LCL-sérülés","Izolált MCL-sérülés","PCL-sérülés"],"answer":2,"exp":"Valgus mechanizmus és csak 30°-ban pozitív teszt izolált MCL-sérülésre utal. Ha 0°-ban is pozitív, társult sérülést kell feltételezni."}],"seccion":"Speciális tesztek régiónként","grupo":"Csípő és térd","icono":"🦵","mapa":"img/mapas/t19.jpg","fichas":[{"nombre":"Lachman-teszt","img":"img/fichas/lachman.jpg"}],"secuencias":[]},"20":{"id":20,"title":"Térd: meniszkuszok és térdkalács","lead":"A meniszkusz- és térdkalácstesztekkel a csavarodáskor vagy érkezéskor jelentkező térdfájdalom, akadás és instabilitásérzés okát keressük. A döntést több lelet együttese adja.","sheet":{"kind":"tests","tests":[{"name":"McMurray-teszt","alias":"","steps":"Hanyatt fekvés, a térdet maximálisan flektálod, majd a lábszárat kifelé vagy befelé rotálva fokozatosan extendálod.","positive":"Kattanás vagy fájdalom az ízületi résben.","tissue":"Meniszkusz (belső és külső)","point":"Külső rotációval a belső, belső rotációval a külső meniszkuszt vizsgálja. Önmagában nem bizonyító."},{"name":"Apley-teszt","alias":"Apley-kompressziós teszt","steps":"Hason fekvés, térd 90°-os flexióban. A sarok felől lefelé irányuló nyomás mellett a lábszárat befelé és kifelé rotálod.","positive":"Kompresszióra és rotációra fájdalom az ízületi résben.","tissue":"Meniszkusz","point":"Ha disztrakció melletti rotációra fáj, inkább szalagra vagy más, nem meniszkusz eredetű struktúrára gondolj."},{"name":"Thessaly-teszt","alias":"","steps":"A vizsgáló fogja a beteg két kezét. Egylábas állásban, 20°-os térdflexióban a beteg törzsét és térdét befelé–kifelé rotálja. Az ép oldallal kezd.","positive":"Ízületi rés fájdalma, beakadás- vagy akadásérzés.","tissue":"Meniszkusz","point":"Terhelt helyzetű teszt. Figyelj az elesésre, biztosítsd a két kéz megtámasztását."},{"name":"Patella apprehenziós teszt","alias":"","steps":"Hanyatt fekvés, enyhén hajlított térd. A m. quadriceps femoris ellazult, a térdkalácsot lassan oldalra (lateral felé) tolod.","positive":"Félelem jelentkezik, a beteg a quadriceps megfeszítésével védekezik.","tissue":"Patellastabilizátorok (lig. patellofemorale med.)","point":"Korábbi patellaficam vagy subluxatio igazolására hasznos. Óvatosan végezd, ne provokálj ficamot."}]},"keypoints":["Az ízületi rés fájdalma fontos, meniszkusz-sérülésre utaló lelet","A meniszkusztesztek egyenként nem döntőek, több leletet vess össze","A teljes extenziót gátló beakadás (locking) orvosi konzultációt igényel","A patellateszteknél figyeld a félelmi reakciót, és óvatosan végezd","Terhelt helyzetű teszteknél az elesés megelőzésére biztosíts megtámasztást"],"case":{"text":"35 éves férfi. Hajlított térddel csavarodott meg, néhány óra múlva a térd megduzzadt. Lépcsőn a térd belső oldalán akadást érez. A belső ízületi rés nyomásérzékeny, a McMurray-teszt fájdalmas, kattanással.","answer":"Belső meniszkusz-sérülés gyanúja. Vizsgáld a társult szalagsérülést is, és irányítsd orvosi képalkotó vizsgálatra. Beakadás esetén ne erőltesd az extenziót."},"questions":[{"level":"Alap","q":"Az ábrán melyik teszt ad kompressziót és rotációt hason fekvésben, 90°-os térdnél?","options":["McMurray-teszt","Thessaly-teszt","Apley-teszt","Patella apprehenziós teszt"],"answer":2,"exp":"Az Apley-teszt hason fekvésben, 90°-os térdflexióban a sarok felőli nyomás mellett rotál, és a meniszkuszt vizsgálja."},{"level":"Alap","q":"Az ábra összefoglalója szerint melyik lelet utal meniszkusz-sérülésre?","options":["Az ízületi rés fájdalma","Fájdalom a térdkalács felett","Fájdalom a tuberositas tibiaen","Fájdalom a comb hátsó felszínén"],"answer":0,"exp":"Az ízületi rés (a combcsont és a sípcsont közti rés) fájdalma meniszkusz-sérülésre utal."},{"level":"Középhaladó","q":"A McMurray-tesztben a lábszár külső rotációja melletti extenzió elsősorban mit vizsgál?","options":["Külső meniszkusz","Belső meniszkusz","Elülső keresztszalag","Térdkalácsszalag"],"answer":1,"exp":"Külső rotációval a belső, belső rotációval a külső meniszkuszt vizsgáljuk."},{"level":"Középhaladó","q":"Mi a pozitív lelet a patella apprehenziós tesztben?","options":["Kattanás a térdkalácsnál","Belső ízületi rés fájdalma","Korlátozott térdextenzió","Félelem és quadriceps-védekezés"],"answer":3,"exp":"Ha a térdkalács oldalra tolásakor a beteg félelmet mutat és a quadricepsszel védekezik, a teszt pozitív: patellainstabilitásra utal."},{"level":"Klinikai","q":"18 éves nő. Ugrásból érkezéskor úgy érezte, kiugrott a térdkalácsa, majd magától visszaugrott. Melyik vizsgálat a legmegfelelőbb?","options":["Patella apprehenziós teszt","Hátsó fiók teszt","Thompson-teszt","Varus stresszteszt"],"answer":0,"exp":"Patellaficamra vagy subluxatióra utaló lefolyás. Az instabilitást a patella apprehenziós teszttel ellenőrzöd."},{"level":"Klinikai","q":"40 éves férfi. Régóta akad a térde belül, ma reggel óta nem tudja teljesen kinyújtani. Mi a helyes teendő?","options":["Erős passzív extenzióval visszahelyezni","Orvoshoz fordulni, vizsgálatot kérni","A Thessaly-tesztet ismételni","Azonnal erősítést kezdeni"],"answer":1,"exp":"Az extenziót gátló beakadás beékelődött meniszkuszra utalhat, orvosi vizsgálat kell. Kerüld az erőltetett extenziót és a tesztek ismétlését."}],"seccion":"Speciális tesztek régiónként","grupo":"Csípő és térd","icono":"🦵","mapa":"img/mapas/t20.jpg","fichas":[{"nombre":"McMurray-teszt","img":"img/fichas/mcmurray.jpg"}],"secuencias":[]},"21":{"id":21,"title":"Boka és láb","lead":"A boka- és lábtesztekkel a ficam okozta szalagsérülést és az Achilles-ín szakadását különítjük el. A törés lehetőségére mindig gondolni kell.","sheet":{"kind":"tests","tests":[{"name":"Thompson-teszt","alias":"Simmonds-teszt","steps":"Hason fekvés, a lábfej lelóg az ágy széléről. A m. triceps surae izomhasát összeszorítod.","positive":"Nincs plantarflexió a bokában, vagy egyértelműen kisebb, mint az ép oldalon.","tissue":"Achilles-ín","point":"Szakadás mellett is lehet aktív plantarflexió (pl. a lábujjhajlítókkal), ezért ez a teszt hasznos."},{"name":"Elülső fiók teszt (boka)","alias":"","steps":"Ülés vagy hanyatt fekvés, boka enyhe plantarflexióban. A sípcsont distalis részét rögzíted, a sarkat fogva a talust előre húzod.","positive":"Az ép oldalnál nagyobb elülső elmozdulás, bizonytalan végérzés.","tissue":"Lig. talofibulare anterius","point":"Az inverziós ficamban leggyakrabban sérülő szalagot vizsgálja. Akut szakban a fájdalomra figyelve végezd."},{"name":"Talusbillentés-teszt","alias":"Varus stresszteszt","steps":"A lábszár distalis részét rögzíted, a calcaneust fogva a bokát inverzió irányába billented.","positive":"Az ép oldalnál nagyobb talusdőlés, fájdalom.","tissue":"Lig. calcaneofibulare (lig. talofib. ant.)","point":"Az elülső fiók teszttel együtt ítéld meg a külső szalagsérülés súlyosságát."},{"name":"Squeeze-teszt","alias":"","steps":"Hanyatt fekvés. A lábszár közepén a sípcsontot és a szárkapcsot két kézzel összeszorítod.","positive":"Fájdalom a boka felett, a sípcsont és a szárkapocs között.","tissue":"Distalis tibiofibularis szalagok (syndesmosis)","point":"Magas bokaficam gyanújakor használd. A törés kizárása is fontos."}]},"keypoints":["Inverziós ficamban a lig. talofibulare anterius sérül a leggyakrabban","Achilles-ín-szakadás mellett is lehet aktív plantarflexió","Csontos nyomásérzékenység vagy terhelési képtelenség esetén törésre gondolj, küldd orvoshoz","A szalagteszteket mindig az ép oldallal összevetve ítéld meg","A sípcsont és a szárkapocs közti fájdalom magas bokaficamra utalhat"],"case":{"text":"45 éves férfi. Teniszezés közben olyan érzése volt, mintha hátulról megrúgták volna. Lábujjhegyre nem tud állni. Hason fekvésben a m. triceps surae összeszorítására nincs plantarflexió.","answer":"Pozitív Thompson-teszt: Achilles-ín-szakadás gyanúja. Sürgősen irányítsd orvosi vizsgálatra. Az aktív plantarflexió megléte nem zárja ki a szakadást."},"questions":[{"level":"Alap","q":"Melyik struktúrát vizsgálja a Thompson-teszt?","options":["Lig. talofibulare anterius","Achilles-ín","Lig. calcaneofibulare","Talpi bőnye (aponeurosis plantaris)"],"answer":1,"exp":"A m. triceps surae összeszorításakor azt nézzük, létrejön-e plantarflexió: az Achilles-ín folytonosságát vizsgálja."},{"level":"Alap","q":"Melyik szalag sérül a leggyakrabban inverziós ficamban?","options":["Lig. talofibulare posterius","Lig. deltoideum","Lig. calcaneofibulare","Lig. talofibulare anterius"],"answer":3,"exp":"A sérülés többnyire plantarflexióval társult inverzióban jön létre, a lig. talofibulare anterius sérül a leggyakrabban. Súlyosabb esetben a lig. calcaneofibulare is."},{"level":"Középhaladó","q":"Elsősorban melyik szalagot vizsgálja a talusbillentés-teszt?","options":["Lig. calcaneofibulare","Lig. deltoideum","Achilles-ín","M. tibialis posterior ina"],"answer":0,"exp":"A calcaneust inverzióba billentve a talus dőlését figyeljük, így elsősorban a lig. calcaneofibularét vizsgáljuk."},{"level":"Középhaladó","q":"A squeeze-tesztnél fájdalom jelentkezik a boka felett. Mire gondolsz?","options":["Achilles-ín-szakadás","Talpi fasciitis","Distalis tibiofibularis szalagsérülés","Hallux valgus"],"answer":2,"exp":"Ha a lábszár közepének összeszorítása a distalis tibiofibularis ízületnél okoz fájdalmat, syndesmosis-sérülés (magas bokaficam) gyanúja áll fenn."},{"level":"Klinikai","q":"22 éves férfi, inverziós sérülés. Külboka előtt duzzanat, nyomásérzékenység; csontos nincs. Melyik teszt vizsgálja a lig. talofibulare anteriust?","options":["Elülső fiók teszt (boka)","Thompson-teszt","Lachman-teszt","Squeeze-teszt"],"answer":0,"exp":"A lig. talofibulare anterius fékezi a talus előremozdulását. A boka elülső fiók tesztjével, az ép oldallal összevetve vizsgálod."},{"level":"Klinikai","q":"60 éves nő. Elesett és kibicsaklott a bokája. A külbokán csontos nyomásérzékenység van, terhelve nem tud járni. Mi a helyes teendő?","options":["Az elülső fiók tesztet ismételni","Törés gyanújával orvoshoz küldeni","Azonnal egyensúlygyakorlatok","Tapasszal járásgyakorlás"],"answer":1,"exp":"A csontos nyomásérzékenység és a terhelési képtelenség törésre utal. Stresszteszt és gyakorlatok előtt orvosi vizsgálat kell."}],"seccion":"Speciális tesztek régiónként","grupo":"Boka és láb","icono":"🦶","mapa":"img/mapas/t21.jpg","fichas":[{"nombre":"Thompson-teszt","img":"img/fichas/thompson.jpg"}],"secuencias":[{"nombre":"Thompson-teszt","rotulo":"Vizsgálja","texto":"Achilles-ín","frames":["img/mov/teste-thompson-1.jpg","img/mov/teste-thompson-2.jpg","img/mov/teste-thompson-3.jpg"]}]},"22":{"id":22,"title":"Neurológiai és neurodinámiás tesztek","lead":"A neurodinámiás tesztekben az idegrendszert lépésenként nyújtjuk, és a tünetek reprodukálódását figyeljük. Segítenek elkülöníteni az ideggyöki és a perifériás ideg eredetű fájdalmat.","sheet":{"kind":"tests","tests":[{"name":"Lasègue-jel (SLR-teszt)","alias":"Egyenes lábemelés teszt","steps":"Hanyatt fekvésben a nyújtott térdű alsó végtagot passzívan emeled. Rögzíted a tünet megjelenésének szögét, és dorsalflexióval ellenőrzöd a fokozódást.","positive":"A tünetek reprodukálódnak, pl. a farból az alsó végtag hátsó felszínére sugárzó fájdalom.","tissue":"N. ischiadicus, L5 és S1 ideggyök stb.","point":"A hamstringfeszülés elkülönítésére hasznos a boka dorsalflexiója vagy a nyakflexió hozzáadása."},{"name":"N. femoralis nyújtási teszt","alias":"FNST (fordított Lasègue)","steps":"Hason fekvésben a térdet passzívan flektálod. Szükség esetén csípőextenziót is adsz.","positive":"A comb elülső felszínére sugárzó fájdalom.","tissue":"N. femoralis, L2–L4 ideggyökök","point":"Különítsd el a quadriceps-feszüléstől. A felső ágyéki ideggyöki érintettség vizsgálatára használjuk."},{"name":"Slump teszt","alias":"","steps":"Ülésben sorban: törzsflexió → nyakflexió → térdextenzió → boka dorsalflexió, majd a nyakflexiót feloldva figyeled a változást.","positive":"A tünetek reprodukálódnak, és a nyakflexió feloldására enyhülnek.","tissue":"Idegrendszer a gerinccsatornától az alsó végtagig","point":"Lépésenként haladj, és a tünet megjelenésekor állj meg. Vesd össze a két oldalt."},{"name":"Felső végtagi idegfeszítési teszt","alias":"ULNT1 (n. medianus)","steps":"Hanyatt fekvés: vállöv depresszió, vállabdukció, alkarszupináció, csukló- és ujjextenzió, külső rotáció, könyökextenzió; végül nyaki oldalhajlítás.","positive":"A felső végtagi tünetek reprodukálódnak, és nyaki oldalhajlításra változnak.","tissue":"N. medianus, nyaki ideggyökök","point":"Vesd össze az ép oldallal. Ha távoli testrész mozgatása változtat a tüneten, valószínűbb az ideg eredet."}]},"keypoints":["Az idegteszteket a tünetreprodukció és az oldalkülönbség alapján ítéld meg","Ha távoli testrész mozgatása változtat a tüneten, ideg eredetre gondolj","Az izomfeszülést és az ideg eredetű tünetet külön dokumentáld","A tünet megjelenésekor állj meg, ne provokálj erős fájdalmat","Progrediáló bénulás vagy hólyag- és végbélzavar esetén azonnal orvoshoz"],"case":{"text":"42 éves férfi. Nehéz teher emelése után derékfájás és a jobb alsó végtag hátsó felszínén fájdalom jelentkezett. Az SLR-teszt a jobb alsó végtag hátsó felszínén reprodukálja a kisugárzó fájdalmat, dorsalflexióra fokozódik.","answer":"Ágyéki ideggyöki eredetű tünetekre utaló lelet. Izomerő, érzés és reflexek alapján határozd meg az érintett szegmentumot. Hólyag- és végbélzavar vagy progrediáló bénulás esetén azonnal küldd orvoshoz."},"questions":[{"level":"Alap","q":"Melyik ideget nyújtja elsősorban az SLR-teszt?","options":["N. medianus","N. femoralis","N. ischiadicus","N. ulnaris"],"answer":2,"exp":"Nyújtott térddel emelve az alsó végtagot a hátsó felszínen futó n. ischiadicus és az alsó ágyéki ideggyökök nyúlnak meg."},{"level":"Alap","q":"Milyen testhelyzetben végezzük az n. femoralis nyújtási tesztet?","options":["Hason fekvés","Hanyatt fekvés","Nyújtott ülés","Állás"],"answer":0,"exp":"Hason fekvésben a térdet flektálva a comb elülső felszínén futó n. femoralist nyújtjuk."},{"level":"Középhaladó","q":"Az SLR-tesztben a boka dorsalflexiója fokozta a tüneteket. Mire utal ez?","options":["Hamstringrövidülés","Ideg eredetű tünet","Csípőkontraktúra","Bokaficam"],"answer":1,"exp":"A dorsalflexió az izomhossz változtatása nélkül növeli az ideg feszülését. Ha a tünet fokozódik, ideg eredetre utal."},{"level":"Középhaladó","q":"A slump tesztben a nyakflexió feloldására enyhültek az alsó végtagi tünetek. Mire gondolsz?","options":["Izomnyújtási fájdalom","Ízületi instabilitás","Pszichés eredetű fájdalom","Az idegrendszer fokozott érzékenysége"],"answer":3,"exp":"A nyak mozgatása nem hat az alsó végtag izmaira, így a tünetváltozás az idegrendszer érintettségére utal."},{"level":"Klinikai","q":"50 éves nő. Zsibbadás a comb elejétől a térd belső oldaláig. Hason fekve a térdflexió reprodukálja a combelülső fájdalmat. Melyik szegmentum gyanús?","options":["L2–L4","L5","S1","C6"],"answer":0,"exp":"Pozitív n. femoralis nyújtási teszt és combelülső tünetek: felső ágyéki (L2–L4) ideggyöki érintettség gyanúja."},{"level":"Klinikai","q":"38 éves férfi. Az SLR-teszt reprodukálja az alsó végtagi fájdalmat. Mostanában nehezen vizel, a gát területén csökkent az érzés. Mi a helyes teendő?","options":["Az SLR-tesztet ismételten ellenőrizni","Ágyéki izomerősítés","Azonnal orvoshoz küldeni","Az idegcsúsztatást folytatni"],"answer":2,"exp":"A vizelési zavar és a gáttáji érzéscsökkenés cauda equina-szindrómára utaló vörös zászló. Azonnali orvosi vizsgálat kell."}],"seccion":"Speciális tesztek régiónként","grupo":"Neurológiai tesztek","icono":"🧠","mapa":"img/mapas/t22.jpg","fichas":[{"nombre":"Lasègue-jel (SLR-teszt)","img":"img/fichas/lasegue.jpg"}],"secuencias":[{"nombre":"Lasègue-jel","rotulo":"Vizsgálja","texto":"n. ischiadicus (L4–S1)","frames":["img/mov/teste-lasegue-1.jpg","img/mov/teste-lasegue-2.jpg","img/mov/teste-lasegue-3.jpg"]}]},"23":{"id":23,"title":"Subacromialis impingement és rotátorköpeny-szakadás","lead":"A subacromialis impingementben emeléskor a rotátorköpeny és a bursa subacromialis irritálódik, és fájdalmat okoz. Fontos elkülöníteni a rotátorköpeny-szakadástól, és fokozatos terápiás gyakorlatokat adni.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Emeléskor a rotátorköpeny (főleg a m. supraspinatus ina) és a bursa subacromialis irritálódik és fáj. Életkor, túlterhelés vagy trauma talaján rotátorköpeny-szakadás alakulhat ki."},{"h":"Fő tünetek","t":"Emeléskor jelentkező fájdalom (fájdalmas ív), éjszakai fájdalom, nehéz az érintett oldalon feküdni. Szakadásnál az emelés és a külső rotáció ereje csökken."},{"h":"Vizsgálati szempontok","t":"Neer- és Hawkins–Kennedy-teszttel az impingementet, Jobe-teszttel és a külső rotáció erejével a rotátorköpeny működését vizsgálod. Értékeld a lapocka mozgását és a testtartást is."},{"h":"A kezelés menete","t":"Fájdalomcsillapítás és az aktivitás szabályozása → a ROM javítása → a rotátorköpeny és a lapockakörüli izmok fokozatos erősítése → mozgásgyakorlás, visszatérés a munkába és a sportba."},{"h":"Óvatosság, ellenjavallat","t":"Kerüld a fájdalmat fokozó, ismételt emelést. A terhelést a szakadás mértékéhez és az orvosi tervhez igazítsd, ne erőltesd a nyújtást."},{"h":"Orvoshoz irányítás jelei","t":"Trauma utáni hirtelen emelési képtelenség, progrediáló gyengeség, romló nyugalmi fájdalom, láz vagy duzzanat, zsibbadás és más neurológiai tünet."}]},"keypoints":["A fájdalmas ív és az éjszakai fájdalom gyakori panasz","Az emelés és a külső rotáció gyengesége rotátorköpeny-szakadásra utalhat","A lapocka mozgását és a testtartást is értékeld","A gyakorlatok terhelését fájdalomhatáron belül, fokozatosan emeld","Trauma utáni hirtelen emelési képtelenségnél irányítsd orvoshoz"],"case":{"text":"62 éves férfi. Hónapok óta fáj a válla abdukcióban, éjszakai fájdalma is van. Az emelés középső tartományában erős a fájdalom, a Jobe-teszt fájdalmas, és gyengeség is látható.","answer":"A m. supraspinatus inának károsodása vagy rotátorköpeny-szakadás gyanúja. Kérd ki az orvosi képalkotó lelet és a terv eredményét, és fájdalomhatáron belül haladj a ROM-mal, valamint a rotátorköpeny és a lapockakörüli izmok gyakorlataival. Kerüld a fájdalmat fokozó, ismételt emelést."},"questions":[{"level":"Alap","q":"Melyik ín halad az acromion alatt, és irritálódik könnyen emeléskor?","options":["M. supraspinatus ina","M. teres minor ina","M. pectoralis major ina","M. triceps brachii ina"],"answer":0,"exp":"A m. supraspinatus ina az acromion alatt fut, ezért emeléskor a bursa subacromialisszal együtt könnyen irritálódik."},{"level":"Alap","q":"Hogyan nevezzük, ha a vállemelésnek csak a középső tartományában jelentkezik fájdalom?","options":["Váll–kéz-szindróma","Éjszakai fájdalom","Fájdalmas ív","Drop arm jel"],"answer":2,"exp":"Ha az emelés közben jelentkezik fájdalom, és tovább emelve enyhül, fájdalmas ívről beszélünk. Subacromialis eltéréseknél látjuk."},{"level":"Középhaladó","q":"Mit vizsgál elsősorban a Hawkins–Kennedy-teszt?","options":["Elülső vállinstabilitás","Subacromialis impingement","Acromioclavicularis ficam","Thoracic outlet szindróma"],"answer":1,"exp":"90°-os vállflexióban belső rotációt adva azt nézzük, beszorulnak-e a struktúrák az acromion alatt és fájnak-e: impingementteszt."},{"level":"Középhaladó","q":"Melyik lelet utal leginkább rotátorköpeny-szakadásra?","options":["Korlátozott könyökflexió","Megnövekedett szorítóerő","Csak ujjzsibbadás","Az emelés és külső rotáció gyengesége"],"answer":3,"exp":"A rotátorköpeny az emelésben és a külső rotációban vesz részt. A gyengeség szakadásra utalhat, ezt orvosi képalkotás igazolja."},{"level":"Klinikai","q":"58 éves nő. Elesése óta nem tudja felemelni a karját. Passzívan emelhető, aktívan nem. Mi a legvalószínűbb?","options":["Fagyott váll","Rotátorköpeny-szakadás","Cervicalis spondylosis","Vállficam"],"answer":1,"exp":"Ha passzívan mozog, de aktívan nem emelhető, izom-ín működészavarra utal; trauma után rotátorköpeny-szakadás gyanús. Fagyott vállnál a passzív mozgás is korlátozott."},{"level":"Klinikai","q":"45 éves férfi, tartós emelési fájdalommal járó subacromialis impingement. Melyik a megfelelő kezdeti terápiás gyakorlat?","options":["Fájdalmat tűrve ismételt emelés","Emelés nehéz súlyzóval","Rotátorköpeny-gyakorlat fájdalomhatáron belül","Teljes nyugalom fenntartása"],"answer":2,"exp":"A fájdalmat nem fokozó rotátorköpeny- és lapockakörüli gyakorlatokkal kezdj, és fokozatosan emeld a terhelést."}],"seccion":"Sérülések és rehabilitáció","grupo":"Váll","icono":"💪","mapa":"img/mapas/t23.jpg","fichas":[],"secuencias":[]},"24":{"id":24,"title":"Fagyott váll","lead":"A fagyott vállban a fájdalom és a mozgásbeszűkülés fokozatosan alakul ki; közép- és időskorban gyakori. A kezelést a betegség fázisához kell igazítani.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"A vállízületi tok gyulladása és fibrózisa fájdalmat és mozgásbeszűkülést okoz. Az ok gyakran nem tisztázott; összefüggést írtak le a cukorbetegséggel."},{"h":"Fő tünetek","t":"Éjszakai fájdalom, nehézség a hajfésülésben és a kéz hát mögé vitelében. Az aktív és a passzív ROM is beszűkül, különösen a külső rotáció."},{"h":"Vizsgálati szempontok","t":"Vesd össze az aktív és a passzív ROM-ot, értékeld a fájdalom mértékét, az éjszakai fájdalmat és az ADL-nehézségeket. Fontos az elkülönítés más kórképektől, pl. rotátorköpeny-szakadástól."},{"h":"Rehabilitáció fázisonként","t":"Gyulladásos fázis: fájdalomcsillapítás és kímélő mozgatás. Merevedési fázis: nyújtás és ROM-gyakorlatok fájdalomhatáron belül. Oldódási fázis: a ROM és az izomerő visszanyerése."},{"h":"Óvatosság, ellenjavallat","t":"A gyulladásos fázisban az erős nyújtás ronthatja a fájdalmat. Kerüld a fájdalom eltűrését kívánó, erőltetett passzív mozgatást."},{"h":"Orvoshoz irányítás jelei","t":"Trauma utáni kezdet, hirtelen gyengeség, láz vagy duzzanat, általános tünetek (pl. fogyás), a nyugalmi fájdalom hirtelen romlása."}]},"keypoints":["Jellemző, hogy az aktív és a passzív ROM is beszűkül","Különösen a külső rotáció korlátozottsága feltűnő","A gyulladásos fázisban kerüld a fájdalmat fokozó nyújtást","Fázisonként válts kezelési célt","Különítsd el más kórképektől, pl. rotátorköpeny-szakadástól"],"case":{"text":"55 éves nő. Kiváltó ok nélkül kezdett fájni a válla, éjszaka a fájdalomtól nem tud aludni. Néhány hónap alatt nehézzé vált a hajfésülés és a kéz hát mögé vitele; a külső rotáció aktívan és passzívan is erősen korlátozott.","answer":"Fagyott váll gyanúja. Orvosi diagnózissal zárd ki a más kórképeket, és határozd meg az aktuális fázist. Erős fájdalom idején kerüld az erős nyújtást; fájdalomcsillapítással és kímélő mozgatással kezdj."},"questions":[{"level":"Alap","q":"Melyik mozgás korlátozott különösen fagyott vállban?","options":["Könyökflexió","Csukló dorsalflexiója","Lapockaemelés","Váll külső rotációja"],"answer":3,"exp":"Fagyott vállban a tok zsugorodása miatt a váll több irányban korlátozott, különösen a külső rotáció."},{"level":"Alap","q":"Fagyott vállban melyik az a fázis, amikor a fájdalom enyhül, és a mozgásbeszűkülés kerül előtérbe?","options":["Gyulladásos fázis","Merevedési fázis","Oldódási fázis","Akut fázis"],"answer":1,"exp":"Amikor a gyulladásos fázis erős fájdalma csillapodik, a mozgásbeszűküléssel jellemzett merevedési fázis következik, majd az oldódási fázis."},{"level":"Középhaladó","q":"Melyik lelet segít elkülöníteni a fagyott vállat a rotátorköpeny-szakadástól?","options":["Éjszakai fájdalom megléte","A passzív ROM korlátozottsága","Életkor","A fájdalom helye"],"answer":1,"exp":"Fagyott vállban a passzív ROM is korlátozott. Rotátorköpeny-szakadásnál passzívan viszonylag jól mozog, de aktívan gyakran nehezen emelhető."},{"level":"Középhaladó","q":"Mi a legmegfelelőbb kezelés a fagyott váll gyulladásos fázisában?","options":["Fájdalomcsillapítás, kímélő mozgatás","Erős passzív nyújtás","Nagy terhelésű erősítés","Sportba való visszatérés gyakorlása"],"answer":0,"exp":"A gyulladásos fázisban erős a fájdalom, az erős nyújtás ronthat. Fájdalomcsillapítás és fájdalmat nem fokozó mozgatás a fő elem."},{"level":"Klinikai","q":"52 éves nő, fagyott váll merevedési fázisban. A fájdalom enyhe, a külső rotáció és a kéz hát mögé vitele korlátozott. Mi a megfelelő kezelés?","options":["Teljes nyugalom","Rögzítés háromszögkendővel","ROM-gyakorlat fájdalomhatáron belül","Fájdalmat tűrő erős nyújtás"],"answer":2,"exp":"A merevedési fázisban a fájdalom már enyhült, ezért fájdalomhatáron belül haladj a nyújtással és a ROM-gyakorlatokkal."},{"level":"Klinikai","q":"60 éves férfi. A vállfájdalom és mozgásbeszűkülés mellett az utóbbi időben lefogyott, és erős nyugalmi fájdalma van. Mi a helyes teendő?","options":["Orvoshoz küldeni","A ROM-gyakorlatok fokozása","Csak hőkezelés és megfigyelés","Izomerősítés megkezdése"],"answer":0,"exp":"A fogyás és az erős nyugalmi fájdalom súlyos betegségre utaló vörös zászló. Először orvosi vizsgálatra irányítsd."}],"seccion":"Sérülések és rehabilitáció","grupo":"Váll","icono":"💪","mapa":"img/mapas/t24.jpg","fichas":[],"secuencias":[]},"25":{"id":25,"title":"Rotátorköpeny-varrat után","lead":"A rotátorköpeny-varrat utáni rehabilitáció a varrt ín védelme mellett fokozatosan állítja vissza a ROM-ot és az izomerőt. Alapfeltétel az orvos által megadott időpontok és korlátozások betartása.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"A szakadt rotátorköpenyt műtéttel visszarögzítik a csonthoz. A varrt ín csonthoz gyógyulása időbe telik, a túl korai terhelés újraszakadást okozhat."},{"h":"Fő tünetek","t":"Posztoperatív és éjszakai fájdalom, mozgásbeszűkülés, gyengeség. Az ortézis miatt a vállöv és a nyak feszes lehet, a könyök és a kéz mozgása is csökkenhet."},{"h":"Vizsgálati szempontok","t":"Értékeld a fájdalmat, a passzív és aktív ROM-ot, a lapocka mozgását, az izomerőt és az ADL-t. Nézd meg a műtéti leírást és az orvosi utasítást (tiltott helyzetek, időpontok)."},{"h":"Rehabilitáció fázisonként","t":"Védelmi fázis (ortézis, passzív mozgatás) → aktív asszisztált és aktív mozgatás → fokozatos izomerősítés → visszatérés a napi tevékenységekhez, a munkához és a sporthoz."},{"h":"Óvatosság, ellenjavallat","t":"Kerüld az előírt időpont előtti aktív emelést és ellenállásos gyakorlatot, valamint a varrt ínt erősen nyújtó helyzeteket. A könyököt és az ujjakat rögzítés alatt is mozgasd."},{"h":"Orvoshoz irányítás jelei","t":"A fájdalom hirtelen fokozódása vagy az emelőerő csökkenése (újraszakadás gyanúja), a seb körüli bőrpír, duzzanat, melegség, láz, zsibbadás megjelenése."}]},"keypoints":["Az időpontokat és a tiltott helyzeteket az orvosi utasításból és a műtéti leírásból ellenőrizd","A védelmi fázisban védd a varrt ínt, a passzív mozgatás áll a középpontban","Rögzítés alatt is gyakoroltasd a könyököt, az ujjakat és a lapockát","Ellenállásos gyakorlatot az előírt időponttól, fokozatosan adj","Az emelőerő hirtelen csökkenésekor újraszakadásra gondolj, küldd orvoshoz"],"case":{"text":"60 éves férfi, korai posztoperatív szak rotátorköpeny-varrat után, ortézist visel. Mivel gyorsan vissza akar térni a munkába, saját maga gyakorolta a kar emelését.","answer":"A védelmi fázisban az előíratlan aktív emelés megterheli a varrt ínt. Ellenőrizd az orvosi utasítást, a megengedett passzív mozgatásra és a könyök–ujjak gyakorlataira koncentrálj, és magyarázd el, miért fontos az időpontok betartása."},"questions":[{"level":"Alap","q":"Mi az ortézis fő célja a rotátorköpeny-varrat utáni korai szakban?","options":["Izomerő fokozása","ROM növelése","A varrt ín védelme","Ödéma megelőzése"],"answer":2,"exp":"A védelmi fázisban az ortézis rögzít, és óvja a varrt ínt, amíg az a csonthoz nem gyógyul."},{"level":"Alap","q":"A rotátorköpeny-varrat utáni rehabilitációban mit vezetünk be utolsóként?","options":["Ortézises rögzítés","Passzív mozgatás","Aktív asszisztált mozgatás","Ellenállásos gyakorlat"],"answer":3,"exp":"A védelmi fázis rögzítése és passzív mozgatása után az aktív asszisztált és aktív mozgatás jön, végül az ellenállásos izomerősítés."},{"level":"Középhaladó","q":"Melyik mozgást kell kerülni a varrat utáni védelmi fázisban?","options":["A váll előírás előtti aktív emelése","A könyök aktív hajlítása–nyújtása","Ujjgyakorlatok","Az előírt passzív mozgatás"],"answer":0,"exp":"A védelmi fázisban az előíratlan aktív vállemelés megterheli a varrt ínt. A könyök és az ujjak mozgatása rögzítés alatt is folytatandó."},{"level":"Középhaladó","q":"Mit kell először ellenőrizni, amikor a posztoperatív gyakorlatok menetét tervezed?","options":["Csak a beteg kívánságát","Az orvosi utasítást és a műtéti leírást","Az ép oldal izomerejét","Csak az életkort"],"answer":1,"exp":"A szakadás méretétől és a varrattechnikától függően eltérnek az időpontok és a tiltott helyzetek, ezért nézd meg az utasítást és a leírást."},{"level":"Klinikai","q":"65 éves nő, rotátorköpeny-varrat után jól haladt, de egy tárgy felemelésekor fájdalmat érzett, és hirtelen nem tudja emelni a karját. Mi a teendő?","options":["Az ellenállásos gyakorlat fokozása","Ugyanazon gyakorlatok folytatása","Erős nyújtás","Jelezni az orvosnak, vizsgálatot kérni"],"answer":3,"exp":"A hirtelen fájdalom és emelőerő-csökkenés újraszakadásra utalhat. Állítsd le a gyakorlatokat, és kérj orvosi vizsgálatot."},{"level":"Klinikai","q":"58 éves férfi, rotátorköpeny-varrat után ortézisben. Könyök- és ujjmerevségre panaszkodik. Mi a helyes teendő?","options":["Könyök- és ujjgyakorlatok tanítása","A váll aktív emelésének megkezdése","Semmit, a rögzítés folytatása","Ellenállásos vállgyakorlat"],"answer":0,"exp":"Rögzítés alatt is mozgasd a könyököt és az ujjakat a merevség megelőzésére. A váll aktív emelése és az ellenállás várjon az előírt időpontig."}],"seccion":"Sérülések és rehabilitáció","grupo":"Váll","icono":"💪","mapa":"img/mapas/t25.jpg","fichas":[],"secuencias":[]},"26":{"id":26,"title":"Tendinopátiák","lead":"Tendinopátiában az ín nem tud alkalmazkodni az ismétlődő terheléshez, és fájdalom, funkciócsökkenés alakul ki. A gyógyulás kulcsa nem a pihenés, hanem a terhelés szabályozása és fokozatos emelése.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Az ínt érő ismétlődő terhelés meghaladja a regenerációt, az ín szerkezete és működése megváltozik, és fájdalom jelentkezik. Gyakori kiváltó ok az edzésmennyiség hirtelen növelése."},{"h":"Fő tünetek","t":"Fájdalom és merevség a mozgás elején és másnap reggel, az ín helyi nyomásérzékenysége. Mozgás közben enyhülhet, terhelés után romolhat."},{"h":"Vizsgálati szempontok","t":"Vizsgáld az ín nyomásérzékenységét, a fájdalmat terhelésre (egylábas sarokemelés, egylábas guggolás), és kérdezz rá az edzésmennyiség, a cipő és a talaj változására."},{"h":"A kezelés menete","t":"A terhelés szabályozása → izometriás gyakorlatok → izotóniás (excentrikust is tartalmazó) erősítés → gyors mozgások, pl. ugrások → visszatérés a sportba."},{"h":"Óvatosság, ellenjavallat","t":"A teljes pihentetés csökkentheti az ín terhelhetőségét. Kerüld a fájdalmat jelentősen rontó terhelést és a másnapig megmaradó erős fájdalmat."},{"h":"Orvoshoz irányítás jelei","t":"Hirtelen szakadásérzés vagy pattanó hang, egyértelmű gyengeség, erős duzzanat és melegség, nem javuló éjszakai vagy nyugalmi fájdalom."}]},"keypoints":["Az edzésmennyiség hirtelen növelése gyakran kivált tendinopátiát","Teljes pihentetés helyett a fájdalomhoz igazítva szabályozd a terhelést","A terhelés utáni és másnapi fájdalom alapján igazítsd a terhelés mennyiségét","Izometriás gyakorlatoktól haladj fokozatosan a nagyobb terhelés felé","Szakadásérzés vagy hirtelen gyengeség esetén küldd orvoshoz"],"case":{"text":"28 éves futó férfi. Mióta hirtelen megnövelte a futótávot, reggelente tartósan merev és fájdalmas az Achilles-ína. A futás elején fáj, közben enyhül. Az ín középső részén nyomásérzékenység van.","answer":"Achilles-tendinopátia gyanúja. Ne teljes pihentetést javasolj, hanem szabályozd a futómennyiséget, és a fájdalomhoz igazítva haladj fokozatos terheléssel, pl. sarokemeléssel. Szakadásérzés vagy gyengeség esetén küldd orvoshoz."},"questions":[{"level":"Alap","q":"Melyik a tendinopátia tipikus kiváltó oka?","options":["Hosszú pihenés","Az edzésmennyiség hirtelen növelése","Elegendő alvás","Javuló hajlékonyság"],"answer":1,"exp":"Az ín regenerációját meghaladó terhelés, különösen az edzésmennyiség hirtelen növelése a tendinopátia tipikus kiváltó oka."},{"level":"Alap","q":"Milyen fájdalomjellemző gyakori tendinopátiában?","options":["Csak éjszakai erős fájdalom","Nyugalomban folyamatosan romlik","Mindig azonos erősségű","Mozgáskezdeti fájdalom, reggeli merevség"],"answer":3,"exp":"A mozgás elején és másnap reggel jelentkezik fájdalom és merevség, ami mozgás közben gyakran enyhül."},{"level":"Középhaladó","q":"A tendinopátia fokozatos terhelésében mit vezetünk be viszonylag későn?","options":["Izometriás gyakorlat","Lassú izomerősítés","Gyors mozgások, pl. ugrások","A terhelés szabályozása"],"answer":2,"exp":"A fájdalmat kontrollálva izometriás és izotóniás gyakorlatokkal növeled a terhelhetőséget, majd gyors mozgásokra, pl. ugrásokra térsz át."},{"level":"Középhaladó","q":"Mi a megfelelő támpont a tendinopátia terhelésének újragondolásához?","options":["A fájdalom változása másnap","A testsúly változása","A hőmérséklet","Az edzés napszaka"],"answer":0,"exp":"Ne csak a mozgás közbeni, hanem a másnapi fájdalom és merevség változását is figyeld, és ehhez igazítsd a terhelést."},{"level":"Klinikai","q":"22 éves röplabdázó nő. Ugrások után fáj a térdkalács alsó csúcsa, a térdkalácsszalag nyomásérzékeny. Mi a legvalószínűbb?","options":["Elülső keresztszalag-sérülés","Patellaris tendinopátia","Meniszkusz-sérülés","Patellaficam"],"answer":1,"exp":"Az ismételt ugrások és a térdkalács alsó csúcsának, illetve a térdkalácsszalagnak a nyomásérzékenysége patellaris tendinopátiára jellemző."},{"level":"Klinikai","q":"40 éves férfi, Achilles-tendinopátiával kezeled. Teniszezéskor úgy érezte, hátulról megrúgták; lábujjhegyre nem tud állni. Mi a teendő?","options":["Az excentrikus gyakorlat folytatása","A terhelés további emelése","A nyújtás fokozása","Szakadás gyanújával orvoshoz küldeni"],"answer":3,"exp":"A hirtelen ütésérzés és a lábujjhegyállás képtelensége Achilles-ín-szakadásra utal. Állítsd le a gyakorlatokat, és irányítsd orvosi vizsgálatra."}],"seccion":"Sérülések és rehabilitáció","grupo":"Sport, inak és izmok","icono":"🏃","mapa":"img/mapas/t26.jpg","fichas":[],"secuencias":[]},"27":{"id":27,"title":"Bokaficam","lead":"A bokaficam az egyik leggyakoribb sportsérülés; többnyire plantarflexióval társult inverzióban jön létre. Az újabb ficam megelőzésében a proprioceptív tréning kulcsfontosságú.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Plantarflexióval társult inverzióban a külső szalagok sérülnek. Leggyakrabban a lig. talofibulare anterius sérül, súlyosabb esetben a lig. calcaneofibulare is."},{"h":"Fő tünetek","t":"Fájdalom, duzzanat és bevérzés a külboka körül, terhelési fájdalom. A beteg instabilitásérzésről vagy ismétlődő ficamokról is beszámolhat."},{"h":"Vizsgálati szempontok","t":"Sérülési mechanizmus, a nyomásérzékenység helye, terhelhetőség, elülső fiók teszt és talusbillentés-teszt. Ne nézd el a törést és más szalagok sérülését."},{"h":"Rehabilitáció fázisonként","t":"1 védelem, hűtés, kompresszió, felpolcolás → 2 mobilitás és fokozatos terhelés → 3 izomerősítés és propriocepció → 4 futás, ugrás, visszatérés a sportba."},{"h":"Óvatosság, ellenjavallat","t":"Akut szakban kerüld a fájdalmat fokozó gyakorlatokat. Ha kimarad a proprioceptív és egyensúlygyakorlás, könnyen kiújul a ficam, és instabilitásérzés marad."},{"h":"Orvoshoz irányítás jelei","t":"Csontos nyomásérzékenység vagy terhelési képtelenség (törés gyanúja), kifejezett duzzanat vagy deformitás, zsibbadás, nem javuló fájdalom vagy ismétlődő instabilitás."}]},"keypoints":["A sérülési mechanizmus többnyire plantarflexióval társult inverzió","Leggyakrabban a lig. talofibulare anterius sérül","Csontos nyomásérzékenység vagy terhelési képtelenség esetén törésre gondolj","A proprioceptív tréning csökkenti a kiújulás kockázatát","A sportba való visszatérés fokozatos, az egylábas mozgások ellenőrzése után"],"case":{"text":"19 éves férfi. Focizás közben befelé bicsaklott a lába. Másnap a külboka előtt duzzanat és nyomásérzékenység van, csontos nyomásérzékenység nincs, terhelni tud. Az elülső fiók tesztnél az ép oldalnál nagyobb az előremozdulás.","answer":"Lig. talofibulare anterius sérülésével járó inverziós ficam gyanúja. Védelemmel, hűtéssel, kompresszióval, felpolcolással és fájdalomhoz igazított terheléssel kezdj, majd izomerősítés és proprioceptív gyakorlás után fokozatosan térjen vissza a sportba."},"questions":[{"level":"Alap","q":"Az ábrán melyik a bokaficam tipikus sérülési mechanizmusa?","options":["Dorsalflexióval társult everzió","Plantarflexióval társult inverzió","Dorsalflexióval társult inverzió","Plantarflexióval társult everzió"],"answer":1,"exp":"A bokaficam többnyire plantarflexióval társult inverzióban jön létre, és a külső oldali lig. talofibulare anterius sérül a leggyakrabban."},{"level":"Alap","q":"Az ábrán mi a 3. fázis tartalma?","options":["Védelem, hűtés, kompresszió, felpolcolás","Mobilitás és fokozatos terhelés","Izomerősítés és propriocepció","Futás, visszatérés a sportba"],"answer":2,"exp":"1. fázis: védelem, hűtés, kompresszió, felpolcolás; 2.: mobilitás és terhelés; 3.: izomerősítés és propriocepció; 4.: visszatérés a sportba."},{"level":"Középhaladó","q":"Melyik fázisban kezdődik a fokozatos terhelés?","options":["1. fázis","2. fázis","3. fázis","4. fázis"],"answer":1,"exp":"Az 1. fázis védelme után a 2. fázisban a mobilitás javításával együtt, a fájdalomhoz igazítva fokozatosan növeled a terhelést."},{"level":"Középhaladó","q":"Melyik gyakorlás különösen fontos a bokaficam kiújulásának megelőzésében?","options":["Hosszú rögzítés","Teljes nyugalom","Felső végtagi izomerősítés","Proprioceptív tréning"],"answer":3,"exp":"Az egyensúlydeszkás vagy egylábas állásos proprioceptív tréning csökkenti a kiújulás kockázatát."},{"level":"Klinikai","q":"24 éves nő. 3 héttel a ficam után szinte nincs fájdalma, de egylábas állásban inog a bokája. Melyik kezelés élvez elsőbbséget?","options":["Egyensúly- és proprioceptív gyakorlat","Hűtés és felpolcolás","Teljes nyugalom","Azonnali teljes sebességű sprint"],"answer":0,"exp":"A fájdalom csillapodott, de instabilitás maradt. Az egylábas állásos proprioceptív és erősítő gyakorlatok élveznek elsőbbséget, majd fokozatos visszatérés."},{"level":"Klinikai","q":"20 éves férfi. Sokszor ficamította már a bokáját, és a mindennapokban is inogni érzi. Mire gondolsz?","options":["Achilles-ín-szakadás","Talpi fasciitis","Krónikus bokainstabilitás","Hallux valgus"],"answer":2,"exp":"Az ismétlődő ficam és az instabilitásérzés krónikus bokainstabilitásra utal. A proprioceptív és erősítő gyakorlás fontos, szükség esetén orvosi konzultáció."}],"seccion":"Sérülések és rehabilitáció","grupo":"Sport, inak és izmok","icono":"🏃","mapa":"img/mapas/t27.jpg","fichas":[],"secuencias":[]},"28":{"id":28,"title":"Izomsérülések","lead":"Az izomsérülés sportsérülés, két fő formája az izomhúzódás (részleges szakadás) és az izomzúzódás. Gyakran kiújul, ezért fontos a fokozatos terhelés és a visszatérési kritériumok kijelölése.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"A húzódás főleg excentrikus kontrakcióban jön létre (a feszülő izom megnyúlik), leggyakrabban az izom-ín átmenetben. A zúzódás direkt külső erő okozta sérülés, főleg a m. quadriceps femorisban."},{"h":"Fő tünetek","t":"Fájdalom vagy szakadásérzés a sérüléskor, nyomásérzékenység, duzzanat, bevérzés, fájdalom nyújtásra és ellenállásra, erőcsökkenés. Súlyos esetben behúzódás tapintható."},{"h":"Vizsgálati szempontok","t":"Sérülési mechanizmus, nyomásérzékeny pont, nyújtási fájdalom (pl. SLR-szög oldalkülönbsége), fájdalom ellenállásra, járásminta. A súlyosságot a képalkotó leletekkel együtt az orvos ítéli meg."},{"h":"Rehabilitáció fázisonként","t":"Akut fázisban védelem és duzzanatkontroll. A fájdalomtól függően izometriás → koncentrikus → excentrikus munka, a futás is fokozatosan. Visszatérés előtt ellenőrizd a sportmozgásokat."},{"h":"Óvatosság, ellenjavallat","t":"Akut fázisban kerüld az erős nyújtást és az erős masszázst. Combzúzódás után az erős inger myositis ossificanst válthat ki. Ne dolgoztasd fájdalomban."},{"h":"Orvoshoz irányítás jelei","t":"Egyértelmű behúzódás vagy szakadásérzés, gyorsan fokozódó duzzanat, tartós erős fájdalom, zsibbadás vagy bőrszínváltozás (compartment-szindróma gyanúja)."}]},"keypoints":["A húzódás excentrikus kontrakcióban, az izom-ín átmenetben a leggyakoribb","Akut fázisban védelem és duzzanatkontroll, erős nyújtás nélkül","A terhelés sorrendje: izometriás → koncentrikus → excentrikus","A hamstringeknél építs be excentrikus edzést","A visszatérésről fájdalom, hajlékonyság, izomerő és sportmozgás alapján dönts"],"case":{"text":"20 éves férfi rövidtávfutó. Teljes sebességű sprint közben fájdalmat érzett a comb hátsó felén, és abbahagyta a versenyt. Másnap a m. biceps femoris felett nyomásérzékenység és bevérzés, SLR-nél oldalkülönbség és nyújtási fájdalom.","answer":"Hamstring-húzódásra gondolunk. Akut fázisban a védelem és a duzzanatkontroll az elsődleges, kerüld az erős nyújtást és masszázst. A fájdalomtól függően izometriás munkával kezdve fokozatosan emeld a terhelést. Behúzódás vagy más súlyos jel esetén orvoshoz."},"questions":[{"level":"Alap","q":"Hol alakul ki leggyakrabban izomhúzódás?","options":["Az izomhas közepén","Az izom-ín átmenetben","A csonthártyában","Az ín csonttapadásánál"],"answer":1,"exp":"A húzódás leggyakrabban az izom és az ín átmeneténél jön létre. A hamstringeknél főleg a m. biceps femoris caput longumát érinti."},{"level":"Alap","q":"Melyik kontrakciós forma mellett alakul ki leggyakrabban húzódás?","options":["Izometriás","Koncentrikus","Excentrikus","Izokinetikus"],"answer":2,"exp":"Excentrikus kontrakcióban, amikor a feszülő izom megnyúlik; tipikus helyzet a sprint lendítő fázisának vége."},{"level":"Középhaladó","q":"Mi a húzódás utáni erősítés szokásos sorrendje?","options":["Excentrikus → koncentrikus → izometriás","Izometriás → koncentrikus → excentrikus","Koncentrikus → izometriás → excentrikus","Rögtön maximális excentrikus munka"],"answer":1,"exp":"A fájdalomtól függően a kis terhelésű izometriás munkával kezdünk, majd koncentrikus, végül excentrikus kontrakció következik."},{"level":"Középhaladó","q":"Miért kerüljük combzúzódás után az erős masszázst és nyújtást?","options":["Myositis ossificanst válthat ki","Megszűnik az izomatrófia","Megrövidül az ín","Leáll az ideg regenerációja"],"answer":0,"exp":"A zúzódás utáni korai erős inger fokozhatja az izomon belüli vérzést, és myositis ossificans kialakulásához vezethet."},{"level":"Klinikai","q":"Labdarúgó: rúgáskor fájdalom jelentkezett a comb elülső felén, másnap is nyomásérzékeny és nyújtásra fáj. Mi a helyes teendő akut fázisban?","options":["Erős nyújtás","Védelem és duzzanatkontroll","Ellenőrzés teljes sprinttel","Erős masszázs"],"answer":1,"exp":"Akut fázisban a védelem és a duzzanatkontroll az elsődleges. Az erős nyújtás, a masszázs és a maximális mozgáspróba ronthatja a sérülést."},{"level":"Klinikai","q":"Középiskolás, combját erős ütés érte. A duzzanat gyorsan nő, erős fájdalomról és a láb zsibbadásáról panaszkodik. Mi az elsődleges teendő?","options":["Hőterápia","Nyújtás tanítása","Azonnali orvoshoz irányítás","Erősítés megkezdése"],"answer":2,"exp":"A gyorsan növő duzzanat, az erős fájdalom és a zsibbadás compartment-szindrómára utal, sürgős orvosi vizsgálat szükséges."}],"seccion":"Sérülések és rehabilitáció","grupo":"Sport, inak és izmok","icono":"🏃","mapa":"img/mapas/t28.jpg","fichas":[],"secuencias":[]},"29":{"id":29,"title":"Elülső keresztszalag- és meniszkuszsérülés","lead":"Az ACL-sérülés sportban, érkezéskor vagy irányváltáskor gyakori, és sokszor meniszkuszsérüléssel társul. A prognózist a korai vizsgálat és a mozgásminták újratanítása határozza meg.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Az ACL-sérülés többnyire nem kontakt, érkezéskor vagy irányváltáskor jön létre, szerepe van a térdvalgusnak és a lábszár rotációjának. A meniszkusz terhelés alatti rotációban sérül, gyakran az ACL-lel együtt."},{"h":"Fő tünetek","t":"ACL: pattanó hang a sérüléskor, haemarthros okozta duzzanat, térdkiszaladás (giving way). Meniszkusz: fájdalom az ízületi résben, akadásérzés, blokkolás (locking), mozgáskorlátozottság."},{"h":"Vizsgálati szempontok","t":"ACL: Lachman-teszt, elülső fiók teszt, pivot shift teszt. Meniszkusz: az ízületi rés nyomásérzékenysége, McMurray-teszt. A végleges diagnózist az orvos állítja fel."},{"h":"A kezelés menete","t":"Akut fázisban duzzanatkontroll, az extenziós ROM és a quadriceps-kontrakció biztosítása. Konzervatív kezelésről vagy szalagpótlásról az orvos dönt. Már a műtét előtt építsd fel az erőt és a ROM-ot."},{"h":"Óvatosság, ellenjavallat","t":"Az ismétlődő térdkiszaladás tovább károsíthatja a meniszkuszt és a porcot. Blokkolt térdnél ne erőltesd a ROM-gyakorlatokat. Figyelj a térd befelé esésére mozgás közben."},{"h":"Orvoshoz irányítás jelei","t":"Blokkolás miatt nem nyújtható térd, közvetlenül a sérülés után gyorsan kialakuló ízületi duzzanat, ismétlődő térdkiszaladás, tartós erős fájdalom, törésre utaló jelek."}]},"keypoints":["Az ACL-sérülés többnyire nem kontakt, veszélyes helyzet a térd befelé esése","Az ACL vizsgálatának alapja a Lachman-teszt","Meniszkuszsérülés: az ízületi rés nyomásérzékenysége és akadásérzés","Ha a térd blokkolás miatt nem nyújtható, orvoshoz","Megelőzésként tanítsd az érkezés és az irányváltás technikáját"],"case":{"text":"17 éves kosárlabdázó lány. Felugrásból érkezve a térde befelé esett, pattanó hangot hallott és elesett. Néhány óra alatt bedagadt a térde; a Lachman-teszt fokozott elülső elmozdulást és hiányzó végérzést mutat.","answer":"ACL-sérülés gyanúja. Akut fázisban a duzzanatkontroll, az extenziós ROM és a quadriceps-kontrakció biztosítása az elsődleges. Társuló meniszkuszsérülés miatt kérdezz rá a blokkolásra. Konzervatív kezelésről vagy pótlásról az orvos dönt; saját döntésből ne térjen vissza a sportba."},"questions":[{"level":"Alap","q":"Mi a nem kontakt ACL-sérülés tipikus helyzete?","options":["Térdvarus (a térd kifelé tér)","Térdvalgus (a térd befelé esik)","A térd hiperflexiója","Direkt ütés a térdkalácsra"],"answer":1,"exp":"A nem kontakt ACL-sérülés jellemzően érkezéskor vagy irányváltáskor jön létre, amikor a térd befelé esik (valgus)."},{"level":"Alap","q":"Melyik tünet jellemző a meniszkuszsérülésre?","options":["Blokkolás (locking)","Lógó lábfej","A patellareflex kiesése","Érzéscsökkenés a comb elülső felén"],"answer":0,"exp":"Ha a sérült meniszkuszrész beékelődik az ízületbe, a térd egy adott szögben elakad: ez a blokkolás."},{"level":"Középhaladó","q":"Melyik manuális teszt a legérzékenyebb ACL-sérülésre?","options":["McMurray-teszt","Hátsó fiók teszt","Lachman-teszt","Valgus stresszteszt"],"answer":2,"exp":"A Lachman-teszt enyhén hajlított térdnél előre húzza a sípcsontot, és az elmozdulást és a végérzést vizsgálja. Az ACL-vizsgálat alapja."},{"level":"Középhaladó","q":"Mi a pozitív McMurray-teszt lelete?","options":["Fokozott elülső tibiaelmozdulás","Kattanás és fájdalom rotáció melletti nyújtáskor","Patellainstabilitás-érzés","A belső ízületi rés kinyílása"],"answer":1,"exp":"Hajlított térdből a lábszárat rotálva nyújtjuk; ha az ízületi résben kattanás vagy fájdalom jelentkezik, meniszkuszsérülésre gyanakszunk."},{"level":"Klinikai","q":"Labdarúgó: irányváltáskor megcsavarta a térdét, azóta akad, és nem tudja teljesen kinyújtani. Mi a legvalószínűbb?","options":["Patellaris tendinopátia","Iliotibialis szalag szindróma","Meniszkuszsérülés okozta blokkolás","Osgood–Schlatter-betegség"],"answer":2,"exp":"Rotációs sérülés után a nyújtás képtelensége blokkolásra utal. Ne erőltesd a ROM-gyakorlatokat, irányítsd orvosi vizsgálatra."},{"level":"Klinikai","q":"ACL-sérülés utáni 2. nap, a térd duzzadt. Mi az elsődleges a konzervatív kezelés elején?","options":["Ugrásgyakorlás","Duzzanatkontroll és az extenzió biztosítása","Maximális irányváltás gyakorlása","Mély guggolás terheléssel"],"answer":1,"exp":"Kezdetben a duzzanatot kezeljük, biztosítjuk az extenziós ROM-ot és a quadriceps-kontrakciót. A nagy terhelés térdkiszaladást és másodlagos sérülést okozhat."}],"seccion":"Sérülések és rehabilitáció","grupo":"Sport, inak és izmok","icono":"🏃","mapa":"img/mapas/t29.jpg","fichas":[],"secuencias":[]},"30":{"id":30,"title":"Elülső keresztszalag-pótlás után","lead":"Az ACL-pótlás utáni rehabilitáció a graft védelme mellett fokozatosan állítja vissza a ROM-ot, az izomerőt és a mozgásmintákat. Az első cél: ne maradjon extenziós korlátozottság.","sheet":{"kind":"condition","items":[{"h":"Kórkép és műtét","t":"A szalagot saját ínból (pl. hamstringín vagy csont–patellaín–csont graft) pótolják. A graft a műtét után átépül, és csak idővel nyeri el szilárdságát."},{"h":"Posztoperatív feladatok","t":"Korán gyakori a duzzanat, a fájdalom, az extenziós korlátozottság és a quadriceps gyenge aktivációja. Figyelj a graftvételi hely fájdalmára és gyengeségére is."},{"h":"Vizsgálati szempontok","t":"Duzzanat, a térdextenzió és -flexió oldalkülönbsége, a quadriceps akaratlagos kontrakciója (extension lag), járásminta, izomerő, funkcionális tesztek (pl. hop tesztek)."},{"h":"Rehabilitáció fázisonként","t":"0–2. hét: teljes extenzió, quadriceps. 2–6. hét: normál járás, flexió növelése. 6–12. hét: erő, propriocepció. 3–6. hónap: fokozatos futás, ugrás. 6. hónaptól: visszatérési tesztek."},{"h":"Óvatosság, ellenjavallat","t":"Ne maradjon extenziós korlátozottság. A graftot terhelő gyakorlatok kezdetét a műtéti technika és az orvos utasítása szabja meg. Ha nő a duzzanat, csökkentsd a terhelést; ne csak az idő alapján haladj."},{"h":"Orvoshoz irányítás jelei","t":"Láz, a seb pirossága, melege, gennyes váladékozása, hirtelen fokozódó duzzanat, vádlifájdalom és -duzzanat (mélyvénás trombózis gyanúja), térdkiszaladás."}]},"keypoints":["Az első számú cél a teljes extenzió elérése","Már korán aktiváld akaratlagosan a quadricepset","Ne csak az idő, hanem a duzzanat, a ROM és az izomerő alapján haladj","A sportba való visszatérésről funkcionális tesztek és az orvos döntenek","Az újrasérülés megelőzésére tanítsd az érkezést és az irányváltást"],"case":{"text":"22 éves férfi, 2 héttel ACL-pótlás után. A térd enyhén duzzadt, az extenzió −10°. A quadriceps kontrakciója gyenge, extension lag látható. Azt mondja, minél előbb futni szeretne.","answer":"Ebben a szakaszban a teljes extenzió és a quadriceps-kontroll elérése az elsődleges, futáshoz még korai. A megmaradó extenziós korlátozottság kóros járáshoz és elülső térdfájdalomhoz vezet. Kezeld a duzzanatot, és csak a kritériumok teljesülése után haladj tovább."},"questions":[{"level":"Alap","q":"Mi az ACL-pótlás utáni rehabilitáció elsődleges célja?","options":["Korai ugrásgyakorlás","Elsőként a mély flexió elérése","A teljes extenzió visszanyerése","Futás közvetlenül a műtét után"],"answer":2,"exp":"A megmaradó extenziós korlátozottság kóros járáshoz és elülső térdfájdalomhoz vezet, ezért a teljes extenzió visszanyerése az elsődleges."},{"level":"Alap","q":"Melyik fázisban végezzük a sportba való visszatérési teszteket?","options":["2. fázis (2–6. hét)","3. fázis (6–12. hét)","4. fázis (3–6. hónap)","5. fázis (6. hónaptól)"],"answer":3,"exp":"A visszatérési teszteket az utolsó, 5. fázisban (6. hónaptól) végezzük, az erő- és funkcionális tesztek eredményei alapján."},{"level":"Középhaladó","q":"Mit jelent a korai posztoperatív szakaszban vizsgált extension lag?","options":["A térd elülső instabilitása","Az aktív extenzió elmarad a passzívtól","A passzív flexió korlátozottsága","A térdkalács laterális helyzete"],"answer":1,"exp":"Passzívan a térd teljesen nyújtható, aktívan viszont nem: ez a quadriceps csökkent aktivációját jelzi."},{"level":"Középhaladó","q":"Mi alapján helyes továbblépni a rehabilitáció következő szakaszába?","options":["A duzzanat, a ROM és az erő kritériumai alapján is","Csak a műtét óta eltelt hetek alapján","A terv szerint, fokozódó fájdalom ellenére is","Elsősorban a beteg kívánsága szerint"],"answer":0,"exp":"Az idő csak tájékoztató. Akkor lépünk tovább, ha a duzzanat, a ROM, az izomerő és a mozgásminőség kritériumai teljesülnek."},{"level":"Klinikai","q":"1 héttel a pótlás után hirtelen vádlifájdalom, duzzanat és melegség jelentkezik. Mi a helyes teendő?","options":["Masszázzsal oszlatni a duzzanatot","Növelni a terhelést","Azonnal jelezni az orvosnak","Hőterápia"],"answer":2,"exp":"Mélyvénás trombózisra utaló jel. A masszázs kerülendő, azonnal jelezni kell az orvosnak."},{"level":"Klinikai","q":"4 hónappal a műtét után nagy az erő-oldalkülönbség, és érkezéskor a térd befelé esik. Mi most a helyes teendő?","options":["Azonnali visszatérés a mérkőzésekre","Folytatni az erősítést és az érkezés javítását","A rehabilitáció befejezése","Visszatérés csak ortézissel"],"answer":1,"exp":"Az erő-oldalkülönbség és a térd befelé esése az újrasérülés kockázati tényezői. Folytasd az erősítést és a mozgásjavítást; a visszatérés csak a kritériumok után jöhet szóba."}],"seccion":"Sérülések és rehabilitáció","grupo":"Sport, inak és izmok","icono":"🏃","mapa":"img/mapas/t30.jpg","fichas":[],"secuencias":[]},"31":{"id":31,"title":"Artrózis","lead":"Az artrózis az ízületi porc degenerációjával járó betegség, amelyben a fájdalom és a funkcióromlás fokozatosan halad. Főleg a térdet és a csípőt érinti; a konzervatív kezelés alapja a mozgásterápia és a betegoktatás.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Lényege az ízületi porc degenerációja és kopása, osteophytaképződéssel, subchondralis sclerosissal és synovitisszel. A térdartrózis főleg mediális, a csípőartrózis gyakran dysplasia talaján alakul ki."},{"h":"Fő tünetek","t":"Indulási fájdalom, fájdalom felálláskor és lépcsőzéskor, merevség, ízületi folyadékgyülem, mozgáskorlátozottság. Előrehaladva feltűnő a deformitás (pl. O-láb) és a járászavar."},{"h":"Vizsgálati szempontok","t":"A fájdalom helye és kiváltója, ROM (pl. a térdextenzió, a csípő belső rotációjának korlátozottsága), izomerő, járás (laterális thrust, Trendelenburg-jel), ADL."},{"h":"A kezelés menete","t":"Betegoktatás, mozgásterápia (a quadriceps és a csípőabduktorok erősítése, ROM megtartása), aerob mozgás, testsúlykontroll, bot, talpbetét. Ha a konzervatív kezelés nem elég, műtét jön szóba."},{"h":"Óvatosság, ellenjavallat","t":"Erős gyulladás vagy folyadékgyülem idején csökkentsd a terhelést. A másnapig tartó fájdalmat okozó terhelés túl sok. A botot alapesetben az érintett oldallal ellentétes kézben tartsa."},{"h":"Orvoshoz irányítás jelei","t":"Hirtelen erős duzzanat és melegség (fertőzés vagy pszeudoköszvény gyanúja), láz, fokozódó éjszakai fájdalom, hirtelen járásképtelenség, esés utáni erős fájdalom."}]},"keypoints":["A térdartrózis többnyire mediális, gyakran O-láb deformitással","A csípőartrózis hátterében gyakran acetabularis dysplasia áll","A konzervatív kezelés alapja a mozgásterápia és a betegoktatás","A botot az érintett oldallal ellentétes kézben tartsa","Vizsgáld felül azt a terhelést, amely után másnapig fájdalom marad"],"case":{"text":"70 éves nő. Évek óta fáj a jobb térde, főleg felálláskor, a mozgás kezdetén és lépcsőn. O-láb deformitás, extenziós korlátozottság és járás közben a térd kifelé billenése (laterális thrust) látható.","answer":"Mediális térdartrózisra gondolunk. Betegoktatás, a quadriceps és a csípő körüli izmok erősítése, a ROM megtartása, testsúlykontroll; szükség esetén bot a bal kézben. Hirtelen melegség vagy duzzanat esetén orvoshoz."},"questions":[{"level":"Alap","q":"Melyik a térdartrózis leggyakoribb típusa?","options":["Laterális (X-láb)","Mediális (O-láb)","Csak patellofemoralis","Tibiofibularis"],"answer":1,"exp":"A térdartrózis leggyakrabban a mediális ízületfelet érinti, és gyakran O-láb (varus) deformitással jár."},{"level":"Alap","q":"Melyik az artrózis tipikus képalkotó lelete?","options":["Az ízületi rés kiszélesedése","A növekedési porc kiszélesedése","Periostealis reakció","Osteophytaképződés"],"answer":3,"exp":"Az artrózis tipikus jelei az ízületi rés szűkülete, az osteophyták és a subchondralis sclerosis."},{"level":"Középhaladó","q":"Jobb oldali térdartrózisos betegnek bothasználatot tanítasz. Melyik kézben tartsa a botot?","options":["A jobb kézben","A bal kézben","Mindkét kézben","Mindegy"],"answer":1,"exp":"A botot alapesetben az érintett oldallal ellentétes kézben tartja, és az érintett lábbal együtt teszi előre; így csökken az érintett oldal terhelése."},{"level":"Középhaladó","q":"Csípőartrózisban, a m. gluteus medius gyengesége esetén melyik jel jellemző?","options":["Drop arm jel","Lasègue-jel","Trendelenburg-jel","Homans-jel"],"answer":2,"exp":"A m. gluteus medius gyengeségekor az érintett oldali féllábas állásban az ellenoldali medence lesüllyed: ez a Trendelenburg-jel."},{"level":"Klinikai","q":"65 éves férfi, térdartrózis. A mozgásterápia után másnapig erős fájdalom és duzzanat maradt. Mi a helyes teendő?","options":["Tovább emelni a terhelést","Minden mozgást leállítani","Csökkenteni és újraadagolni a terhelést","Csak pihenést javasolni"],"answer":2,"exp":"A másnapig tartó fájdalom és duzzanat túlterhelésre utal. Ne hagyd abba, hanem a mennyiséget és az intenzitást módosítva folytasd."},{"level":"Klinikai","q":"Térdartrózisos beteg térde hirtelen erősen bedagadt, meleg, és lázas is. Mi az elsődleges teendő?","options":["Értesíteni az orvost","Fokozni a mozgásterápiát","Hőterápia","Nyújtás tanítása"],"answer":0,"exp":"A hirtelen duzzanat, melegség és láz fertőzésre vagy pszeudoköszvényre utalhat. Kerüld a hőkezelést és a mozgást, értesítsd az orvost."}],"seccion":"Sérülések és rehabilitáció","grupo":"Ortopédia és traumatológia","icono":"🦴","mapa":"img/mapas/t31.jpg","fichas":[],"secuencias":[]},"32":{"id":32,"title":"Csípő- és térdprotézis","lead":"Az ízületi protézis a sérült ízfelszíneket mesterséges anyaggal pótolja a fájdalom csökkentése és a funkció javítása érdekében. A gyógyulás kulcsa a műtéti feltáráshoz igazított mozgástanítás és a korai mobilizálás.","sheet":{"kind":"condition","items":[{"h":"Kórkép és műtét","t":"Artrózis vagy más ok miatt sérült ízfelszínek pótlása protézissel a fájdalom csökkentésére és a funkció javítására. Csípőprotézisnél (THA) a ficamveszélyes helyzet a feltárás módjától függ."},{"h":"Posztoperatív feladatok","t":"Fájdalom, duzzanat, mozgáskorlátozottság, izomgyengeség, romló járás. THA után a ficam megelőzése, térdprotézis (TKA) után a flexiós és extenziós ROM elérése a fő feladat."},{"h":"Vizsgálati szempontok","t":"Seb és duzzanat, ROM, izomerő (quadriceps, m. gluteus medius), lábhossz-különbség érzése, járásminta, egyensúly, ADL. A terhelési korlátot és a tiltott helyzeteket egyeztesd az orvossal."},{"h":"A kezelés menete","t":"Korán bokagyakorlatok, izometriás gyakorlatok, mobilizálás és járásgyakorlás. ROM- és erősítő gyakorlatok, a járási segédeszköz fokozatos váltása, ADL- és otthoni életvitel-tanítás."},{"h":"Óvatosság, ellenjavallat","t":"Hátsó feltárású THA után a flexió–addukció–belső rotáció, elülső feltárás után az extenzió–addukció–külső rotáció kombinációja kerülendő. TKA után figyelj a n. peroneus bénulásának jeleire."},{"h":"Orvoshoz irányítás jelei","t":"Ficamra utaló hirtelen fájdalom, a láb rövidülése és rotációja, vádliduzzanat és -fájdalom, hirtelen nehézlégzés vagy mellkasi fájdalom, a seb pirossága, gennyezése, láz."}]},"keypoints":["A THA ficamveszélyes helyzete a feltárás módjától függ","Hátsó feltárásnál kerüld a flexió–addukció–belső rotáció kombinációt","A boka dorsal- és plantarflexiója segíti a trombózis megelőzését","TKA után fontos a flexiós és extenziós ROM korai elérése","A terhelést és a tiltott helyzeteket mindig egyeztesd az orvossal"],"case":{"text":"75 éves nő, csípőartrózis miatt hátsó feltárásból THA, 3. posztoperatív nap. Járókerettel gyakorol, és a földről akar felvenni valamit: a törzsét elfordítva mélyen lehajolna.","answer":"A mély flexió–addukció–belső rotáció kombinációja hátsó feltárású THA után ficamveszélyes, azonnal állítsd meg. Tanítsd a biztonságos mozdulatokat segédeszközzel (pl. tárgyfelvevő fogóval). Hirtelen fájdalom, a láb rövidülése vagy rotációja esetén orvoshoz."},"questions":[{"level":"Alap","q":"Hátsó feltárású THA után melyik helyzet ficamveszélyes?","options":["Extenzió, addukció, külső rotáció","Flexió, addukció, belső rotáció","Flexió, abdukció, külső rotáció","Extenzió, abdukció, belső rotáció"],"answer":1,"exp":"Hátsó feltárású THA után a csípő flexió–addukció–belső rotáció kombinációjában nagyobb a ficam veszélye."},{"level":"Alap","q":"Mi a térdprotézis (TKA) fő célja?","options":["A csontnövekedés serkentése","A szalag pótlása","Az ideg helyreállítása","Fájdalomcsökkentés és funkciójavítás"],"answer":3,"exp":"A TKA a sérült ízfelszíneket protézissel pótolja; célja a fájdalom csökkentése, a járás és más funkciók javítása."},{"level":"Középhaladó","q":"Melyik gyakorlatot tanítod korán a mélyvénás trombózis megelőzésére?","options":["Nyaki rotáció","Az ujjak hajlítása-nyújtása","A boka dorsal- és plantarflexiója","Mély guggolás"],"answer":2,"exp":"A boka dorsal- és plantarflexiója a vádli izompumpáján keresztül segíti a vénás visszaáramlást és a trombózis megelőzését."},{"level":"Középhaladó","q":"Melyik idegbénulásra kell figyelni TKA után?","options":["N. peroneus bénulása","N. medianus bénulása","N. facialis bénulása","N. radialis bénulása"],"answer":0,"exp":"TKA után a fibulafej körüli nyomás miatt n. peroneus-bénulás alakulhat ki; figyelj a lógó lábfejre és a zsibbadásra."},{"level":"Klinikai","q":"Hátsó feltárású THA utáni 5. nap: a beteg alacsony széken ül, és keresztbe akarja tenni a lábát. Mi a helyes teendő?","options":["Csak megfigyelni","Magasabb szék, a lábkeresztezés kerülése","A lábkeresztezés gyakorlása","A mély hajlás gyakorlása"],"answer":1,"exp":"Alacsony széken a mély flexió és a lábkeresztezés (addukció, belső rotáció) ficamveszélyes. Magas ülőfelületet használjon, és ne tegye keresztbe a lábát."},{"level":"Klinikai","q":"TKA utáni 2. nap: járásgyakorlás közben hirtelen nehézlégzés és mellkasi fájdalom jelentkezik. Mi az elsődleges teendő?","options":["A járásgyakorlás folytatása","Légzőgyakorlatok tanítása","Azonnali leállítás, jelzés az orvosnak","Pihentetés és megfigyelés"],"answer":2,"exp":"Tüdőembóliára utaló jel. A mozgást azonnal le kell állítani, és jelezni kell az orvosnak."}],"seccion":"Sérülések és rehabilitáció","grupo":"Ortopédia és traumatológia","icono":"🦴","mapa":"img/mapas/t32.jpg","fichas":[],"secuencias":[]},"33":{"id":33,"title":"Gyakori törések","lead":"Időseknél az osteoporosis talaján gyakoriak az esés okozta törések. A csontgyógyulás szakaszát és az orvos által engedélyezett keretet követve előzd meg az inaktivitást, és állítsd vissza a funkciót.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Időseknél osteoporosis talaján, esés után gyakori a proximalis femur, a distalis radius, a proximalis humerus és a csigolyatest törése. Fiataloknál a nagy energiájú trauma a jellemző."},{"h":"Fő tünetek","t":"Fájdalom, duzzanat, deformitás, bevérzés, funkciókiesés. Proximalis femurtörésnél a beteg nem tud felállni, a láb rövidült és kifelé rotált; kompressziós törésnél mozgásra hátfájás."},{"h":"Vizsgálati szempontok","t":"Egyeztesd az orvossal a törés típusát, a rögzítést, a terhelés és a ROM keretét. Fájdalom, duzzanat, szomszédos ízületek ROM-ja, erő, ideg- és keringési állapot, a sérülés előtti ADL és kogníció."},{"h":"A kezelés menete","t":"Rögzítés alatt mozgasd a szabad ízületeket a duzzanat és a kontraktúra ellen. A csontgyógyulás és az engedély szerint ROM-, terhelési és erősítő gyakorlatok. Időseknél korai mobilizálás, esésmegelőzés."},{"h":"Óvatosság, ellenjavallat","t":"Ne lépd túl az engedélyezett terhelést és ROM-ot. Tartós ágynyugalomnál figyelj az inaktivitásra, a tüdőgyulladásra, a decubitusra és a deliriumra. Distalis radiustörés után figyelj az ujjak merevségére."},{"h":"Orvoshoz irányítás jelei","t":"Erős fájdalom a rögzítés alatt, zsibbadás, az ujjak elszíneződése (keringési zavar vagy compartment-szindróma gyanúja), hirtelen fokozódó fájdalom vagy deformitás, vádliduzzanat, láz."}]},"keypoints":["Időseknél gyakori az osteoporosis talaján, esés után kialakuló törés","A terhelés és a ROM engedélyezett keretét mindig egyeztesd az orvossal","Rögzítés alatt is aktívan mozgasd a nem rögzített ízületeket","Proximalis femurtörés után korai mobilizálással előzd meg az inaktivitást","Újabb törés ellen: esésmegelőzés és az osteoporosis kezelése"],"case":{"text":"82 éves nő otthon elesett, fáj a jobb csípője, nem tud felállni. A jobb alsó végtag rövidült és kifelé rotált. Pertrochanter femurtörés miatt osteosynthesist végeztek, a műtét utáni napon rehabilitációt rendeltek el.","answer":"Egyeztesd az orvossal az engedélyezett terhelést, kezdd a korai mobilizálást és a járásgyakorlást, előzd meg az inaktivitást, a tüdőgyulladást és a deliriumot. Cél a sérülés előtti ADL; hazabocsátás előtt tanítsd az esésmegelőzést és az osteoporosis kezelését."},"questions":[{"level":"Alap","q":"Melyik törés gyakori, ha idős ember kinyújtott kézre esik?","options":["Os scaphoideum törése","Distalis radiustörés","Olecranontörés","Metacarpustörés"],"answer":1,"exp":"Időseknél kinyújtott kézre esés után a distalis radiustörés a jellemző. Ha a distalis fragmentum dorsalisan mozdul el, Colles-törésről beszélünk."},{"level":"Alap","q":"Milyen helyzetben áll az alsó végtag proximalis femurtörésnél?","options":["Hosszabb és befelé rotált","Nincs eltérés","Rövidült és kifelé rotált","Hosszabb és abdukált"],"answer":2,"exp":"Proximalis femurtörésnél a láb jellemzően rövidült és kifelé rotált, az állás és a járás nehezített."},{"level":"Középhaladó","q":"Melyik a helyes gyógytorna a törés rögzítési szakaszában?","options":["Erős passzív ROM a rögzített részen","Teljes terhelés engedély előtt","Erős masszázs a törés helyén","A nem rögzített ízületek mozgatása"],"answer":3,"exp":"A rögzítés alatt a törést védjük, és a nem rögzített ízületek mozgatásával előzzük meg a duzzanatot, a kontraktúrát és az izomgyengülést."},{"level":"Középhaladó","q":"Mi a korai mobilizálás fő célja időseknél proximalis femurtörés műtéte után?","options":["A törés típusának megállapítása","Az inaktivitási szindróma megelőzése","A műtét helyettesítése","A csontgyógyulás szükségtelenné tétele"],"answer":1,"exp":"Időseknél tartós fekvés mellett gyorsan kialakul az izomgyengülés, a tüdőgyulladás, a decubitus és a delirium, ezért korán mobilizálunk."},{"level":"Klinikai","q":"70 éves nő, distalis radiustörés miatt gipszben. Az ujjai erősen duzzadtak, zsibbadnak és elszíneződtek. Mi a helyes teendő?","options":["Az ujjtorna fokozása","Hőterápia","Azonnal jelezni az orvosnak","Megvárni a következő kezelést"],"answer":2,"exp":"A rögzítés alatti erős duzzanat, zsibbadás és elszíneződés keringési zavarra vagy compartment-szindrómára utal. Azonnal jelezd az orvosnak."},{"level":"Klinikai","q":"85 éves nő, ágyéki kompressziós csigolyatörés, hátfájás; az orvos engedélyezte a mobilizálást. Mi a helyes teendő?","options":["Mobilizálás az engedélyezett keretben","Ágyban maradás, megfigyelés","Erős törzsflexiós gyakorlatok","Nehéz tárgyak emelésének gyakorlása"],"answer":0,"exp":"Az engedélyezett keretben mobilizálunk az inaktivitás ellen. Kompressziós törésnél az erős törzsflexió és a nehéz tárgy emelése megterhelő, kerülendő."}],"seccion":"Sérülések és rehabilitáció","grupo":"Ortopédia és traumatológia","icono":"🦴","mapa":"img/mapas/t33.jpg","fichas":[],"secuencias":[]},"34":{"id":34,"title":"Derékfájás és porckorongsérv","lead":"A derékfájás többsége nem specifikus, oka nem azonosítható, de fontos elkülöníteni a gyöki tüneteket és a súlyos betegségeket. A vörös zászlók kizárása után az aktivitás megtartását támogatjuk.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"A derékfájás többsége nem specifikus. Porckorongsérvnél a nucleus pulposus az anulus fibrosuson áttörve előboltosul, és nyomja az ideggyököt. Leggyakoribb az L4/5 és az L5/S1 szegmentumban."},{"h":"Fő tünetek","t":"Derékfájás és egyoldali, lábba sugárzó fájdalom (isiász), zsibbadás, előrehajlásra és ülésre fokozódó panasz. Az érintett gyöknek megfelelő érzés-, erő- és reflexcsökkenés."},{"h":"Vizsgálati szempontok","t":"SLR-teszt (felső lumbalis gyököknél femoralis ideg nyújtási teszt), dermatomák, izomerő (L5: nagylábujj dorsalflexió, S1: boka plantarflexió), reflexek (S1: Achilles-ín reflex)."},{"h":"A kezelés menete","t":"Betegoktatással csökkentsd a félelmet, tartsd meg az aktivitást a lehetséges keretben. Keress tünetcsökkentő testhelyzetet és gyakorlatot; törzs- és alsóvégtag-gyakorlatok, fokozatosan növelt aktivitás."},{"h":"Óvatosság, ellenjavallat","t":"Tartós ágynyugalmat ne javasolj. Állítsd le azt a gyakorlatot, amelytől a tünetek a lábujjak felé terjednek. A félelemkerülés és más pszichoszociális tényezők szerepet játszanak a krónikussá válásban."},{"h":"Orvoshoz irányítás jelei","t":"Hólyag- és végbélzavar, nyeregérzéskiesés (cauda equina szindróma), progrediáló gyengeség, láz, megmagyarázatlan fogyás, daganat az anamnézisben, trauma utáni erős fájdalom."}]},"keypoints":["A derékfájás többsége nem specifikus","L4/5 sérvnél jellemzően az L5 gyök érintett","Az SLR-teszt az alsó lumbalis gyöki tüneteket vizsgálja","Tartós pihenés helyett tartsd meg az aktivitást a lehetséges keretben","Hólyag- és végbélzavar, nyeregérzéskiesés: sürgősen orvoshoz"],"case":{"text":"35 éves férfi, irodai munkát végez. Nehéz tárgy emelése óta derékfájás és a bal lábszár külső oldalától a lábhátig terjedő zsibbadás. A bal SLR kiváltja a lábba sugárzó fájdalmat, a bal nagylábujj dorsalflexiója gyenge. Vizelési zavar nincs.","answer":"L4/5 porckorongsérv okozta L5 gyöki laesióra gyanakszunk. Oktatás, aktivitás megtartása a lehetséges keretben, a tüneteket nem rontó gyakorlatok; az izomgyengeség alakulását rendszeresen vizsgáld újra. Progrediáló bénulás vagy hólyag- és végbélzavar esetén azonnal orvoshoz."},"questions":[{"level":"Alap","q":"Melyik szegmentumban leggyakoribb a lumbalis porckorongsérv?","options":["L1/2","L2/3","L3/4","L4/5"],"answer":3,"exp":"A lumbalis porckorongsérv leggyakrabban az L4/5, ezt követően az L5/S1 szegmentumban fordul elő."},{"level":"Alap","q":"Porckorongsérvben főként melyik szövet boltosul elő?","options":["Nucleus pulposus","Lig. flavum","Csigolyaív","Processus spinosus"],"answer":0,"exp":"A porckorong központi része, a nucleus pulposus az anulus fibrosus repedésén át előboltosul, és nyomja az ideggyököt."},{"level":"Középhaladó","q":"L5 gyöki laesióban melyik mozgás ereje csökken jellemzően?","options":["A boka plantarflexiója","A nagylábujj dorsalflexiója","Térdextenzió","Csípőflexió"],"answer":1,"exp":"Az L5 gyök a m. extensor hallucis longust idegzi be, laesiójában a nagylábujj dorsalflexiója gyengül. A boka plantarflexiója S1."},{"level":"Középhaladó","q":"S1 gyöki laesióban melyik reflex csökken jellemzően?","options":["Patellareflex","Bicepsreflex","Achilles-ín reflex","Brachioradialis reflex"],"answer":2,"exp":"Az Achilles-ín reflexben főként az S1 vesz részt. A patellareflex elsősorban az L4 vizsgálatára szolgál."},{"level":"Klinikai","q":"40 éves nő, akut derékfájás, vörös zászló nincs. Mi a helyes tanács?","options":["2 hét szigorú ágynyugalom","Táppénz a fájdalom megszűnéséig","Minden mozgás tiltása","Aktivitás megtartása a lehetséges keretben"],"answer":3,"exp":"Vörös zászlók nélküli akut derékfájásnál a tartós pihenés helyett a napi aktivitás megtartása javasolt a lehetséges keretben."},{"level":"Klinikai","q":"Derékfájós beteg, mindkét lába zsibbad; arról panaszkodik, hogy nehezen indul a vizelete, és a végbélnyílás körül tompa az érzése. Mi a teendő?","options":["A mozgásterápia folytatása","Trakciós kezelés","Azonnal értesíteni az orvost","Megvárni a következő kezelést"],"answer":2,"exp":"A hólyag- és végbélzavar és a nyeregérzéskiesés cauda equina szindrómára utaló sürgős jel. Azonnal értesítsd az orvost."}],"seccion":"Sérülések és rehabilitáció","grupo":"Gerinc","icono":"🧍","mapa":"img/mapas/t34.jpg","fichas":[],"secuencias":[]},"35":{"id":35,"title":"Nyakfájás","lead":"A nyakfájás többsége nem specifikus, de fontos elkülöníteni a radiculopathiát és a myelopathiát. A veszélyjelek ellenőrzése után mozgásterápiát alkalmazunk, és a testtartást korrigáljuk.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Leggyakoribb a nem specifikus nyakfájás. Ha porckorong vagy osteophyta nyomja az ideggyököt, radiculopathia, ha a gerincvelőt, myelopathia alakul ki. Trauma után ostorcsapás-sérülés (whiplash) is előfordul."},{"h":"Fő tünetek","t":"Nyakfájás, mozgáskorlátozottság, lapockatáji fájdalom. Radiculopathiában egyoldali karfájdalom, zsibbadás. Myelopathiában mindkét kéz zsibbadása, romló finommozgás (gombolás, evőeszköz), járászavar."},{"h":"Vizsgálati szempontok","t":"Nyaki ROM, Spurling-teszt, dermatomák, izomerő, reflexek (C6: brachioradialis, C7: triceps), Hoffmann-reflex, járás, testtartás."},{"h":"A kezelés menete","t":"Oktatás és az aktivitás megtartása, nyak- és vállöv-gyakorlatok (pl. a mély nyaki flexorok gyakorlatai), a testtartás és a munkakörnyezet alakítása. Manuálterápia a vizsgálat alapján, óvatosan."},{"h":"Óvatosság, ellenjavallat","t":"Myelopathia gyanújakor kerüld az erős nyaki manuális technikákat. Azonnal állítsd le azt a technikát vagy gyakorlatot, amely szédülést, kettőslátást vagy beszédzavart vált ki."},{"h":"Orvoshoz irányítás jelei","t":"Mindkét kéz zsibbadása, romló finommozgás és járászavar, progrediáló bénulás, trauma utáni fájdalom, láz, szédülés, beszéd- vagy nyelészavar, megmagyarázatlan fogyás."}]},"keypoints":["A nyakfájás többsége nem specifikus","A Spurling-teszt a radiculopathia vizsgálatára szolgál","Mindkét kéz romló ügyessége és járászavar: myelopathia gyanúja","Végeztess mély nyaki flexor- és vállöv-gyakorlatokat","Myelopathia gyanújakor kerüld az erős nyaki manuális technikákat"],"case":{"text":"45 éves nő, irodai dolgozó. Egy hónapja nyakfájás és a jobb hüvelykujj zsibbadása. A nyak jobbra történő extenziójakor és oldalra hajlításakor a jobb karba sugárzó fájdalom jelentkezik. A jobb brachioradialis reflex csökkent.","answer":"Jobb oldali C6 radiculopathiára gondolunk. A tüneteket nem rontó keretben oktatás, mozgásterápia, a testtartás és a munkakörnyezet alakítása. Progrediáló gyengeség vagy myelopathia jelei (mindkét kéz zsibbadása, járászavar) esetén orvoshoz."},"questions":[{"level":"Alap","q":"Melyik tünet utal cervicalis spondylotikus myelopathiára?","options":["Csak egyoldali lapockatáji fájdalom","Mindkét kéz romló ügyessége","Nyakizom-merevség","Csak fejfájás"],"answer":1,"exp":"Gerincvelő-kompresszióban mindkét kéz zsibbad, romlik a finommozgás (evőeszköz, gombolás), és járászavar jelentkezik."},{"level":"Alap","q":"Melyik a mély nyaki flexorok tipikus gyakorlata?","options":["Erős nyaki extenzió","Gyors nyaki rotáció","Állbehúzás (craniocervicalis flexió)","Vállhúzogatás"],"answer":2,"exp":"Az áll enyhe behúzásával végzett craniocervicalis flexió a mély nyaki flexorok (pl. m. longus colli) aktivitását fokozó tipikus gyakorlat."},{"level":"Középhaladó","q":"Mi a pozitív Spurling-teszt lelete?","options":["Extenzió + lateroflexió: karba sugárzó fájdalom","Nyaki flexió: hátba nyilalló fájdalom","Vállabdukcióra enyhülő tünetek","Csuklóflexióra jelentkező zsibbadás"],"answer":0,"exp":"A nyakat az érintett oldal felé extendáljuk és oldalra hajlítjuk, majd axiális nyomást adunk; karba sugárzó fájdalom vagy zsibbadás radiculopathiára utal."},{"level":"Középhaladó","q":"C7 gyöki laesióban melyik reflex csökken jellemzően?","options":["Bicepsreflex","Brachioradialis reflex","Tricepsreflex","Patellareflex"],"answer":2,"exp":"A tricepsreflex főként a C7, a bicepsreflex a C5, a brachioradialis reflex a C6 vizsgálatára szolgál."},{"level":"Klinikai","q":"60 éves férfi: mostanában nehezen gombol, a járása bizonytalan, a Hoffmann-reflex pozitív. Mire gyanakszol leginkább?","options":["Nem specifikus nyakfájás","Thoracic outlet szindróma","Carpalis alagút szindróma","Cervicalis spondylotikus myelopathia"],"answer":3,"exp":"A romló finommozgás, a járászavar és a kóros reflex myelopathiára utal. Kerüld az erős nyaki technikákat, irányítsd orvosi vizsgálatra."},{"level":"Klinikai","q":"Nyakfájós betegnél nyaki rotációs gyakorlat közben szédülés és kettőslátás jelentkezik. Mi a helyes teendő?","options":["Folytatni, hogy hozzászokjon","Azonnal leállítani, orvoshoz irányítani","A ROM további növelése","Hőterápiára váltani"],"answer":1,"exp":"A szédülés és a kettőslátás vascularis vagy neurológiai problémára utalhat. Azonnal állítsd le, és irányítsd orvosi vizsgálatra."}],"seccion":"Sérülések és rehabilitáció","grupo":"Gerinc","icono":"🧍","mapa":"img/mapas/t35.jpg","fichas":[],"secuencias":[]},"36":{"id":36,"title":"Scoliosis","lead":"A scoliosis a gerinc oldalirányú görbülete csigolyarotációval: háromdimenziós deformitás. Növekedés alatt hajlamos a progresszióra, ezért fontos a korai felismerés és a rendszeres kontroll.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"A gerinc frontalis síkban oldalra görbül: csigolyarotációval járó háromdimenziós deformitás. Többnyire ismeretlen eredetű (idiopathiás), serdülő lányoknál gyakoribb. El kell különíteni a funkcionálistól."},{"h":"Fő tünetek","t":"Többnyire kevéssé fáj; a váll, a lapocka, a derékvonal aszimmetriája vagy előrehajláskor a bordapúp, ágyéki púp hívja fel rá a figyelmet. Súlyos esetben a légzésfunkciót is rontja."},{"h":"Vizsgálati szempontok","t":"Állásban a váll, a medence és a derékvonal szimmetriája, előrehajlási teszt, lábhossz-különbség (funkcionálistól való elkülönítés), hajlékonyság, légzés. A görbületet röntgenen, Cobb-szöggel az orvos méri."},{"h":"A kezelés menete","t":"A kontrollról, az ortézisről vagy a műtétről a növekedési szakasz és a Cobb-szög alapján az orvos dönt. A gyógytornász törzs- és légzőgyakorlatokat végeztet, és támogatja az ortézis viselését."},{"h":"Óvatosság, ellenjavallat","t":"Növekedés alatt hajlamos a progresszióra, ezért fontos a rendszeres kontroll. Ne mondd, hogy pusztán tornával korrigálható. Az ortézis viselési idejét az orvos határozza meg."},{"h":"Orvoshoz irányítás jelei","t":"Erős vagy éjszakai fájdalom, neurológiai tünetek (zsibbadás, gyengeség), gyors progresszió, atipikus görbület (pl. balra domború háti görbület), láz."}]},"keypoints":["A scoliosis csigolyarotációval járó háromdimenziós deformitás","A legjellemzőbb a serdülő lányoknál gyakori idiopathiás scoliosis","Előrehajlási teszttel ellenőrizd a bordapúpot","Növekedés alatt hajlamos a progresszióra, fontos a rendszeres kontroll","Fájdalommal vagy neurológiai tünetekkel járó scoliosisnál orvoshoz"],"case":{"text":"13 éves lány, iskolai szűrésen scoliosist állapítottak meg. Állásban a jobb válla magasabb, előrehajláskor jobb oldali bordapúp látható. Fájdalom és neurológiai tünet nincs. Az ortopéd orvos ortézist rendelt.","answer":"Serdülőkori idiopathiás scoliosisra gondolunk. A gyógytornász támogatja az ortézis folyamatos viselését, törzs- és légzőgyakorlatokat végeztet. Ne mondd, hogy pusztán tornával meggyógyul. Fájdalom, neurológiai tünet vagy gyors progresszió esetén orvoshoz."},"questions":[{"level":"Alap","q":"Scoliosis-szűrésnél mit figyelsz az előrehajlási tesztben?","options":["A térd hiperextenzióját","Bordapúpot","A lábboltozat lesüllyedését","Fokozott nyaki lordosist"],"answer":1,"exp":"Előrehajláskor hátulról nézzük a hátat, és a csigolyarotáció okozta bordapúpot vagy ágyéki púpot keressük."},{"level":"Alap","q":"Melyik mutató jelzi a scoliosis görbületének mértékét?","options":["Q-szög","Collodiaphysealis szög","Cobb-szög","Femorotibialis szög"],"answer":2,"exp":"A görbület mértékét röntgenen a Cobb-szöggel mérjük, a görbület felső és alsó végcsigolyája alapján."},{"level":"Középhaladó","q":"Mi igaz az idiopathiás scoliosisra?","options":["Idős férfiaknál gyakori","Serdülő lányoknál gyakori","Mindig erős fájdalommal jár","Csak frontalis síkú deformitás"],"answer":1,"exp":"Az idiopathiás scoliosis serdülő lányoknál gyakoribb, többnyire kevéssé fáj, és csigolyarotációval járó háromdimenziós deformitás."},{"level":"Középhaladó","q":"Mi okozhat funkcionális scoliosist?","options":["Veleszületett csigolya-rendellenesség","Neuromuszkuláris betegség","Csigolyarotációs deformitás","Lábhossz-különbség"],"answer":3,"exp":"A lábhossz-különbség vagy fájdalom miatti kíméleti tartás okozta funkcionális scoliosis az ok megszüntetésével javul; el kell különíteni a strukturálistól."},{"level":"Klinikai","q":"14 éves lány ortézissel; mivel szorítja, saját döntésből kevesebb ideig hordja. Mi a gyógytornász teendője?","options":["Ortézis elhagyása, csak torna","Támogatni a viselést, egyeztetni az orvossal","A viselési idő további csökkentése","Megnyugtatni, hogy nincs gond"],"answer":1,"exp":"A viselési időben az orvos utasítása a mérvadó. Hallgasd meg a gondjait, támogasd a viselést, az illeszkedésről egyeztess az orvossal vagy az ortézistechnikussal."},{"level":"Klinikai","q":"12 éves fiú scoliosissal, éjszaka erős hátfájásra ébred. Mi a helyes teendő?","options":["Nyújtás tanítása","Megfigyelés","A terhelés növelése","Orvosi vizsgálatra irányítás"],"answer":3,"exp":"Erős vagy éjszakai fájdalommal járó scoliosis mögött más ok, pl. daganat is állhat, ezért orvosi vizsgálatra kell irányítani."}],"seccion":"Sérülések és rehabilitáció","grupo":"Gerinc","icono":"🧍","mapa":"img/mapas/t36.jpg","fichas":[],"secuencias":[]},"37":{"id":37,"title":"Stroke","lead":"Az agyi erek elzáródása vagy megrepedése miatt hirtelen kialakuló neurológiai tünetek. A korai mobilizáció és a feladatorientált, ismételt gyakorlás a funkcionális javulás alapja.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Ischaemiás stroke (atherothromboticus, cardioemboliás, lacunaris), agyvérzés és subarachnoidealis vérzés. A tünetek a lézió helyétől és méretétől függnek."},{"h":"Fő tünetek","t":"Hemiparesis, érzészavar, spaszticitás, afázia, féloldali neglect, dysarthria, dysphagia, valamint figyelemzavar és más magasabb kérgi funkciózavarok."},{"h":"Vizsgálati szempontok","t":"Parézis: Brunnstrom-stádium, SIAS, FMA; spaszticitás: MAS; egyensúly: BBS; ADL: FIM."},{"h":"Rehabilitáció fázisonként","t":"Akut fázis: korai mobilizáció kockázatkezelés mellett. Szubakut fázis: feladatorientált gyakorlás és járástanítás. Krónikus fázis: az aktivitás és a részvétel fenntartása."},{"h":"Óvatosság, ellenjavallat","t":"Akut fázisban figyelj a vérnyomás, a tudatállapot és a neurológiai tünetek ingadozására. A paretikus kar húzása vagy a helytelen segítés vállfájdalmat okoz."},{"h":"Orvoshoz irányítás jelei","t":"Azonnal jelezd, ha csökken a tudatszint, hirtelen romlik a parézis vagy a dysarthria, illetve erős fejfájás, hányás vagy hirtelen vérnyomás-változás jelentkezik."}]},"keypoints":["A mobilizáció indítása és leállítása az orvosi utasítás és a leállítási kritériumok szerint","A paretikus vállat ne húzd, pozicionálással védd","Neglectnél: az elhanyagolt oldalra terelő feladatok és környezet-átalakítás","A funkcionális javulás alapja a feladatorientált, ismételt gyakorlás","Az ortézist a járásképességhez és a célokhoz igazítva, fokozatosan mérlegeld"],"case":{"text":"68 éves férfi, jobb oldali a. cerebri media területi ischaemiás stroke után 3 héttel. Bal oldali hemiparesis (alsó végtag: Brunnstrom III. stádium). Kerekesszékkel gyakran nekimegy a bal oldali tárgyaknak, és a tányér bal felén hagyja az ételt.","answer":"Bal oldali neglect gyanúja, magas az elesés és az ütközés kockázata. A bal oldalra irányuló figyelmet fejlesztő feladatok és környezet-átalakítás, felügyelet melletti gyakorlás. Amíg a neglect fennáll, ne engedélyezd az önálló közlekedést."},"questions":[{"level":"Alap","q":"Milyen eloszlású hemiparesis jellemző az a. cerebri media területi ischaemiás strokera?","options":["Alsó végtag túlsúlyú","Felső végtag és arc túlsúlyú","Mindkét alsó végtag paraparesise","Szimmetrikus tetraparesis"],"answer":1,"exp":"Az a. cerebri media a félteke lateralis felszínét látja el, a felső végtag és az arc motoros kérgével együtt, ezért ezek túlsúlyosak. Alsó végtag túlsúly: a. cerebri anterior."},{"level":"Alap","q":"Melyik lézió okoz leggyakrabban bal oldali neglectet?","options":["Bal frontalis lebeny","Kisagy","Jobb parietalis lebeny","Agytörzs"],"answer":2,"exp":"A bal oldali neglect jellemzően a jobb félteke, különösen a jobb parietalis lebeny károsodásakor alakul ki."},{"level":"Középhaladó","q":"Melyik Brunnstrom-stádiumban jelennek meg a szinergiák akaratlagosan, teljes mértékben?","options":["II. stádium","IV. stádium","VI. stádium","III. stádium"],"answer":3,"exp":"III.: a szinergiák akaratlagosan, teljes mértékben megjelennek. II.: asszociált reakciók, kezdődő szinergiák. IV.: részben lehetséges izolált mozgás."},{"level":"Középhaladó","q":"Melyik skálával méred a stroke utáni spaszticitást?","options":["MAS","FIM","BBS","MMSE"],"answer":0,"exp":"A MAS a passzív mozgatással szembeni ellenállás alapján fokozza az izomtónust. A FIM az ADL-t, a BBS az egyensúlyt, az MMSE a kognitív funkciót méri."},{"level":"Klinikai","q":"Stroke után a paretikus vállon subluxatio van, és a beteg transzfer közben vállfájdalmat jelez. Mit teszel?","options":["A paretikus karnál fogva segíted","Megtámasztod a vállat, nem húzod a kart","Teljesen rögzíted, amíg el nem múlik a fájdalom","Naponta erős passzív nyújtást végzel"],"answer":1,"exp":"A subluxált váll húzása fájdalmat és sérülést okoz. Támasztóeszközzel és pozicionálással védd, a mozgástartományt fájdalommentes határon belül tartsd fenn."},{"level":"Klinikai","q":"Akut ischaemiás stroke: mobilizáció közben hirtelen romlik a dysarthria és a parézis. Mit teszel?","options":["Folytatod a járásgyakorlást","Pihenő után folytatod a gyakorlást","Leállsz, és azonnal jelzed az orvosnak","Másnap újraértékeled"],"answer":2,"exp":"A neurológiai tünetek hirtelen romlása a lézió terjedésére vagy kiújulásra utalhat. Állítsd le a gyakorlást, biztosítsd a beteget, és azonnal értesítsd az orvost."}],"seccion":"Sérülések és rehabilitáció","grupo":"Neurológia","icono":"🧠","mapa":"img/mapas/t37.jpg","fichas":[],"secuencias":[]},"38":{"id":38,"title":"Parkinson-kór","lead":"A középagyi substantia nigra dopaminerg neuronjainak degenerációjával járó, motoros tüneteket okozó progresszív neurodegeneratív betegség. Kulcs a külső jelzőingerekre (cue) épülő mozgás és az esésmegelőzés.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"A substantia nigra dopaminerg neuronjai degenerálódnak, a striatumban dopaminhiány alakul ki, és sérül a mozgásszabályozás. A tünetek lassan progrediálnak."},{"h":"Fő tünetek","t":"Nyugalmi tremor, rigor, akinézia/bradykinesia, posturalis instabilitás. Emellett freezing, aprólépéses járás, előrehajló tartás és nem motoros tünetek (pl. obstipáció)."},{"h":"Vizsgálati szempontok","t":"Hoehn–Yahr-stádium, MDS-UPDRS, BBS, TUG, járássebesség, freezing megléte, eleséses anamnézis és a gyógyszerhatás napszaki ingadozása."},{"h":"A kezelés menete","t":"Korai szakaszban általános mozgás és állóképesség megőrzése; a progresszióval vizuális/auditív cue-val segített járásgyakorlás, egyensúlygyakorlás, esésmegelőzés és környezet-átalakítás."},{"h":"Óvatosság, ellenjavallat","t":"Az edzés időpontját a gyógyszerhatás ingadozásához (wearing-off, dyskinesia) igazítsd. Figyelj az orthostaticus hypotoniára is."},{"h":"Orvoshoz irányítás jelei","t":"Jelezd a tünetek hirtelen romlását, a gyógyszerhatás idejének rövidülését, a hallucinációt, az ismétlődő eséseket, a dysphagia romlását, illetve a magas lázat erős rigorral."}]},"keypoints":["Az edzést a gyógyszer hatásos, „on” időszakára időzítsd","Külső jelzőingerek (padlócsíkok, ritmikus hang) csökkentik a freezinget","Nagy amplitúdójú, lassú mozdulatokat gyakoroltass ismételten","Fordulás és kettős feladat közben magas az esés kockázata","Az előrehajló tartás ellen törzsextenziós és -rotációs gyakorlatok"],"case":{"text":"72 éves nő, Parkinson-kór (Hoehn–Yahr III). Szűk ajtókban és fordulásnál lefagy a lába, otthon többször elesett. A tünetek akkor erősebbek, amikor a gyógyszer hatása lecseng.","answer":"A freezing és a posturalis instabilitás miatt magas az esés kockázata. „On” időszakban gyakoroltasd a járást és a fordulást vizuális/auditív cue-kkal, és alakítsátok át a lakókörnyezetet. A gyógyszerelést az orvossal beszéld meg; a beteg önállóan ne módosítsa."},"questions":[{"level":"Alap","q":"Melyik struktúra degenerálódik elsősorban Parkinson-kórban?","options":["Kisagy","Substantia nigra","Gerincvelő elülső szarva","Motoros kéreg"],"answer":1,"exp":"A substantia nigra dopaminerg neuronjai degenerálódnak; a striatum dopaminszintjének csökkenése okozza a motoros tüneteket."},{"level":"Alap","q":"Mi jellemző a Parkinson-kór tremorára?","options":["Intenciós tremor","Mozgásra fokozódik","Nyugalmi tremor","Alvás alatt is fennáll"],"answer":2,"exp":"Nyugalomban jelenik meg, és akaratlagos mozgásra enyhül. Intenciós tremor kisagyi károsodásban látható."},{"level":"Középhaladó","q":"Mi jellemző a Hoehn–Yahr III. stádiumra?","options":["Megjelenik a posturalis instabilitás","Csak egyoldali tünetek","Kerekesszék, ágyhoz kötöttség","Kétoldali tünetek, ép posturalis reflexek"],"answer":0,"exp":"III.: kétoldali tünetek posturalis instabilitással. I.: egyoldali; II.: kétoldali, ép posturalis reflexekkel; V.: kerekesszék vagy ágyhoz kötöttség."},{"level":"Középhaladó","q":"Mivel csökkenthető a freezing?","options":["Csukott szemmel járás","A járássebesség hirtelen növelése","Ismételt járás szűk folyosón","Vizuális cue, pl. padlócsíkok"],"answer":3,"exp":"A külső jelzőingerek (padlócsíkok, metronóm hangja) csökkentik a freezinget és javítják a lépéshosszt."},{"level":"Klinikai","q":"Parkinson-kóros beteg reggel és délben veszi be a gyógyszert; késő délután lelassul, a gyakorlás elakad. Mit teszel?","options":["Délután növeled az edzésmennyiséget","Az edzést az „on” időszakra teszed","A beteg maga módosítja az adagot","Abbahagyod a gyógytornát"],"answer":1,"exp":"Wearing-off gyanúja. Az edzést a hatásos időszakra időzítsd, az ingadozást jelezd az orvosnak. A gyógyszerelést az orvos állítja be."},{"level":"Klinikai","q":"Parkinson-kóros beteg hirtelen abbahagyta a gyógyszert; magas láz, kifejezett rigor és tudatzavar jelentkezik. Mit teszel?","options":["Enyhe mozgással kivársz","Fokozod a nyújtást","Leállsz, azonnal értesíted az orvost","Másnap újraértékeled"],"answer":2,"exp":"A gyógyszer hirtelen elhagyása utáni láz, rigor és tudatzavar malignus szindróma (NMS-szerű állapot) gyanúja, sürgős ellátást igényel. Azonnal értesítsd az orvost."}],"seccion":"Sérülések és rehabilitáció","grupo":"Neurológia","icono":"🧠","mapa":"img/mapas/t38.jpg","fichas":[],"secuencias":[]},"39":{"id":39,"title":"Sclerosis multiplex","lead":"A központi idegrendszer myelinhüvelyét gyulladás károsítja; gyakran relapszusok és remissziók váltakoznak. Kulcs a terhelés adagolása a fáradékonyság és a testhő-emelkedés figyelembevételével.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Autoimmun betegség: az agyban, a gerincvelőben és a látóidegben időben és térben disszeminált demyelinisatiós gócok alakulnak ki. Fiatal felnőtteken, főleg nőkön gyakoribb."},{"h":"Fő tünetek","t":"Látászavar (opticus neuritis), izomgyengeség, érzészavar, spaszticitás, ataxia, fáradékonyság, hólyag- és bélműködési zavar, Lhermitte-jel stb."},{"h":"Vizsgálati szempontok","t":"EDSS, manuális izomtesztelés, MAS, egyensúly, járásképesség és a fáradtság mértéke. Ellenőrizd a tünetek napszaki és hőmérséklet okozta változását is."},{"h":"A kezelés menete","t":"Relapszusban pihentetés és kíméletes ROM-gyakorlatok; remisszióban aerob, erősítő és egyensúlygyakorlatok, a fáradtsághoz igazítva, fokozatosan."},{"h":"Óvatosság, ellenjavallat","t":"A testhő emelkedése átmenetileg rontja a tüneteket (Uhthoff-jelenség): kerüld a meleg környezetet és a túlterhelést, iktass be pihenőket."},{"h":"Orvoshoz irányítás jelei","t":"Új látásromlás, zsibbadás vagy bénulás, illetve 24 óránál tovább tartó hirtelen tünetromlás relapszusra utalhat: jelezd az orvosnak."}]},"keypoints":["Hűvös környezetben edz, kerüld a testhő emelkedését","Erős fáradtság esetén csökkentsd a terhelést, tarts pihenőket","Relapszusban és remisszióban más-más gyakorlatanyagot alkalmazz","Az ADL-oktatásba építsd be az energiatakarékos technikákat","A spaszticitást nyújtással és pozicionálással kezeld"],"case":{"text":"32 éves nő, sclerosis multiplex (remisszió). Meleg tornateremben edzés közben fokozódott az alsó végtagi gyengeség és zsibbadás, de pihenés és hűtés után kb. 30 perc alatt rendeződött.","answer":"A testhő emelkedése okozta átmeneti tünetromlás (Uhthoff-jelenség) valószínű. Hűvös környezetben, pihenőkkel, csökkentett intenzitással folytasd. Ha pihenésre sem javul, és a tünetek fennmaradnak, relapszusra gondolj, és jelezd az orvosnak."},"questions":[{"level":"Alap","q":"Melyik struktúra károsodik elsősorban sclerosis multiplexben?","options":["A perifériás idegek myelinje","A központi idegrendszer myelinje","Neuromuszkuláris junkció","Vázizomrostok"],"answer":1,"exp":"Az agy, a gerincvelő és a látóideg, vagyis a központi idegrendszer myelinhüvelye sérül. Perifériás demyelinisatio pl. Guillain–Barré-szindrómában fordul elő."},{"level":"Alap","q":"Melyik jelenség jelenti a tünetek átmeneti romlását testhő-emelkedésre?","options":["Lhermitte-jel","Romberg-jel","Babinski-reflex","Uhthoff-jelenség"],"answer":3,"exp":"Uhthoff-jelenség: testhő-emelkedésre átmenetileg romlanak a tünetek. Lhermitte-jel: nyakflexióra áramütésszerű fájdalom fut a háton át a végtagokba."},{"level":"Középhaladó","q":"Mi a megfelelő gyógytorna sclerosis multiplex relapszusában?","options":["Nagy intenzitású erősítés","Hosszan tartó aerob edzés","Kíméletes ROM-gyakorlatok","Edzés meleg környezetben"],"answer":2,"exp":"Relapszusban a gyulladás aktív, ezért kerüld a túlterhelést; a kíméletes mozgástartomány-gyakorlatok és a pozicionálás állnak előtérben."},{"level":"Középhaladó","q":"Melyik jel: nyakflexióra áramütésszerű fájdalom fut a háton át a végtagokba?","options":["Lhermitte-jel","Uhthoff-jelenség","Hoffmann-reflex","Trendelenburg-jel"],"answer":0,"exp":"A Lhermitte-jel nyaki gerincvelői léziókban gyakori, a sclerosis multiplex egyik jellegzetes jele."},{"level":"Klinikai","q":"SM-es beteg estére erősen elfárad, a járása bizonytalanná válik. Mit tanácsolsz?","options":["Estére növelje a mozgást","Az aktivitást a jobb napszakokra ossza el","Pihenő nélkül folytassa","Meleg szobában eddzen"],"answer":1,"exp":"A fáradékonyságot energiatakarékos szemlélettel kezeld: az aktivitást a jobb napszakokra oszd el, és tervezetten iktass be pihenőket."},{"level":"Klinikai","q":"Remisszióban lévő SM-es beteg: napok óta tart az egyik szem látásromlása és egy új alsó végtagi zsibbadás. Mit teszel?","options":["Növeled az edzésintenzitást","Hőterápiát adsz hozzá","Relapszus gyanújával jelzed az orvosnak","Egy hónap múlva újraértékeled"],"answer":2,"exp":"A tartósan fennálló új neurológiai tünet relapszusra utalhat. Ne növeld a terhelést, és mielőbb jelezd az orvosnak."}],"seccion":"Sérülések és rehabilitáció","grupo":"Neurológia","icono":"🧠","mapa":"img/mapas/t39.jpg","fichas":[],"secuencias":[]},"40":{"id":40,"title":"Gerincvelő-sérülés","lead":"A gerincvelő sérülése a sérülési szint alatt károsítja a motoros, szenzoros és vegetatív funkciókat. A középpontban a megmaradt funkciókhoz igazított célkitűzés és a szövődmények megelőzése áll.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Esés, közlekedési baleset vagy betegség okozza; komplett és inkomplett sérülést különítünk el. Nyaki sérülés tetraplegiát, háti-ágyéki sérülés paraplegiát okoz."},{"h":"Fő tünetek","t":"A sérülési szint alatt motoros bénulás és érzészavar, hólyag- és bélműködési zavar, vegetatív zavar (orthostaticus hypotonia, hőszabályozási zavar), spaszticitás."},{"h":"Vizsgálati szempontok","t":"Az ASIA-kritériumok szerint határozd meg a neurológiai szintet és az AIS-t; szegmentenként vizsgáld a kulcsizmok erejét és az érzést. Az ADL-t FIM-mel vagy SCIM-mel mérd fel."},{"h":"A kezelés menete","t":"Akut fázisban légzéskezelés, pozicionálás, a ROM megőrzése; szubakut fázisban a megmaradt izmok erősítése és ADL-gyakorlás: felülés, transzfer, kerekesszék-hajtás."},{"h":"Óvatosság, ellenjavallat","t":"Th6 feletti sérülésben figyelj az autonóm dysreflexiára. Tanítsd meg a decubitus-megelőző tehermentesítést; orthostaticus hypotoniánál fokozatos felállítás."},{"h":"Orvoshoz irányítás jelei","t":"Jelezd a hirtelen vérnyomás-emelkedést fejfájással, izzadással, arcpírral; a neurológiai romlást, a lázat, a decubitus romlását és az alsó végtag duzzanatát (MVT gyanúja)."}]},"keypoints":["Neurológiai szint: a legcaudalisabb, még ép funkciójú szegmentum","C6 sérülésben a tenodesis-hatást használd a fogáshoz","Autonóm dysreflexiában ültesd fel, és szüntesd meg a kiváltót (pl. telt hólyag)","Rendszeres tehermentesítő mozdulatokkal előzd meg a decubitust","Nyaki sérülésben mérd fel a légzésfunkciót, segítsd a köpürítést"],"case":{"text":"25 éves férfi, C6 komplett sérülés (AIS A), 2 hónappal a baleset után. Gyakorlás közben hirtelen erős fejfájás, arcpír és izzadás jelentkezik, a vérnyomás jelentősen megemelkedik. A katéterezés tervezett ideje már elmúlt.","answer":"Telt hólyag által kiváltott autonóm dysreflexia gyanúja. Állítsd le a gyakorlást, ültesd fel (fej megemelve), lazítsd meg a ruházatot, keresd és szüntesd meg a kiváltó okot, és azonnal értesítsd az orvost és a nővért. Ne hagyd fekvő helyzetben várakozni."},"questions":[{"level":"Alap","q":"Melyik a C7 kulcsizma, amely lehetővé teszi a kitolásos (push-up) transzfert?","options":["m. biceps brachii","m. triceps brachii","m. iliopsoas","m. quadriceps femoris"],"answer":1,"exp":"A C7 kulcsizma a m. triceps brachii (könyökextenzió). A m. biceps brachii C5, a m. iliopsoas L2, a m. quadriceps femoris L3 kulcsizma."},{"level":"Alap","q":"Melyik sérülési szintre jellemző, hogy a tenodesis-hatást fogásra használják?","options":["C4","Th6","C6","L3"],"answer":2,"exp":"C6 sérülésben a csukló extenziója lehetséges; extenzióra az ujjak passzívan flektálnak (tenodesis-hatás), ez fogásra használható."},{"level":"Középhaladó","q":"Mit jelent az ASIA károsodási skála (AIS) A fokozata?","options":["Inkomplett, csak az érzés marad","Részben megmaradt motoros funkció","Neurológiailag ép","S4–5-ben sincs motoros, szenzoros funkció"],"answer":3,"exp":"AIS A: komplett sérülés, a legalsó sacralis szegmentumokban (S4–5) sincs motoros és szenzoros funkció. AIS B: inkomplett, csak az érzés marad meg."},{"level":"Középhaladó","q":"Melyik sérülési szintnél gyakori az autonóm dysreflexia?","options":["Th6 és felette","Th12 és alatta","L3 és alatta","Cauda equina"],"answer":0,"exp":"Th6 feletti sérülésben a lézió alatti ingerekre (pl. telt hólyag) túlzott szimpatikus válasz és hirtelen vérnyomás-emelkedés jön létre."},{"level":"Klinikai","q":"C6 sérült beteg: billenőasztalon a dőlésszög emelésekor szédülés, sápadtság és vérnyomásesés jelentkezik. Mit teszel?","options":["Tovább emeled, hogy hozzászokjon","Azonnal vízszintesbe állítod az asztalt","Folytatod a gyakorlást","Ülésben előrehajlíttatod a nyakát"],"answer":1,"exp":"Orthostaticus hypotonia gyanúja. Állítsd vissza a dőlést, ellenőrizd a tüneteket és a vérnyomást. Megelőzés: hasi kötő, kompressziós harisnya, fokozatos felállítás."},{"level":"Klinikai","q":"Háti komplett sérült, kerekesszékes beteg: a sacralis bőrpír nyomásra sem halványodik, tartósan fennáll. Mit teszel?","options":["Erősen masszírozod a bőrpírt","Hosszabb üléssel szoktatod","Átnézed a tehermentesítés módját, gyakoriságát","Nem kell tenni semmit"],"answer":2,"exp":"A tartós bőrpír a decubitus korai jele. Vizsgáld felül a tehermentesítést és az ülőpárnát, jelezd az ellátó csapatnak. A pír masszírozása súlyosbítja a szövetkárosodást."}],"seccion":"Sérülések és rehabilitáció","grupo":"Neurológia","icono":"🧠","mapa":"img/mapas/t40.jpg","fichas":[],"secuencias":[]},"41":{"id":41,"title":"Perifériás idegsérülések","lead":"Trauma vagy kompresszió miatt sérül a perifériás ideg, és csökken az ellátási terület motoros, szenzoros és vegetatív funkciója. Fontos a sérülés súlyosságának és a regeneráció menetének követése.","sheet":{"kind":"condition","items":[{"h":"Kórkép","t":"Seddon-beosztás: átmeneti vezetési zavar (neurapraxia), axonszakadás (axonotmesis), az ideg teljes átszakadása (neurotmesis)."},{"h":"Fő tünetek","t":"Az ellátott izmok petyhüdt bénulása és atrófiája, érzészavar és verejtékezési zavar az ellátási területen. Az ínreflexek csökkentek vagy kiesnek."},{"h":"Vizsgálati szempontok","t":"Manuális izomtesztelés, érzésvizsgálat (tapintás, fájdalom, kétpont-diszkrimináció), a Tinel-jel helyének változása, EMG- és idegvezetési vizsgálat eredményei."},{"h":"A kezelés menete","t":"Ortézissel előzd meg a bénult izmok túlnyúlását, tartsd fenn a mozgástartományt. A reinnerváció ütemében az aktív asszisztált gyakorlattól fokozatosan haladj az erősítés felé."},{"h":"Óvatosság, ellenjavallat","t":"Az érzéskiesés területén ügyelj az égési és nyomási sérülésekre. Kerüld a bénult izmok túlterhelését és az idegvarrat utáni túlzott nyújtást."},{"h":"Orvoshoz irányítás jelei","t":"Jelezd a bénulás hirtelen progresszióját, az erős fájdalmat vagy duzzanatot, a bőrszínváltozást, illetve ha a várt időn túl sincs javulás."}]},"keypoints":["Ha a Tinel-jel distalisan vándorol, az az idegregeneráció jele","Csüngő kéznél és lógó lábnál ortézissel előzd meg a kontraktúrát és a túlnyúlást","Tanítsd meg, hogy az érzéscsökkent területet szemmel ellenőrizze és védje","A javulás a sérüléshez közeli izmoktól a távoliak felé halad","Idegvarrat után tartsd be az orvos által előírt rögzítési időt"],"case":{"text":"45 éves férfi: humerusdiaphysis-törés óta nem tudja extendálni a csuklóját és az ujjait. A kézháton, a hüvelyk- és a mutatóujj között csökkent az érzés. A könyökextenzió lehetséges.","answer":"A humerusdiaphysis szintjén kialakult n. radialis bénulás (csüngő kéz) gyanúja. A csuklót dorsalflexióban tartó ortézissel előzd meg a túlnyúlást és a kontraktúrát, tartsd fenn a ROM-ot. A javulást Tinel-jellel és izomteszttel kövesd; ha elmarad, jelezd az orvosnak."},"questions":[{"level":"Alap","q":"Melyik ideg bénulása okoz csüngő kezet?","options":["n. medianus","n. ulnaris","n. radialis","n. musculocutaneus"],"answer":2,"exp":"A n. radialis látja el a csukló- és ujjfeszítőket; bénulásakor a csukló nem extendálható, csüngő kéz alakul ki."},{"level":"Alap","q":"Melyik ideg bénulása okozza a IV–V. ujj karomállását?","options":["n. ulnaris","n. radialis","n. axillaris","n. femoralis"],"answer":0,"exp":"N. ulnaris bénulásban az interosseusok és a IV–V. ujj lumbricalisai bénulnak, így a gyűrűs- és a kisujj karomállásba kerül."},{"level":"Középhaladó","q":"Seddon szerint melyik állapotban ép az axon, és csak a vezetés zavart átmenetileg?","options":["Neurotmesis","Neurapraxia","Axonotmesis","Waller-degeneráció"],"answer":1,"exp":"A neurapraxia az axon folytonosságának megtartásával járó átmeneti vezetési zavar; Waller-degenerációval nem jár, viszonylag gyorsan gyógyul."},{"level":"Középhaladó","q":"Melyik lelet alkalmas a perifériás idegregeneráció követésére?","options":["Fokozott ínreflexek","Babinski-reflex","Rigor","A Tinel-jel helyének vándorlása"],"answer":3,"exp":"A regenerálódó axonvég ütögetése kisugárzó zsibbadást vált ki; ha ez a pont distalisan vándorol, az a regeneráció jele."},{"level":"Klinikai","q":"Lábszárgipsz után a fibulafej nyomása miatt a boka nem flektálható dorsalisan. Mit teszel?","options":["Plantarflexióban tartod a bokát","Boka-láb ortézissel kezeled a lógó lábat","Nagy ellenállással erősíted a bénult izmot","Erős hőt adsz az érzéscsökkent területre"],"answer":1,"exp":"A n. peroneus communis bénulása okozta lógó lábnál a boka-láb ortézis előzi meg a botlást és a plantarflexiós kontraktúrát. Érzéscsökkent területen a hő égésveszélyes."},{"level":"Klinikai","q":"A csukló volaris oldalán szerzett vágás után a hüvelykujj oppozíciója nem megy, a thenar sorvad. Melyik ideg sérülése valószínű?","options":["n. ulnaris","n. radialis ramus superficialis","n. medianus","n. musculocutaneus"],"answer":2,"exp":"A n. medianus látja el a thenarizmokat (pl. m. opponens pollicis); bénulásakor nehezített az oppozíció, majomkéz alakul ki."}],"seccion":"Sérülések és rehabilitáció","grupo":"Neurológia","icono":"🧠","mapa":"img/mapas/t41.jpg","fichas":[],"secuencias":[]},"42":{"id":42,"title":"Manuálterápia (Maitland)","lead":"Az ízületi járulékos mozgások vizsgálatán és fokozatokba sorolt, oszcilláló passzív mozgásokon alapuló rendszer, amely a fájdalomra és a mozgástartományra hat. Jellemzője a vizsgálat és az újravizsgálat ismétlése.","sheet":{"kind":"method","items":[{"h":"Cél","t":"Az ízületi járulékos mozgások felhasználásával csökkenti a fájdalmat és javítja az ízület mobilitását. A technikát és az erősséget a beteg reakciója alapján választod."},{"h":"Fő technikák és típusok","t":"Oszcilláló passzív mozgások I–IV. fokozatban. Az V. fokozat nagy sebességű, kis amplitúdójú thrust (manipuláció)."},{"h":"Javallatok","t":"Ízületi eredetű fájdalom, valamint a tok vagy a szalagok rövidülése miatti mozgásbeszűkülés (derékfájás, nyakfájás, fagyott váll stb.)."},{"h":"Ellenjavallatok, óvatosság","t":"Nem alkalmazható törés, malignus daganat, fertőzés, gyulladásos betegség akut szakasza, súlyos osteoporosis, progrediáló neurológiai tünet vagy nyaki érkárosodás gyanúja esetén."},{"h":"Kivitelezési tippek","t":"Fájdalom túlsúlyában I–II., merevség túlsúlyában III–IV. fokozatot válassz. A kezelés előtt és után ellenőrizd az összehasonlító jeleket, így ítéld meg a hatást."},{"h":"Evidencia","t":"Terápiás gyakorlatokkal kombinálva rövid távon csökkentheti a fájdalmat. Önmagában alkalmazva a hosszú távú hatása korlátozott."}]},"keypoints":["Fájdalomnál I–II., merevségnél III–IV. fokozat","A kezelés előtt és után az összehasonlító jelekkel ítéld meg a hatást","A járulékos mozgást az oldalkülönbség és a végérzés alapján vizsgáld","A technika előtt zárd ki a vörös zászlókat","Az elért mozgástartományt otthoni gyakorlatokkal tartasd fenn"],"case":{"text":"50 éves férfi, krónikus jobb oldali nyaki merevség. Nyugalmi fájdalma alig van; a jobbra rotáció végén ellenállást és enyhe fájdalmat érez. Vörös zászló nincs.","answer":"A merevség dominál a fájdalom felett, így az ellenállásba hatoló III–IV. fokozat jöhet szóba. A kezelés előtt és után vizsgáld újra a rotációs ROM-ot és a fájdalmat, és vezesd át otthoni gyakorlatokba. Vizsgálat nélkül ne alkalmazz erős thrustot."},"questions":[{"level":"Alap","q":"Melyik írja le helyesen a Maitland IV. fokozatot?","options":["Nagy amplitúdó az ellenállás előtt","Kis amplitúdó a tartomány elején","Kis amplitúdó a tartomány végén","Nagy amplitúdó az ellenállásban"],"answer":2,"exp":"A IV. fokozat kis amplitúdójú mozgás az ellenállásban, a mozgástartomány végén. Kis amplitúdó a tartomány elején: I.; nagy amplitúdó az ellenállásban: III."},{"level":"Alap","q":"Melyik fokozatot választod elsősorban fájdalomcsillapításra?","options":["I–II. fokozat","III–IV. fokozat","Csak V. fokozat","Csak IV. fokozat"],"answer":0,"exp":"Az I–II. fokozat az ellenállás előtti tartományban zajlik, főként fájdalomcsillapításra. A III–IV. a merevségre és a mozgásbeszűkülésre való."},{"level":"Középhaladó","q":"Milyen technikát jelöl a Maitland V. fokozat?","options":["Nagy amplitúdó az ellenállás előtt","Nagy sebességű, kis amplitúdójú thrust","Tartós trakció","Lágyrész-gyúrás"],"answer":1,"exp":"Az V. fokozat a mozgástartomány végén végzett nagy sebességű, kis amplitúdójú thrust, vagyis manipuláció."},{"level":"Középhaladó","q":"Mit hasonlítasz össze a kezelés előtt és után a hatás megítéléséhez?","options":["Laborértékeket","Képalkotó leleteket","A testsúly változását","Összehasonlító jeleket (asterisk)"],"answer":3,"exp":"Kezelés előtt rögzítsd a reprodukálható tüneteket és mozgástartományt összehasonlító jelként, majd utána ellenőrizd a változást."},{"level":"Klinikai","q":"Akut derékfájós beteg: mozgatásra erős fájdalom és védekező izomfeszülés. Melyik fokozattal kezdesz?","options":["IV. fokozat","V. fokozat","I–II. fokozat","III. fokozat"],"answer":2,"exp":"Erős fájdalom és fokozott reaktivitás esetén az ellenállásba nem hatoló I–II. fokozattal csillapítsd a fájdalmat."},{"level":"Klinikai","q":"Nyakfájós beteg: nyakrotációra szédülés, kettőslátás és dysarthria jelentkezik. Mit teszel?","options":["Leállsz, és jelzed az orvosnak","Erősíted a IV. fokozatot","Thrusttal próbálsz javítani","Növeled az ismétlésszámot"],"answer":0,"exp":"A szédülés, a kettőslátás és a dysarthria nyaki érkárosodásra utaló jel. Hagyd abba a manuálterápiát, és jelezd az orvosnak."}],"seccion":"Kezelések és beavatkozások","grupo":"Technikák és fizikoterápia","icono":"🤲","mapa":"img/mapas/t42.jpg","fichas":[],"secuencias":[]},"43":{"id":43,"title":"Proprioceptív neuromuszkuláris facilitáció (PNF)","lead":"A proprioceptorok ingerlésével serkenti az ideg-izom válaszokat. Jellemzői a spirális-diagonális mozgásminták; az izomerő, a koordináció és a mozgástartomány javítására használjuk.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A proprioceptorok ingerlésével facilitálja a motoros választ, és javítja az izomerőt, a koordinációt, a stabilitást és a mozgástartományt."},{"h":"Fő technikák és típusok","t":"A vállöv, a medenceöv és a végtagok diagonális mintái ritmikus mozgáskezdéssel, tartás–lazítással, ritmikus stabilizációval és más technikákkal kombinálva."},{"h":"Javallatok","t":"Központi idegrendszeri és ortopédiai kórképek, sportsérülések, ha izomgyengeség, koordinációzavar, mozgásbeszűkülés vagy ízületi instabilitás áll fenn."},{"h":"Ellenjavallatok, óvatosság","t":"Nem alkalmazható gyógyulatlan törésnél, olyan posztoperatív területen, ahol még nem engedélyezett az ellenállás, és erős fájdalomnál. Kardiovaszkuláris kockázatnál figyelj a légzésvisszatartásra."},{"h":"Kivitelezési tippek","t":"Kombináld a manuális kontaktust, a verbális utasítást, a vizuális visszajelzést, a trakciót/approximációt, a nyújtást, az optimális ellenállást és az időzítést. Az ellenállás ne gátolja a gördülékeny mozgást."},{"h":"Evidencia","t":"Beszámolók szerint javítja a mozgástartományt és az izomfunkciót. A hatás a kórképtől és a céltól függ; más terápiás gyakorlatokkal kombinálva alkalmazzuk."}]},"keypoints":["Fájdalom miatti mozgásbeszűkülésnél: tartás–lazítás","Ha nehéz a mozgás elindítása: ritmikus mozgáskezdés","Az ellenállás „optimális” legyen: ne gátolja a gördülékeny mozgást","Normál időzítésben a mozgás distalisan indul","Kerüld a légzésvisszatartást, a beteg folyamatosan lélegezzen"],"case":{"text":"60 éves nő, periarthritis humeroscapularis után beszűkült abdukció. Mozgáskor erős a fájdalom, passzív nyújtásra fokozódik a védekező izomfeszülés.","answer":"Fájdalommal járó mozgásbeszűkülésre az izometriás kontrakciót alkalmazó tartás–lazítás a megfelelő. A fájdalom fokozása nélkül végezd, előtte és utána mérd a ROM-ot. Kerüld az ismételt erős passzív nyújtást."},"questions":[{"level":"Alap","q":"Mi jellemző a PNF mozgásmintáira?","options":["Egysíkú, egyenes vonalú mozgás","Spirális-diagonális mozgás","Csak izokinetikus mozgás","Csak passzív mozgás"],"answer":1,"exp":"A PNF-minták a flexió–extenzió, az addukció–abdukció és a rotáció komponenseit egyesítő spirális-diagonális mozgások."},{"level":"Alap","q":"Melyik PNF-alapelem közvetíti a gyógytornász kezén át a mozgás irányát?","options":["Hideginger","Elektromos ingerlés","Manuális kontaktus","Ultrahang"],"answer":2,"exp":"A manuális kontaktus a mozgás irányába ható nyomással vezeti a beteg izomkontrakcióját és mozgásirányát."},{"level":"Középhaladó","q":"Melyik PNF-technikát alkalmazod, ha a betegnek nehéz elindítani a mozgást?","options":["Tartás–lazítás","Feszítés–lazítás","Ritmikus stabilizáció","Ritmikus mozgáskezdés"],"answer":3,"exp":"A ritmikus mozgáskezdés passzív → aktív asszisztált → aktív → ellenállásos sorrendben halad, segítve a mozgás indítását és tanulását."},{"level":"Középhaladó","q":"Melyik technika növeli az ízületi stabilitást váltakozó izometriás kontrakciókkal?","options":["Ritmikus stabilizáció","Ritmikus mozgáskezdés","Feszítés–lazítás","Ismételt nyújtás"],"answer":0,"exp":"A ritmikus stabilizációban mozgás nélkül, váltakozva izometriásan kontrahálnak az antagonista izomcsoportok, ami növeli a stabilitást."},{"level":"Klinikai","q":"A térd flexiója fájdalom miatt beszűkült. Melyik PNF-technika alkalmas a mozgástartomány javítására?","options":["Feszítés–lazítás","Tartás–lazítás","Ismételt nyújtás","Ritmikus mozgáskezdés"],"answer":1,"exp":"A tartás–lazításnál a korlátozó izom izometriás kontrakcióját ellazulás követi; fájdalommal járó mozgásbeszűkülésben alkalmazzuk."},{"level":"Klinikai","q":"Ellenállásos PNF-gyakorlat közben a beteg visszatartja a lélegzetét, és kipirul az arca. Mit teszel?","options":["Tovább növeled az ellenállást","Növeled az ismétlésszámot","Szólsz, hogy ne tartsa vissza a levegőt","Gyorsabb tempót kérsz"],"answer":2,"exp":"A légzésvisszatartás vérnyomás-emelkedést okoz. Állítsd be az ellenállást, és kérd, hogy folyamatosan lélegezve végezze a gyakorlatot."}],"seccion":"Kezelések és beavatkozások","grupo":"Technikák és fizikoterápia","icono":"🤲","mapa":"img/mapas/t43.jpg","fichas":[],"secuencias":[]},"44":{"id":44,"title":"Elektroterápia","lead":"Elektromos ingerléssel csillapítja a fájdalmat vagy vált ki izomkontrakciót. Az ingeráram típusát és paramétereit a célhoz igazítva választjuk, az ellenjavallatokat mindig ellenőrizni kell.","sheet":{"kind":"method","items":[{"h":"Cél","t":"Fájdalomcsillapítás, izomkontrakció kiváltásával az izomerő megőrzése és fokozása, a mozgás újratanulása, ödémacsökkentés."},{"h":"Fő technikák és típusok","t":"TENS (transzkután elektromos idegstimuláció), NMES (neuromuszkuláris elektromos stimuláció), FES (funkcionális elektromos stimuláció), interferenciaáram, nagyfeszültségű impulzusáram stb."},{"h":"Javallatok","t":"Akut és krónikus fájdalom, műtét vagy immobilizáció utáni izomgyengeség, a stroke utáni paretikus izmok facilitációja, lógó láb ingerlése járás közben."},{"h":"Ellenjavallatok, óvatosság","t":"Kerülendő pacemaker és más beültetett elektronikus eszköz esetén, várandósnál a hason és a derékon, a sinus caroticus felett, daganatos, sérült bőrű és érzészavaros területen."},{"h":"Kivitelezési tippek","t":"Ellenőrizd a bőr állapotát és az érzést; az elektróda helyét és méretét, a frekvenciát, az impulzusszélességet, az intenzitást és a kezelési időt a célhoz igazítsd."},{"h":"Evidencia","t":"Beszámolók szerint hasznos a műtét utáni quadricepsgyengeségben és a stroke utáni funkcionális javulásban. A fájdalomra gyakorolt hatás eredményei ellentmondásosak."}]},"keypoints":["Kezelés előtt ellenőrizd a bőr állapotát és az esetleges érzészavart","Az anamnézisben mindig kérdezz rá a beültetett elektronikus eszközökre","Fájdalomra TENS-t, izomkontrakció kiváltására NMES-t válassz","Kezelés után figyeld meg, van-e bőrpír vagy melegség az elektróda alatt","Az elektromos ingerlést aktív gyakorlással kombináld"],"case":{"text":"65 éves férfi, térdprotézis-műtét után. A m. quadriceps akaratlagos kontrakciója gyenge, SLR-nél a térd nem nyúlik ki teljesen (extenziós deficit). Pacemakere nincs, bőrelváltozás nincs.","answer":"A quadriceps gyengeségére és elégtelen kontrakciójára NMES jöhet szóba, aktív gyakorlással kombinálva. Az elektródákat a műtéti sebet elkerülve helyezd fel, figyeld a bőr- és a fájdalomreakciót. Sebre és érzéscsökkent területre ne adj áramot."},"questions":[{"level":"Alap","q":"Melyik elektroterápia szolgál szenzoros szintű ingerrel főként fájdalomcsillapításra?","options":["FES","TENS","NMES","Ultrahang"],"answer":1,"exp":"A TENS transzkután az érzőidegeket ingerli fájdalomcsillapítás céljából. Az NMES izomkontrakciót vált ki, a FES a mozgást segíti."},{"level":"Alap","q":"Melyik elektroterápia ingerli az izmot a mozgáshoz (pl. a járáshoz) időzítve, a funkciót pótolva?","options":["TENS","Ultrahang","FES","Meleg pakolás"],"answer":2,"exp":"A FES (funkcionális elektromos stimuláció) a mozgás ütemében ingerli az izmokat, és pótolja a funkciót, pl. lógó lábnál járás közben."},{"level":"Középhaladó","q":"Melyik az elektroterápia ellenjavallata?","options":["Krónikus derékfájás","Műtét utáni izomgyengeség","Lógó láb","Beültetett pacemaker"],"answer":3,"exp":"A beültetett elektronikus eszközök az ingeráram hatására hibásan működhetnek, ezért ellenjavallatot jelentenek. A többi lehetőség indikáció."},{"level":"Középhaladó","q":"Melyik módszer keresztez két középfrekvenciás áramot, hogy a mélyben kisfrekvenciás inger jöjjön létre?","options":["Interferenciaáram","TENS","FES","Iontoforézis"],"answer":0,"exp":"Az interferenciaáram két eltérő frekvenciájú középfrekvenciás áramot keresztez; a különbségüknek megfelelő kisfrekvenciás inger a mélyben keletkezik."},{"level":"Klinikai","q":"Térdprotézis után gyenge a quadriceps akaratlagos kontrakciója. Mi a megfelelő választás?","options":["Csak hőterápia","NMES aktív gyakorlással kombinálva","Elektróda a műtéti sebre","Pihentetés, amíg visszatér a kontrakció"],"answer":1,"exp":"Az NMES-t műtét utáni quadriceps-kontrakciós elégtelenségben alkalmazzuk, aktív gyakorlással kombinálva. Az elektródát a sebet elkerülve helyezd fel."},{"level":"Klinikai","q":"Elektromos ingerlés után az elektróda helyén bőrpír és hólyag látható. Mit teszel?","options":["Nagyobb intenzitással folytatod","Ugyanoda ragasztod fel újra","Leállsz, megnézed a bőrt, és jelzed","Melegítéssel kivársz"],"answer":2,"exp":"Az elektróda alatti bőrpír és hólyag bőrsérülésre utalhat. Állítsd le a kezelést, dokumentáld a bőr állapotát, és jelezd."}],"seccion":"Kezelések és beavatkozások","grupo":"Technikák és fizikoterápia","icono":"🤲","mapa":"img/mapas/t44.jpg","fichas":[],"secuencias":[]},"45":{"id":45,"title":"Ultrahang, lézer, hő- és hidegterápia","lead":"Hővel, hanghullámmal, fénnyel vagy hűtéssel hat a fájdalomra és a szövetek állapotára. A fázis és a cél alapján döntesz a melegítés vagy a hűtés mellett, és ellenőrzöd az ellenjavallatokat.","sheet":{"kind":"method","items":[{"h":"Cél","t":"Fájdalomcsillapítás, izomtónus-csökkentés, a szövetek nyújthatóságának javítása, az akut gyulladásos duzzanat mérséklése; a terápiás gyakorlatok előtt vagy után."},{"h":"Fő technikák és típusok","t":"Ultrahang (folyamatos, impulzus), kis teljesítményű lézer, felületi hőterápia (meleg pakolás, paraffin), mikrohullámú diatermia, hidegterápia (jégpakolás stb.)."},{"h":"Javallatok","t":"Hő: krónikus fájdalom, merevség, kontraktúra; hideg: akut sérülés utáni fájdalom és duzzanat; ultrahang: többek között a lágyrészek nyújthatóságának javítása."},{"h":"Ellenjavallatok, óvatosság","t":"Kerülendő a hő akut gyulladásban, vérzékenységnél, daganatos területen; az ultrahang a szemen, várandós hasán, a növekedési porcon; a hideg Raynaud-jelenséggel érintett területen."},{"h":"Kivitelezési tippek","t":"Kezelés előtt ellenőrizd a bőrt és a hő-hideg érzést, közben is figyeld a bőrt. Az ultrahangfejet folyamatosan mozgasd, ne állj meg egy ponton."},{"h":"Evidencia","t":"A terápiás gyakorlatok kiegészítéseként rövid távú fájdalomcsillapításra használják. Önálló hatása a legtöbb beszámoló szerint korlátozott; a fő elem a mozgásterápia."}]},"keypoints":["Akut duzzanatra és melegségre hideg, krónikus merevségre hő","Előtte ellenőrizd a hő-hideg érzést, érzészavaros területet kerülj","Az ultrahangfejet megállás nélkül mozgasd","Hőkezelés után jól kapcsolható hozzá nyújtás és mozgásterápia","A fizikális terápia a mozgásterápia kiegészítője"],"case":{"text":"22 éves férfi, focizás közben inverziós bokaficamot szenvedett; a sérülés másnapja. A külboka körül duzzanat, melegség és nyomásérzékenység, terheléskor erős fájdalom. Az orvos a törést kizárta.","answer":"Akut gyulladásos jelek vannak, ezért hidegterápiával, kompresszióval és felpolcolással csökkentsd a fájdalmat és a duzzanatot. A hő ebben a fázisban fokozhatja a duzzanatot, kerüld. A fagyási sérülés megelőzésére kezelés közben figyeld a bőrt."},"questions":[{"level":"Alap","q":"Melyik fizikális terápiát alkalmazod akut duzzanat és fájdalom csökkentésére?","options":["Meleg pakolás","Paraffin","Hidegterápia","Mikrohullámú diatermia"],"answer":2,"exp":"A hideg érszűkületet okoz, csökkenti az akut fájdalmat és duzzanatot. A többi lehetőség hőterápia, akut gyulladásban kerülendő."},{"level":"Alap","q":"Melyik tartozik a felületi hőterápiák közé?","options":["Mikrohullámú diatermia","Meleg pakolás","Folyamatos ultrahang","Kis teljesítményű lézer"],"answer":1,"exp":"A meleg pakolás és a paraffin a bőrtől a felületes szöveteket melegíti. A mikrohullámú diatermia és a folyamatos ultrahang mélyhőterápia."},{"level":"Középhaladó","q":"Melyik terület ellenjavallt ultrahangkezelésre?","options":["m. quadriceps femoris","A váll környéke","m. triceps surae","Szemgolyó"],"answer":3,"exp":"A szemgolyó ultrahangkezelésre ellenjavallt terület. Kerülendő továbbá a várandós has, a növekedési porc és a daganatos terület."},{"level":"Középhaladó","q":"Melyik az ultrahangkezelés helyes kivitelezése?","options":["Folyamatosan mozgatod a fejet","Egy ponton tartod a fejet","Gél nélkül alkalmazod","Fájdalom esetén is folytatod"],"answer":0,"exp":"Ha a fej egy helyben áll, a hő koncentrálódik és szövetkárosodást okozhat, ezért géllel, folyamatos mozgatással alkalmazzuk."},{"level":"Klinikai","q":"Bokaficam, a sérülés másnapja: kifejezett duzzanat és melegség. Melyik a megfelelő fizikális terápia?","options":["Meleg pakolás","Hideg, kompresszió, felpolcolás","Paraffin","Mikrohullámú diatermia"],"answer":1,"exp":"Akut gyulladásos jelek esetén hideggel, kompresszióval és felpolcolással csökkentsd a fájdalmat és a duzzanatot. A hő fokozhatja a duzzanatot."},{"level":"Klinikai","q":"Diabeteses neuropathia miatt csökkent a láb érzése; meleg pakolást terveznek a lábra. Mit teszel?","options":["Magasabb hőfokon, rövid ideig adod","A szokásos módon alkalmazod","Érzéscsökkent területre nem adsz hőt","Alvás közben hosszan alkalmazod"],"answer":2,"exp":"Az érzészavaros terület nem érzékeli jól a meleget, nagy az égés veszélye. Kerüld a hőterápiát, és válassz más módszert."}],"seccion":"Kezelések és beavatkozások","grupo":"Technikák és fizikoterápia","icono":"🤲","mapa":"img/mapas/t45.jpg","fichas":[],"secuencias":[]},"46":{"id":46,"title":"Hidroterápia, masszázs és manuális nyirokdrenázs","lead":"A hidroterápia a víz felhajtóerejét, nyomását és hőmérsékletét használja, a masszázs és a manuális nyirokdrenázs kézzel hat a lágyrészekre. A kulcs a javallatok és ellenjavallatok pontos mérlegelése.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A hidroterápia a felhajtóerővel, víznyomással és hővel segíti a mozgást és a fájdalomcsillapítást. A masszázs az izomtónust oldja, a manuális nyirokdrenázs a nyiroködémát csökkenti."},{"h":"Fő technikák és típusok","t":"Örvényfürdő, Hubbard-kád, medencés gyógytorna. Masszázs: simítás, gyúrás, nyomás stb. Nyiroködémában komplex fizikális ödématerápia (bőrápolás, manuális drenázs, kompresszió, mozgás)."},{"h":"Javallatok","t":"Terheléskorlátozást igénylő ízületi betegségek és műtétek után, fájdalom és fokozott izomtónus, másodlagos nyiroködéma (pl. daganatműtét után), elsődleges nyiroködéma."},{"h":"Ellenjavallatok, óvatosság","t":"Láz, akut fertőzés (pl. cellulitis), akut mélyvénás trombózis, nyílt seb, dekompenzált szívelégtelenség. Vízben a hidrosztatikai nyomás növeli a szív terhelését."},{"h":"Kivitelezési tippek","t":"A nyirokdrenázst az ödémás területtől centrálisan kezdd, csak a bőrt elmozdító, enyhe nyomással. Vízi tornánál ellenőrizd a vízhőt, az időtartamot, az állapotot és a vitális paramétereket."},{"h":"Evidencia","t":"Nyiroködémában a kompressziót is tartalmazó komplex terápia ajánlott. A masszázs önmagában korlátozott hatású, ezért terápiás gyakorlatokkal együtt alkalmazzuk."}]},"keypoints":["A felhajtóerő könnyíti a terhelést; a teher a vízmélységgel változik","A hidrosztatikai nyomás segíti a vénás visszaáramlást, de terheli a szívet","A nyirokdrenázst centrálisan, enyhe nyomással kezdd","Bőrpír, melegség, láz: fertőzésre gyanakodj, állj le","Nyiroködémában kompressziót is tartalmazó komplex terápia"],"case":{"text":"65 éves nő. Emlőrák-műtét utáni másodlagos nyiroködéma; az érintett felső végtag körfogata nagyobb az épnél. Nincs bőrpír, melegség vagy láz, mélyvénás trombózist nem diagnosztizáltak.","answer":"Fertőzés és trombózis jele nélkül a komplex terápia javallt. Kombináld a bőrápolást, a centrálisan kezdett, enyhe nyomású manuális drenázst, a kompressziót és a kompresszió alatti mozgást. Bőrpír vagy láz esetén állj le és küldd orvoshoz."},"questions":[{"level":"Alap","q":"A víz melyik tulajdonsága csökkenti az ízületekre ható testsúlyterhet?","options":["Felhajtóerő","Viszkozitás","Fajhő","Felületi feszültség"],"answer":0,"exp":"A felhajtóerő a testsúllyal ellentétesen hat, így csökkenti a terhelést. A viszkozitás a mozgással szembeni ellenállás, a fajhő a hőhatással függ össze."},{"level":"Alap","q":"Manuális nyirokdrenázsnál melyik területet kezeled először?","options":["Az ödéma legkifejezettebb disztális részét","Az ödémás területtől centrálisabb részt","Az ujjak és lábujjak végét","Csak a legfájdalmasabb részt"],"answer":1,"exp":"Először a centrális részt (nyirokcsomók, törzs felőli oldal) drenálod, hogy utat nyiss, majd haladsz disztálisan."},{"level":"Középhaladó","q":"Melyik a manuális nyirokdrenázs legjellemzőbb ellenjavallata?","options":["Krónikus másodlagos nyiroködéma","Fenntartó fázisú felsővégtagi nyiroködéma","Akut mélyvénás trombózis","Enyhe bőrszárazság"],"answer":2,"exp":"Akut mélyvénás trombózisban a trombus elszabadulhat, ezért ellenjavallt. A krónikus nyiroködéma javallat, a bőrszárazságot bőrápolással kezeljük."},{"level":"Középhaladó","q":"Mi NEM része a nyiroködéma komplex terápiájának?","options":["Bőrápolás","Manuális nyirokdrenázs","Kompressziós terápia","Az érintett végtag tartós nyugalomba helyezése"],"answer":3,"exp":"A komplex terápia elemei: bőrápolás, manuális drenázs, kompresszió és kompresszió alatti gyakorlatok. A tartós immobilizáció nem része."},{"level":"Klinikai","q":"60-as éveiben járó nő, emlőrák-műtét utáni karödéma. Drenázs közben a végtagon hirtelen bőrpír, melegség és láz jelenik meg. Mit teszel?","options":["Növeled a drenázs nyomását","Abbahagyod a kezelést, jelzed az orvosnak","Hőkezelést adsz hozzá","Erősebb kompresszióval folytatod"],"answer":1,"exp":"Akut fertőzésre (pl. cellulitis) utaló jelek. Állítsd le a drenázst, a kompressziót és a hőkezelést, és haladéktalanul küldd orvoshoz."},{"level":"Klinikai","q":"70-es éveiben járó férfi, szívelégtelenség, nyugalomban is nehézlégzés. Medencés gyógytornát mérlegelsz. Mi a helyes döntés?","options":["A szívterhelés nő, egyeztess orvossal","A felhajtóerő miatt korlátozás nélkül végezhető","Mély vízben, hosszan végezd","Melegebb vízben végezd"],"answer":0,"exp":"Vízben a hidrosztatikai nyomás fokozza a vénás visszaáramlást és a szív terhelését. Nem stabil szívelégtelenségben az orvossal egyeztesd a javallatot."}],"seccion":"Kezelések és beavatkozások","grupo":"Technikák és fizikoterápia","icono":"🤲","mapa":"img/mapas/t46.jpg","fichas":[],"secuencias":[]},"47":{"id":47,"title":"Kineziotape","lead":"Rugalmas szalagot ragasztunk a bőrre, hogy szenzoros ingert adjunk és segítsük az ízületi mozgást. Ismerd a felragasztás alapjait és a bőrproblémák megelőzését; a terápiás gyakorlatok kiegészítőjeként használd.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A bőrön keresztüli szenzoros ingerrel segíti az izomaktivitást, irányítja az ízületi mozgást, javítja a testtartás tudatosítását, és segíthet az ödéma, bevérzés csökkentésében. Erős rögzítés nem cél."},{"h":"Fő technikák és típusok","t":"Formák: I, Y, X és legyező (nyirok). Vannak izomra, ízülettámogatásra és ödémára irányuló felragasztások. Rögzítésre nem rugalmas (merev) tape-et használunk."},{"h":"Javallatok","t":"Sportsérülés utáni fájdalom és duzzanat csökkentésének segítése, az izomhasználat újratanulása, testtartás és tengelyállás tudatosítása, terápiás gyakorlatok mellett."},{"h":"Ellenjavallatok, óvatosság","t":"Bőrsérülés, fertőzés, ekcéma, korábbi tapeallergia, mélyvénás trombózis gyanúja, sérülékeny bőrű idős. Érzészavaros területen a bőrprobléma nehezen vehető észre."},{"h":"Kivitelezési tippek","t":"A bőr legyen tiszta és száraz, a sarkokat vágd le kerekre. A két véget feszítés nélkül ragaszd fel. Először kis darabbal próbálj, és kérd, hogy viszketés vagy bőrpír esetén azonnal vegye le."},{"h":"Evidencia","t":"A legtöbb vizsgálat szerint a fájdalomra kifejtett hatás rövid távú és korlátozott, ezért nem önálló kezelés, hanem a terápiás gyakorlatok kiegészítője."}]},"keypoints":["A rugalmas tape célja a támogatás, nem a rögzítés","A két véget feszítés nélkül fektesd a bőrre","Tiszta, száraz bőr; a sarkokat vágd kerekre","Viszketés vagy bőrpír esetén azonnal le kell venni","Hatása korlátozott, terápiás gyakorlatokkal kombináld"],"case":{"text":"22 éves férfi, inverziós bokaficam után 3 nappal. A külboka körül duzzanat és bevérzés látható, terheléskor enyhe fájdalom. Még sosem tapelték, bőrbetegsége nem volt.","answer":"Először nézd meg a bőr állapotát, és ragassz fel egy kis próbadarabot. A duzzanatra legyező formát tegyél kis feszítéssel, a terápiás gyakorlatok mellett. Ne mondd, hogy a tape meggyógyítja; kérd, hogy viszketés vagy bőrpír esetén vegye le."},"questions":[{"level":"Alap","q":"Milyen feszítéssel ragasztod fel a rugalmas tape két végét?","options":["Maximálisan megnyújtva","Csak a végeket erősen megfeszítve","Feszítés nélkül","A bőrt összecsípve"],"answer":2,"exp":"A két véget (horgonyt) feszítés nélkül fekteted a bőrre. A végeken lévő feszítés húzza a bőrt, leváláshoz és bőrirritációhoz vezet."},{"level":"Alap","q":"Melyik az a forma, amelynél a tape-et két szárra vágod, és az izomhasat körülfogod?","options":["I-forma","X-forma","Legyező forma","Y-forma"],"answer":3,"exp":"Az Y-forma tövét egy ponton rögzíted, a két szárral az izomhasat fogod körül. A legyező formát vékony csíkokra vágva az ödémán terítjük szét."},{"level":"Középhaladó","q":"Melyik jel esetén kell tapelés után azonnal levenni a szalagot?","options":["Viszketés vagy bőrpír a felragasztás helyén","Enyhe izomfeszülés edzés után","Könnyebben figyel a testtartására","Könnyebbnek érzi a mozgást"],"answer":0,"exp":"A viszketés és a bőrpír bőrirritáció (pl. tapeallergia) jele. A romlás megelőzésére kérd, hogy azonnal vegye le."},{"level":"Középhaladó","q":"Mit választasz, ha az ízület mozgását erősen korlátozni, rögzíteni akarod?","options":["Rugalmas tape I-forma","Nem rugalmas (merev) tape","Rugalmas tape legyező forma","Feszítés nélküli Y-forma"],"answer":1,"exp":"Erős rögzítéshez nem rugalmas tape kell. A rugalmas tape alig gátolja a mozgást; célja a támogatás és a szenzoros inger."},{"level":"Klinikai","q":"20-as éveiben járó férfi, bokaficam utáni duzzanatra tapelést tervezel. Mit a legfontosabb ellenőrizni felragasztás előtt?","options":["A járássebességet","A nyugalmi pulzust","A bőr állapotát és a korábbi tapeallergiát","Az ügyesebbik lábat"],"answer":2,"exp":"Felragasztás előtt nézd meg a bőrsérülést, ekcémát és a korábbi tapeallergiát. Bőrprobléma esetén ne tapelj."},{"level":"Klinikai","q":"30-as éveiben járó nő vállának tapelése után azt mondja: „kevésbé fáj”. Mit mondasz neki?","options":["A szövet regenerálódott, meggyógyult","A hatás gyakran átmeneti, gyakorlatokkal együtt kell","Állandóan viselnie kell","Az izomereje azonnal nőtt"],"answer":1,"exp":"A tapelés hatása rövid távú és korlátozott. Ne kelts túlzott elvárást; magyarázd el, hogy a terápiás gyakorlatok kiegészítője."}],"seccion":"Kezelések és beavatkozások","grupo":"Technikák és fizikoterápia","icono":"🤲","mapa":"img/mapas/t47.jpg","fichas":[],"secuencias":[]},"48":{"id":48,"title":"Terápiás gyakorlatok","lead":"A gyógytorna magja: előírt gyakorlatokkal javítjuk az izomerőt, a hajlékonyságot, az állóképességet és az egyensúlyt, hogy az ADL javuljon. Ismerd a terhelési elveket és a leállítási kritériumokat a biztonságos haladáshoz.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A mozgástartomány, az izomerő, az izom- és általános állóképesség, a hajlékonyság, az egyensúly és a koordináció javítása, hogy javuljanak az alapmozgások, az ADL és a részvétel."},{"h":"Fő technikák és típusok","t":"ROM-gyakorlat (passzív, aktív asszisztált, aktív), erősítés (izometriás, izotóniás – koncentrikus, excentrikus –, izokinetikus), nyújtás, aerob edzés, egyensúly- és koordinációs gyakorlat."},{"h":"Javallatok","t":"Széles körben: mozgásszervi betegségek, műtétek után, neurológiai és belgyógyászati betegségek, inaktivitási szindróma, időskori funkcióvesztés."},{"h":"Ellenjavallatok, óvatosság","t":"Instabil szívbetegség, rosszul beállított hypertonia, akut gyulladás, nem rögzített törés: óvatosság vagy ellenjavallat. Ellenőrizd a terhelés leállítási kritériumait."},{"h":"Kivitelezési tippek","t":"A terhelést a túlterhelés, a specificitás és a reverzibilitás elve szerint állítsd be, figyeld a szubjektív terhelésérzetet és a vitális paramétereket. Vedd észre a kompenzációt; ne tartsa vissza a lélegzetét."},{"h":"Evidencia","t":"Számos mozgásszervi és krónikus betegségben a terápiás gyakorlat a kezelés ajánlott alapja. A hatás azon múlik, hogy a program tartósan kivitelezhető-e."}]},"keypoints":["A terhelést a túlterhelés, specificitás és reverzibilitás elve szerint építsd","Korai posztoperatív szakban izometriás, ízületet nem mozgató gyakorlattal kezdj","Kerüld a légzésvisszatartást (préselést), lélegezzen folyamatosan","Vedd észre a kompenzációt, helyes mozgással dolgozzon","Mellkasi fájdalom, hideg verejték, erős nehézlégzés: azonnal állj le, jelezd"],"case":{"text":"72 éves nő, térdprotézis után 3 héttel. A m. quadriceps izomereje 3-as: aktívan a teljes mozgástartományban mozgat, de ellenállást nem bír. Vitális paraméterei stabilak.","answer":"A gravitáció elleni aktív mozgással kezdj, majd fokozatosan adj hozzá enyhe ellenállást. Figyeld a kompenzációt és a fájdalmat, kerüld a légzésvisszatartást. Már az első napon maximális terhelést ne adj."},"questions":[{"level":"Alap","q":"Melyik az az összehúzódási forma, amelyben az izom feszülést fejt ki, miközben megnyúlik?","options":["Koncentrikus kontrakció","Excentrikus kontrakció","Izometriás kontrakció","Izokinetikus kontrakció"],"answer":1,"exp":"Excentrikus kontrakcióban az izom megnyúlás közben fejt ki erőt. Koncentrikusban rövidülés közben, izometriásban hosszváltozás nélkül."},{"level":"Alap","q":"Melyik elv szerint kell a hétköznapinál nagyobb terhelést adni az izomerő növeléséhez?","options":["Specificitás elve","Reverzibilitás elve","Túlterhelés elve","Egyéniesítés elve"],"answer":2,"exp":"A túlterhelés elve szerint a megszokott terhelést meghaladó inger hatására jön létre az adaptáció."},{"level":"Középhaladó","q":"Melyik gyakorlat erősít ízületi mozgás nélkül, ezért jól használható korán a műtét után?","options":["Izometriás gyakorlat","Izokinetikus gyakorlat","Ugrógyakorlat","Nagy terhelésű excentrikus gyakorlat"],"answer":0,"exp":"Az izometriás gyakorlatban az izom az ízület mozgatása nélkül húzódik össze, így kíméli az ízületet és a sebet, ezért korán végezhető."},{"level":"Középhaladó","q":"Mit kell kerülni erősítő gyakorlat közben?","options":["A folyamatos légzést","A kompenzáció ellenőrzését","A bemelegítést","A légzésvisszatartást"],"answer":3,"exp":"A légzésvisszatartás (préselés) hirtelen megemeli a vérnyomást. Főleg időseknél és szívbetegeknél lélegezzen folyamatosan."},{"level":"Klinikai","q":"70-es éveiben járó férfi, a m. quadriceps izomereje 3-as. Hogyan kezded az erősítést?","options":["Maximális ellenállású izokinetikus gyakorlattal","Gravitáció elleni aktív mozgás, fokozatos terhelés","Csak passzív mozgatással","Nagy intenzitású ugrógyakorlattal"],"answer":1,"exp":"A 3-as erő azt jelenti, hogy a teljes tartományban mozgat a gravitáció ellen. Aktív mozgással kezdj, és fokozatosan adj enyhe ellenállást."},{"level":"Klinikai","q":"60-as éveiben járó férfi, szobakerékpározás közben mellkasi fájdalom és hideg verejtékezés jelentkezik. Mit teszel?","options":["Leállítod, vitálisakat mérsz, jelzed az orvosnak","Csökkented a terhelést és folytatod","Pihenő után ugyanazzal a terheléssel folytatod","Átváltasz nyújtásra"],"answer":0,"exp":"A mellkasi fájdalom és a hideg verejték leállítási kritérium, szívbetegségre utalhat. Azonnal állítsd le, mérd a vitálisakat és jelezd az orvosnak."}],"seccion":"Kezelések és beavatkozások","grupo":"Mozgásterápia és szakterületek","icono":"🩺","mapa":"img/mapas/t48.jpg","fichas":[],"secuencias":[{"nombre":"Híd","rotulo":"Erősíti","texto":"farizmok és hamstringek","frames":["img/mov/ponte-1.jpg","img/mov/ponte-2.jpg","img/mov/ponte-3.jpg"]},{"nombre":"Nyújtott lábemelés","rotulo":"Erősíti","texto":"quadriceps","frames":["img/mov/elevacao-1.jpg","img/mov/elevacao-2.jpg","img/mov/elevacao-3.jpg"]},{"nombre":"Guggolás","rotulo":"Erősíti","texto":"quadriceps és farizmok","frames":["img/mov/agachamento-1.jpg","img/mov/agachamento-2.jpg","img/mov/agachamento-3.jpg"]}]},"49":{"id":49,"title":"Légzésfizioterápia","lead":"Légzéstechnikák tanításával, a váladékürítés segítésével és terápiás gyakorlatokkal javítja a ventilációt és csökkenti a nehézlégzést. Központi szerepe van a COPD-ben és a posztoperatív tüdőszövődmények megelőzésében.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A ventiláció javítása, a légúti clearance elősegítése, a nehézlégzés csökkentése, a terhelhetőség és az ADL javítása, a posztoperatív tüdőszövődmények megelőzése."},{"h":"Fő technikák és típusok","t":"Ajakfékes légzés, rekeszlégzés, testhelyzeti drenázs, huffing és köhögéstanítás, légzéssegítés, légzőizom-edzés, általános állóképességi és erősítő gyakorlatok."},{"h":"Javallatok","t":"Krónikus légzőszervi betegségek (pl. COPD), tüdőgyulladás, mellkasi és hasi műtét előtt és után, neuromuszkuláris betegség okozta ventilációs zavar, sok váladékkal járó bronchiectasia."},{"h":"Ellenjavallatok, óvatosság","t":"Fej-mélyen helyzetű drenázs kerülendő emelkedett koponyaűri nyomás, instabil keringés, vérköpés esetén. Figyelj a kezeletlen légmellre, súlyos ritmuszavarra; kövesd az SpO2-t és a tüneteket."},{"h":"Kivitelezési tippek","t":"A váladék helyét hallgatózással, képalkotó leletből határozd meg, és ehhez válassz testhelyzetet. Kövesd az SpO2-t, a légzésszámot, a pulzust és a módosított Borg-skálát; a mozgást a légzés ritmusához igazítsd."},{"h":"Evidencia","t":"COPD-ben a terápiás gyakorlatokra épülő légzésrehabilitáció ajánlott a nehézlégzés csökkentésére és a terhelhetőség javítására."}]},"keypoints":["Az ajakfékes légzés megelőzi a légutak kilégzési kollapszusát","Testhelyzeti drenázsnál a váladékos tüdőszegmens van felül","Huffing: nyitott hangréssel erős, gyors kilégzés","Fej-mélyen helyzet kerülendő koponyaűri nyomásfokozódás, vérköpés esetén","COPD-ben a légzésrehabilitáció alapja a terápiás gyakorlat"],"case":{"text":"74 éves férfi, COPD, otthoni oxigénterápia nélkül. Járáskor és öltözködéskor erős nehézlégzés; sietős mozgás után csökken az SpO2. Kevés a váladéka, nyugalmi állapota stabil.","answer":"Taníts ajakfékes légzést és a mozgás tempójának beosztását, majd az SpO2 és a nehézlégzés követése mellett végezz állóképességi és alsóvégtag-erősítő gyakorlatokat. Kérd, hogy ne siessen visszatartott lélegzettel."},"questions":[{"level":"Alap","q":"COPD-ben melyik légzéstechnikát tanítod a légutak kilégzési kollapszusának megelőzésére?","options":["Gyors, felületes mellkasi légzés","Légzésvisszatartás","Ajakfékes légzés","Hiperventiláció"],"answer":2,"exp":"Az ajakfékes légzés ellenállást ad a kilégzéshez, fenntartja a légúti nyomást, megelőzi a kollapszust és segíti a kilégzést."},{"level":"Alap","q":"Melyik módszernél helyezed felülre a váladékos tüdőszegmenst, hogy a gravitáció segítse a váladék mozgását?","options":["Huffing","Testhelyzeti drenázs","Légzőizom-edzés","Ajakfékes légzés"],"answer":1,"exp":"A testhelyzeti (posturalis) drenázs során a váladékos szegmens van felül, és a gravitáció a centrális légutak felé mozgatja a váladékot."},{"level":"Középhaladó","q":"Melyik az a technika, amelyben nyitott hangréssel erősen, gyorsan kilélegezve mozgatod a váladékot?","options":["A köhögés elfojtása","Rekeszlégzés","Valsalva-manőver","Huffing"],"answer":3,"exp":"A huffing nyitott hangréssel végzett erőltetett kilégzés; a köhögésnél kisebb mellűri nyomásemelkedéssel mozgatja a váladékot."},{"level":"Középhaladó","q":"Melyik állapotban kerülendő a fej-mélyen helyzetű testhelyzeti drenázs?","options":["Emelkedett koponyaűri nyomás","Krónikus bronchiectasia","Sok váladékkal járó pneumonia","Alsó lebenyi atelectasia"],"answer":0,"exp":"A fej-mélyen helyzet emeli a koponyaűri nyomást, ezért emelkedett koponyaűri nyomásban kerülendő. A többi állapot a drenázs javallata lehet."},{"level":"Klinikai","q":"70-es éveiben járó férfi, COPD. Járás közben fokozódik a nehézlégzése és csökken az SpO2. Mit tanítasz?","options":["Gyorsan járjon, hogy hamar végezzen","Ajakfékes légzést és a mozgás tempójának beosztását","Visszatartott lélegzettel mozogjon","Teljesen hagyja abba a járást"],"answer":1,"exp":"A mozgás tempóját a légzéshez igazítsa, és használjon ajakfékes légzést. A teljes inaktivitás felgyorsítja a dekondicionálódást."},{"level":"Klinikai","q":"Hasi műtét utáni első napon lévő beteg. Mi segít a posztoperatív tüdőszövődmények megelőzésében?","options":["Több napos ágynyugalom","Fájdalom miatt a légzőgyakorlat kihagyása","Korai mobilizálás, mélylégzés és köhögés tanítása","Tartós fej-mélyen helyzet"],"answer":2,"exp":"A korai mobilizálás és a mélylégzés, köhögés (a seb megtámasztásával) tanítása fontos az atelectasia és a pneumonia megelőzésében."}],"seccion":"Kezelések és beavatkozások","grupo":"Mozgásterápia és szakterületek","icono":"🩺","mapa":"img/mapas/t49.jpg","fichas":[],"secuencias":[]},"50":{"id":50,"title":"Kardiológiai rehabilitáció","lead":"Terápiás gyakorlatot, betegoktatást és életmód-tanácsadást ötvöző komplex program. Célja a terhelhetőség és az életminőség javítása, valamint a visszaesés megelőzése. A biztonság az első.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A terhelhetőség és az életminőség javítása, a koszorúér-rizikófaktorok korrekciója, a visszaesés és a visszavétel megelőzése, a szorongás csökkentése és a munkába, társadalomba való visszatérés segítése."},{"h":"Fő technikák és típusok","t":"Aerob edzés (járás, szobakerékpár), rezisztív edzés, betegoktatás, életmód-tanácsadás (gyógyszerszedés, étrend, dohányzás elhagyása). Három fázisban halad: akut, rehabilitációs, fenntartó."},{"h":"Javallatok","t":"Akut myocardialis infarktus után, angina pectoris, szívműtét után, krónikus szívelégtelenség, nagyérbetegségek, perifériás artériás betegség. Feltétel a stabil állapot."},{"h":"Ellenjavallatok, óvatosság","t":"Instabil angina, kontrollálatlan ritmuszavar, dekompenzált szívelégtelenség, tünetes súlyos aortastenosis, akut myocarditis: a terápiás gyakorlat ellenjavallt."},{"h":"Kivitelezési tippek","t":"Az intenzitást a spiroergometriás anaerob küszöb (AT) vagy a szubjektív terhelésérzet alapján állítsd be. Béta-blokkoló mellett a pulzus alig emelkedik: figyeld a tüneteket, a vérnyomást és az EKG-t is."},{"h":"Evidencia","t":"Koszorúér-betegségben és krónikus szívelégtelenségben az irányelvek a terápiás gyakorlatot is tartalmazó komplex kardiológiai rehabilitációt ajánlják."}]},"keypoints":["Gyakorlat, oktatás és életmód-tanácsadás együtt","Az intenzitást az AT vagy a szubjektív terhelésérzet szerint állítsd be","Béta-blokkoló mellett ne csak a pulzus alapján dönts","Mellkasi fájdalom, ST-eltérés, ritmuszavar: állj le","Hirtelen súlygyarapodás, ödéma: szívelégtelenség romlására gyanakodj"],"case":{"text":"63 éves férfi, akut myocardialis infarktus kezelése után, a rehabilitációs fázisban ambulánsan tornázik. Béta-blokkolót szed. Szobakerékpározás közben nincs mellkasi panasza, de a pulzusa alig emelkedik.","answer":"A béta-blokkoló tompítja a pulzusválaszt, ezért ne csak a pulzus alapján emeld a terhelést: a szubjektív terhelésérzet, a vérnyomás és az EKG alapján dönts. Mellkasi fájdalom vagy ST-eltérés esetén állj le, és jelezd az orvosnak."},"questions":[{"level":"Alap","q":"Mi NEM része a kardiológiai rehabilitációnak?","options":["Terápiás gyakorlat","Betegoktatás","A koszorúér-rizikófaktorok korrekciója","Tartós ágynyugalom"],"answer":3,"exp":"A kardiológiai rehab gyakorlatot, betegoktatást, életmód-tanácsadást és pszichés támogatást tartalmazó komplex program. A tartós ágynyugalom dekondicionálódáshoz vezet."},{"level":"Alap","q":"Melyik, a spiroergometriából nyert mutatót használod az intenzitás beállításához?","options":["Manuális izomtesztelés","Anaerob küszöb (AT)","Mozgástartomány","Szorítóerő"],"answer":1,"exp":"Az anaerob küszöb (AT) az aerob edzés intenzitásának gyakori mutatója; spiroergometriával határozzuk meg."},{"level":"Középhaladó","q":"Melyik a terápiás gyakorlat ellenjavallata?","options":["Stabil krónikus szívelégtelenség","Bypassműtét utáni rehabilitációs fázis","Instabil angina","Infarktus utáni stabil szak"],"answer":2,"exp":"Az instabil angina a terápiás gyakorlat ellenjavallata. A stabil krónikus szívelégtelenség és a műtét vagy infarktus utáni rehabilitációs fázis javallat."},{"level":"Középhaladó","q":"Béta-blokkolót szedő betegnél mi hasznos az intenzitás megítélésére?","options":["Szubjektív terhelésérzet (Borg-skála)","Csak a pulzus","Testsúly","Testhőmérséklet"],"answer":0,"exp":"A béta-blokkoló gátolja a pulzus emelkedését, így csak a pulzus alapján túl nagy terhelést állíthatsz be. Használd a szubjektív terhelésérzetet is."},{"level":"Klinikai","q":"60-as éveiben járó férfi, infarktus utáni rehabilitációs fázis. Járásgyakorlat közben mellkasi fájdalom és ST-depresszió jelentkezik. Mit teszel?","options":["Növeled a járássebességet","Folytatod és figyeled","Folyadékpótlás után ugyanazzal a terheléssel","Leállítod a gyakorlatot, jelzed az orvosnak"],"answer":3,"exp":"A mellkasi fájdalom és az ST-depresszió szívizom-ischaemiára utaló leállítási jel. Azonnal állítsd le a gyakorlatot, és jelezd az orvosnak."},{"level":"Klinikai","q":"70-es éveiben járó nő, krónikus szívelégtelenség. Néhány nap alatt hirtelen nőtt a testsúlya, romlott a lábszárödéma és a nehézlégzés. Mit teszel?","options":["Növeled az intenzitást","Szívelégtelenség romlását gyanítod, szólsz orvosnak","A szokásos módon tornáztatod","Csak erősítő edzést adsz hozzá"],"answer":1,"exp":"A rövid idő alatti súlygyarapodás, ödéma és a fokozódó nehézlégzés a szívelégtelenség romlásának jele. Halaszd el a tornát, és jelezd az orvosnak."}],"seccion":"Kezelések és beavatkozások","grupo":"Mozgásterápia és szakterületek","icono":"🩺","mapa":"img/mapas/t50.jpg","fichas":[],"secuencias":[]},"51":{"id":51,"title":"Kismedencei és női egészség","lead":"A medencefenék-izmok működészavarából eredő vizeletinkontinenciával, kismedencei szervsüllyedéssel, a terhesség és a szülés utáni testi változásokkal foglalkozik. Alap a helyes kontrakció tanítása és a vörös zászlók szűrése.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A medencefenék-izmok erejének, állóképességének és koordinációjának javítása, az inkontinencia és a szervsüllyedés enyhítése; a terhesség és szülés utáni lumbopelvicus fájdalom és törzsfunkció rendezése."},{"h":"Fő technikák és típusok","t":"Medencefenék-torna, biofeedback, a hasűri nyomás és a légzés kontrolljának tanítása, testtartás- és mozgástanítás, életmód-tanácsadás (vizelési szokások, testsúlykontroll stb.)."},{"h":"Javallatok","t":"Stressz- és kevert inkontinencia, enyhe kismedencei szervsüllyedés, szülés utáni medencefenék-gyengeség, diastasis recti, radikális prosztatektómia utáni inkontinencia férfiaknál."},{"h":"Ellenjavallatok, óvatosság","t":"A belső (vaginális) vizsgálathoz szakirányú képzés, alapos tájékoztatás és beleegyezés kell. Késői terhességben a hosszú hanyatt fekvés vena cava-szindrómát okozhat. Hematuria, láz, gátzsibbadás: orvoshoz."},{"h":"Kivitelezési tippek","t":"Ellenőrizd a szorító és felhúzó kontrakciót; kerülje a has-, far- és adduktorizmok feszítését és a préselést. Gyakoroljon gyors és kitartott kontrakciót, a hétköznapokban is folytatható módon."},{"h":"Evidencia","t":"Stresszinkontinenciában a medencefenék-torna a konzervatív kezelés első választása. A hatás azon múlik, hogy a beteg kitartóan végzi-e."}]},"keypoints":["A medencefenék-izmokat „szorítsd és húzd fel” utasítással tanítsd","A préselés és a farizom feszítése kompenzáció, kerülendő","Köhögéskor, tüsszentéskor szivárgás: stresszinkontinencia","Késői terhességben a hosszú hanyatt fekvés vérnyomásesést okozhat","Hirtelen vizelési zavar, gátzsibbadás: azonnal orvoshoz"],"case":{"text":"38 éves nő, egy évvel a szülés után. Köhögéskor és tüsszentéskor vizelet szivárog. Felüléskor a has középvonala kidomborodik. Nincs hematuria, láz vagy gáttájéki érzészavar.","answer":"Stresszinkontinenciára és diastasis rectire gondolsz. Tanítsd a helyes medencefenék-kontrakciót és a préselés nélküli hasűri nyomáskontrollt. Kerüld az erős felülések hirtelen, sokszori ismétlését."},"questions":[{"level":"Alap","q":"Melyik a medencefenék fő izma?","options":["M. iliopsoas","M. gluteus maximus","M. levator ani","M. rectus femoris"],"answer":2,"exp":"A m. levator ani a m. coccygeusszal együtt alkotja a diaphragma pelvist, a medencefenék fő izma. A többi csípő körüli izom."},{"level":"Alap","q":"Melyik inkontinenciatípusban szivárog a vizelet, amikor köhögéskor vagy tüsszentéskor nő a hasűri nyomás?","options":["Urgencia-inkontinencia","Stresszinkontinencia","Túlfolyásos inkontinencia","Funkcionális inkontinencia"],"answer":1,"exp":"A stresszinkontinenciában a hasűri nyomás emelkedésekor elégtelen a húgycső zárása. Az urgencia-inkontinenciát erős vizelési inger kíséri."},{"level":"Középhaladó","q":"Hogyan tanítod helyesen a medencefenék-torna kontrakcióját?","options":["Visszatartott lélegzettel, hasprés","A farizmok erős összeszorítása","A has előrenyomása","Húgycső, hüvely, végbél szorítása és felhúzása"],"answer":3,"exp":"A medencefenék-izmokat szorító és felhúzó mozdulattal húzza össze. A préselés, a farizom feszítése és a has előrenyomása kompenzáció."},{"level":"Középhaladó","q":"Mire kell figyelni, ha késői terhességben hosszan hanyatt fekszik?","options":["Vena cava-szindróma (hanyattfekvéses hypotonia)","A diastasis recti javulása","A medencefenék-izmok hipertrófiája","Az inkontinencia megszűnése"],"answer":0,"exp":"Késői terhességben hanyatt fekvésben a méh nyomja a v. cava inferiort, és leeshet a vérnyomás. Fordítsd például oldalfekvésbe."},{"level":"Klinikai","q":"38 éves nő, egy évvel szülés után köhögésre vizelet szivárog, felüléskor kidomborodik a has középvonala. Mi a megfelelő beavatkozás?","options":["Naponta sok erős felülés","Medencefenék-torna és hasűri nyomáskontroll","A folyadékbevitel drasztikus csökkentése","Csak pihenés javaslata"],"answer":1,"exp":"Stresszinkontinencia és diastasis recti valószínű. A helyes medencefenék-kontrakcióval és a hasűri nyomás kontrolljával kezdj."},{"level":"Klinikai","q":"50-es éveiben járó nő derékfájással jár kezelésre. Hirtelen vizelési nehézségről és gátzsibbadásról számol be. Mit teszel?","options":["Fokozod a medencefenék-tornát","Kivársz a következő alkalomig","Azonnal értesíted az orvost","Ágyéki nyújtást végzel"],"answer":2,"exp":"A hirtelen vizelési zavar és a gáttájéki érzészavar cauda equina szindrómára utaló vörös zászló. Azonnal küldd orvoshoz."}],"seccion":"Kezelések és beavatkozások","grupo":"Mozgásterápia és szakterületek","icono":"🩺","mapa":"img/mapas/t51.jpg","fichas":[],"secuencias":[]},"52":{"id":52,"title":"Gyermek-fizioterápia","lead":"A fejlődésben lévő gyermek mozgásfejlődését, aktivitását és részvételét támogató terület. A normál fejlődés ismeretére épül, játékkal és a családdal együttműködve halad.","sheet":{"kind":"method","items":[{"h":"Cél","t":"A mozgásfejlődés elősegítése, az alapmozgások és a helyváltoztatás elsajátítása, a másodlagos károsodások (kontraktúra, deformitás) megelőzése, az otthoni, óvodai, iskolai részvétel bővítése, családtámogatás."},{"h":"Fő technikák és típusok","t":"Neurofejlesztő megközelítés, feladatorientált gyakorlás, játékos mozgás, testhelyzet-kezelés, ortézisek, ülést segítő eszközök és járókeret használata, a család betanítása."},{"h":"Javallatok","t":"Cerebralis paresis, fejlődési elmaradás, Down-szindróma, spina bifida, Duchenne-féle izomdystrophia, kis születési súlyú koraszülöttek, ortopédiai betegségek."},{"h":"Ellenjavallatok, óvatosság","t":"Spasztikus cerebralis paresisben fontos a csípő subluxatiójának, luxatiójának ellenőrzése. Izomdystrophiában kerüld a fáradtságot hagyó nagy terhelést. Figyelj az epilepsziás rohamokra és a fáradásra."},{"h":"Kivitelezési tippek","t":"Vizsgálathoz használd a GMFM-et, a GMFCS-t, a primitív reflexeket és a testtartási reakciókat. Élvezetes játékban gyakorolj, a mindennapi célokat oszd meg a családdal, hogy otthon is folytatható legyen."},{"h":"Evidencia","t":"A világos célokra épülő feladatorientált gyakorlást és a családdal együttműködő beavatkozást támogatja az evidencia. Az egyes technikáknál fontosabb a mindennapi gyakorlat."}]},"keypoints":["A fejtartás várható ideje 3–4 hónapos kor","A GMFCS a cerebralis paresis nagymozgásait 5 szintbe sorolja","Spasztikus CP-ben rendszeresen ellenőrizd a csípőficamot","Izomdystrophiában kerüld a fáradtságot hagyó nagy terhelést","A célt oszd meg a családdal, játékban gyakorolj"],"case":{"text":"5 éves fiú, spasztikus diplegia. Járókerettel közlekedik a lakásban, de feltűnő a lábujjhegyre lépés. A család szeretné, hogy „az óvodában a barátaival együtt tudjon közlekedni”.","answer":"A család kívánsága legyen a mindennapi cél: a járókeretes közlekedés gyakorlását kösd játékhoz és óvodai tevékenységhez. Előzd meg a m. triceps surae rövidülését, mérlegeld az ortézist, és ellenőrizd a csípőt. Ne ragaszkodj csak a normál fejlődés sorrendjéhez."},"questions":[{"level":"Alap","q":"Mikorra várható a fejtartás kialakulása?","options":["1 hónapos korra","3–4 hónapos korra","7–8 hónapos korra","12 hónapos korra"],"answer":1,"exp":"A fejtartás 3–4 hónapos kor körül várható. Ezt követi a fordulás, az ülés, a kapaszkodva állás és az önálló járás."},{"level":"Alap","q":"Melyik skála sorolja 5 szintbe a cerebralis paresises gyermek nagymozgás-képességét?","options":["GMFM","MRC","FIM","GMFCS"],"answer":3,"exp":"A GMFCS 5 szintbe osztályozza a nagymozgás-képességet. A GMFM pontszámmal méri a nagymozgás-funkciót."},{"level":"Középhaladó","q":"Milyen mozgást kerülj Duchenne-féle izomdystrophiában?","options":["Fáradtságot hagyó nagy terhelésű mozgást","ROM-gyakorlatot","Légzőgyakorlatot","Játékos mozgást"],"answer":0,"exp":"Az izomrostok könnyen sérülnek, ezért kerüld az erős fáradtságot hagyó nagy terhelést. A kontraktúra-megelőzés és a légzőtorna fontos."},{"level":"Középhaladó","q":"Spasztikus cerebralis paresisben melyik szövődményt fontos rendszeresen ellenőrizni?","options":["Elülső keresztszalag-szakadás","Rotátorköpeny-szakadás","A csípő subluxatiója, luxatiója","Bokaficam"],"answer":2,"exp":"A csípő körüli izmok spaszticitása és egyensúlyzavara miatt gyakori a csípő subluxatiója, luxatiója, ezért rendszeres ellenőrzés kell."},{"level":"Klinikai","q":"4 éves gyermek, spasztikus diplegia. Hogyan állítod fel helyesen a járás célját?","options":["A gyógytornász egyedül dönt","A családdal közösen, mindennapi célt tűzöl ki","Szigorúan csak a normál fejlődés sorrendje szerint","Játék nélkül, csak ismétléssel gyakoroltatsz"],"answer":1,"exp":"A célt oszd meg a családdal, és kösd konkrét otthoni, óvodai tevékenységhez. A játék segít, hogy a gyakorlás folytatható maradjon."},{"level":"Klinikai","q":"7 éves fiú, Duchenne-féle izomdystrophia, egyre nehezebben jár lépcsőn. Mi a helyes mozgásszemlélet?","options":["Fáradás nélküli aktivitás, kontraktúra-megelőzés","Nagy terhelésű excentrikus erősítés","Minden mozgás tiltása","Naponta a teljes kimerülésig járatni"],"answer":0,"exp":"A túlzott terhelés gyorsíthatja az izomkárosodást. Fáradtságot nem hagyó mértékben tartsd fenn az aktivitást, és folytasd a kontraktúra-megelőzést."}],"seccion":"Kezelések és beavatkozások","grupo":"Mozgásterápia és szakterületek","icono":"🩺","mapa":"img/mapas/t52.jpg","fichas":[],"secuencias":[]},"53":{"id":53,"title":"Idősek fizioterápiája","lead":"Középpontjában az öregedéssel járó funkcióvesztés, a frailty (gyengeség), a sarcopenia és az elesések kezelése áll. Vizsgálatra alapozva segítjük, hogy a mozgást biztonságosan folytassa, megőrizve önellátását és részvételét.","sheet":{"kind":"method","items":[{"h":"Cél","t":"Az ADL, az életvezetési funkciók és a részvétel megőrzése, javítása; az elesések megelőzése; a frailty és a sarcopenia megelőzése, javítása; az inaktivitási szindróma megelőzése; a gondozók tehermentesítése."},{"h":"Fő technikák és típusok","t":"Alsóvégtag- és törzserősítés, egyensúlygyakorlat, járásgyakorlás, kettős feladatos gyakorlás, felülés-, felállás- és átülésgyakorlás, segédeszköz-választás, a lakókörnyezet átalakítása."},{"h":"Javallatok","t":"Frailty, sarcopenia, korábbi elesés, törés vagy műtét után, krónikus betegség miatti inaktivitás, kórházi fekvés okozta dekondicionálódás, demenciával élők aktivitásának támogatása."},{"h":"Ellenjavallatok, óvatosság","t":"Figyelj az ortosztatikus hypotoniára, az osteoporosisos csigolyatörésre, a polifarmácia mellékhatásaira, a kiszáradásra, a sérülékeny bőrre és a kognitív hanyatlásra. Hirtelen fájdalom, tünetváltozás: orvos."},{"h":"Kivitelezési tippek","t":"Mérd fel TUG-gal, egylábon állással, székből felállással, járássebességgel, szorítóerővel, és tűzz ki egyéni célokat. A terhelést fokozatosan emeld, táplálkozással kombinálva ösztönözd a kitartást."},{"h":"Evidencia","t":"Az egyensúly- és erősítő elemeket tartalmazó mozgásprogramok hatékonyak az otthon élő idősek eleséseinek megelőzésében. Fontos, hogy tartósan végezhető legyen."}]},"keypoints":["A Fried-féle frailty-kritériumok közt szerepel a lassuló járás","Sarcopenia: csökkent izomtömeg és izomerő vagy fizikai funkció","Elesés-megelőzés: egyensúly és izomerő együtt","Tartós fekvés utáni mobilizálásnál figyelj az ortosztatikus hypotoniára","Osteoporosisban a hirtelen hátfájás csigolyatörésre gyanús"],"case":{"text":"82 éves nő, az elmúlt évben kétszer elesett. A TUG ideje megnyúlt, székből csak kézzel támaszkodva áll fel. Osteoporosis miatt kezelik, hátfájása nincs. Egyedül él, ritkán megy ki otthonról.","answer":"Magas az elesési kockázat. Fokozatosan kombinálj egyensúlygyakorlatot és alsóvégtag-erősítést, alakítsd át a lakókörnyezetet, és teremts alkalmat a kimozdulásra. Ne javasolj pihenést, és már az első napon ne adj nagy terhelést."},"questions":[{"level":"Alap","q":"Melyik szerepel a Fried-féle frailty-kritériumok között?","options":["Látásromlás","Vérnyomás-emelkedés","Lassuló járássebesség","Testmagasság növekedése"],"answer":2,"exp":"A Fried-kritériumok 5 eleme: fogyás, kimerültség, csökkent aktivitás, lassuló járás és csökkent izomerő (szorítóerő)."},{"level":"Alap","q":"Melyik az az állapot, amelyben az öregedés miatt csökken az izomtömeg, és romlik az izomerő vagy a fizikai funkció?","options":["Sarcopenia","Osteoporosis","Artrózis","Ortosztatikus hypotonia"],"answer":0,"exp":"A sarcopeniában az izomtömeg csökkenéséhez az izomerő vagy a fizikai funkció romlása társul. Az osteoporosis a csonttömeg csökkenése."},{"level":"Középhaladó","q":"Mit mér a TUG (Timed Up and Go teszt)?","options":["A szorítóerőt","Felállást, járást és fordulást tartalmazó mozgást","Csak a kognitív funkciót","A légzésfunkciót"],"answer":1,"exp":"A TUG azt az időt méri, amíg a beteg feláll a székből, elmegy, megfordul, visszajön és leül; a helyváltoztatást és az elesési kockázatot értékeli."},{"level":"Középhaladó","q":"Tartós fekvés után az idős beteg első ülésekor, felállásakor mire kell különösen figyelni?","options":["Rotátorköpeny-szakadás","Kihűlés","Ujjkontraktúra","Ortosztatikus hypotonia"],"answer":3,"exp":"Tartós fekvés után romlik a vérnyomás-szabályozás, felüléskor, álláskor könnyen esik a vérnyomás. Kövesd a tüneteket és a vérnyomást."},{"level":"Klinikai","q":"80-as éveiben járó nő, korábban elesett, a TUG ideje megnyúlt, az alsó végtag ereje csökkent. Mi a megfelelő beavatkozás?","options":["Egyensúlygyakorlat és alsóvégtag-erősítés együtt","Csak nyújtás","Pihenés javaslata","Első naptól maximális terhelésű erősítés"],"answer":0,"exp":"Az elesés megelőzésében az egyensúly- és erősítő elemeket kombináló mozgás hatékony. A terhelést fokozatosan emeld."},{"level":"Klinikai","q":"85 éves nő, osteoporosis. Enyhe fenékre esés után hirtelen erős hátfájás jelentkezik. Mit teszel?","options":["Fokozod a törzsflexiós gyakorlatokat","Hőkezelés mellett kivársz","Orvoshoz küldöd képalkotó vizsgálatra","Hátizom-nyújtást végzel"],"answer":2,"exp":"Osteoporosisos idősnél kisebb trauma utáni hirtelen hátfájás csigolya-kompressziós törésre gyanús. Ne folytasd a tornát, küldd orvoshoz."}],"seccion":"Kezelések és beavatkozások","grupo":"Mozgásterápia és szakterületek","icono":"🩺","mapa":"img/mapas/t53.jpg","fichas":[],"secuencias":[]},"54":{"id":54,"title":"Klinikai esetek","lead":"A klinikai gondolkodás menete: az anamnézisből hipotézist állítasz fel, vizsgálattal ellenőrzöd, az eredmények összegzése és értelmezése után kitűzöd a célt és a kezelést. Az újravizsgálattal folyamatosan felülvizsgálod.","sheet":{"kind":"basics","items":[{"h":"Anamnézis","t":"Kérdezd ki a fő panaszt, a kialakulás menetét, a fájdalom helyét és jellegét, a rontó és enyhítő tényezőket, a kórelőzményt, a gyógyszereket, az életkörülményeket, a kívánságokat. Szűrd a vörös zászlókat is."},{"h":"Hipotézisalkotás","t":"Az anamnézis alapján gyűjts össze több lehetséges okot, kórállapotot, és döntsd el, mit kell vizsgálattal ellenőrizni. Ne köteleződj el rögtön egyetlen magyarázat mellett."},{"h":"Vizsgálat","t":"Megtekintéssel, tapintással, ROM-méréssel, izomerő-vizsgálattal, speciális tesztekkel, neurológiai vizsgálattal, mozgáselemzéssel ellenőrizd a hipotézist. Figyeld az oldalkülönbséget és a reprodukálhatóságot."},{"h":"Összegzés és értelmezés","t":"Rendezd az eredményeket az ICF (FNO) keretében (testi funkciók, aktivitás, részvétel, környezet), és gondold végig a problémák összefüggéseit és sorrendjét."},{"h":"Célkitűzés","t":"A beteggel és a családdal közösen tűzz ki konkrét, mérhető, határidős rövid és hosszú távú célokat. A mindennapi élethelyzetekhez kötött célok a fontosak."},{"h":"Kezelés és újravizsgálat","t":"A célokhoz igazítva válaszd meg a beavatkozást, és ugyanazokkal a mutatókkal vizsgáld újra a változást. Ha nincs javulás, térj vissza a hipotézishez és a vizsgálathoz."}]},"keypoints":["Az anamnézis során mindig szűrd a vörös zászlókat","Állíts fel több hipotézist, és egyenként ellenőrizd vizsgálattal","A problémákat az ICF keretében rendezd","A cél legyen közös a beteggel, mérhető és határidős","Ha nincs javulás, a hipotézistől és a vizsgálattól kezdve gondold újra"],"case":{"text":"68 éves férfi, kétoldali térdartrózis. Járáskor fáj a jobb térde; a jobb m. quadriceps gyengült, a térd extenziója korlátozott. Kívánsága: „el akarok sétálni az unokámmal a közeli parkig”.","answer":"Rendezd a fájdalmat, az izomgyengeséget, a mozgáskorlátozottságot és a járás korlátozottságát, és határidővel tűzd ki célként a parkig sétálást. Végezz erősítő és ROM-gyakorlatokat, a fájdalom és a megtett távolság alapján vizsgáld újra. Ne csak a képalkotó lelet alapján dönts."},"questions":[{"level":"Alap","q":"A klinikai gondolkodás menetében mi következik az anamnézis után?","options":["A kezelés megkezdése","A hipotézis felállítása","A cél végleges kitűzése","Az elbocsátási tanácsadás"],"answer":1,"exp":"Az anamnézisből nyert információk alapján hipotézist állítasz fel az okról, kórállapotról, és kiválasztod az ezt ellenőrző vizsgálatokat."},{"level":"Alap","q":"Melyik a helyes célkitűzési mód?","options":["A gyógytornász egyedül dönt","Elvont megfogalmazás","Határidő nélkül","Mérhető, határidős cél"],"answer":3,"exp":"A cél legyen közös a beteggel és a családdal, konkrét, mérhető és határidős. Így az újravizsgálatkor megítélhető a változás."},{"level":"Középhaladó","q":"Az ICF szerint hová sorolod azt, hogy „nem tud lépcsőn járni”?","options":["Aktivitás","Részvétel","Testi funkciók és struktúrák","Környezeti tényezők"],"answer":0,"exp":"Az egyén által végzett cselekvés, például a lépcsőjárás, az „aktivitás” körébe tartozik. A társadalmi szerepekben való részvétel a „részvétel”."},{"level":"Középhaladó","q":"Mit teszel, ha a beavatkozás utáni újravizsgálatkor nincs javulás?","options":["Ugyanazt a kezelést folytatod","Kihagyod a vizsgálatot","Felülvizsgálod a hipotézist és a vizsgálatot","A beteg kevés erőfeszítésének tulajdonítod"],"answer":2,"exp":"Ha nincs javulás, vizsgáld felül, helyes volt-e a hipotézis és a vizsgálat, és gondold újra a kórállapot értelmezését és a beavatkozást."},{"level":"Klinikai","q":"50-es éveiben járó férfi: emeléskor a középső tartományban oldalsó vállfájdalom, Hawkins–Kennedy-teszt pozitív, passzív ROM ép. Mire gyanakszol?","options":["Fagyott váll","Subacromialis impingement","Cervicalis radiculopathia","Thoracic outlet szindróma"],"answer":1,"exp":"Az emelés középső tartományában jelentkező fájdalmas ív és a pozitív Hawkins–Kennedy-teszt subacromialis impingementre utal. Fagyott vállban a passzív ROM is korlátozott."},{"level":"Klinikai","q":"60-as éveiben járó nő, derékfájás; korábban daganatos betegsége volt, éjszakai fájdalma és tisztázatlan fogyása van. Mit teszel?","options":["Elkezded az ágyéki gerinc tornáját","Manipulációt végzel","Hőkezelés mellett kivársz","Tájékoztatod az orvost, kivizsgálást kérsz"],"answer":3,"exp":"A daganatos előzmény, az éjszakai fájdalom és a fogyás súlyos betegségre utaló vörös zászló. A kezelés előtt küldd orvoshoz."}],"seccion":"Kezelések és beavatkozások","grupo":"Klinikai esetek","icono":"🧩","mapa":"img/mapas/t54.jpg","fichas":[],"secuencias":[]}}};
